package com.codex.provisioner.core;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;

/**
 * Buy or make, for accounts that can trade: what a number of a supply's product costs bought
 * finished, against what it costs made, and the experience making it gives. Each ingredient is
 * itself bought or made, whichever is cheaper, so a clean herb is bought clean when cleaning
 * saves nothing.
 *
 * <p>Ingredients the player already holds are taken first, and are not priced as if bought:
 * they cost no coins, but using them gives up what they would sell for. So a quote has two
 * prices for making: the coins still to spend, and the sale value of what comes out of the bank.
 * Buy or make is judged on both together, since buying finished leaves those ingredients to sell.
 */
public final class Costing
{
	/** The Grand Exchange's tax on a sale: two per cent, at most five million coins an item. */
	static final int TAX_PERCENT = 2;
	static final long TAX_CAP = 5_000_000L;

	/** What filling a supply one way or the other costs. */
	public static final class Quote
	{
		private final long buy;
		private final long make;
		private final long fromBank;
		private final Map<Skill, Double> xp;

		Quote(long buy, long make, long fromBank, Map<Skill, Double> xp)
		{
			this.buy = buy;
			this.make = make;
			this.fromBank = fromBank;
			this.xp = xp;
		}

		/** Coins to buy the product finished, or -1 when it has no price. */
		public long getBuy()
		{
			return buy;
		}

		/**
		 * Coins still to spend on ingredients to make it, after what is held is used, or -1 when one of
		 * them can be neither bought nor made.
		 */
		public long getMake()
		{
			return make;
		}

		/** What the held ingredients making uses would sell for, after the exchange's tax. */
		public long getFromBank()
		{
			return fromBank;
		}

		/** Making's whole cost: the coins to spend and the held ingredients given up; -1 when unknown. */
		public long getMakeTotal()
		{
			return make < 0 ? -1 : make + fromBank;
		}

		/** Experience making it gives, by skill. */
		public Map<Skill, Double> getXp()
		{
			return xp;
		}

		public double totalXp()
		{
			double sum = 0;
			for (double v : xp.values())
			{
				sum += v;
			}
			return sum;
		}

		public boolean known()
		{
			return buy >= 0 && make >= 0;
		}

		/** Making is cheaper than buying, counting what the held ingredients would sell for. */
		public boolean makeIsCheaper()
		{
			return known() && getMakeTotal() < buy;
		}

		/** Coins making saves over buying, held ingredients counted at their sale value; negative when it costs more. */
		public long saving()
		{
			return known() ? buy - getMakeTotal() : 0;
		}

		/** Coins out of pocket making saves over buying, held ingredients counted as free. */
		public long cashSaving()
		{
			return known() ? buy - make : 0;
		}

		/**
		 * Coins each experience point costs when making costs more than buying, the way players
		 * judge a training method; 0 when making saves money or gives no experience.
		 */
		public double coinsPerXp()
		{
			double total = totalXp();
			return known() && getMakeTotal() > buy && total > 0 ? (getMakeTotal() - buy) / total : 0;
		}
	}

	/** What a branch of the recipe tree took: held items' sale value, the items taken and the experience. */
	private static final class Tally
	{
		long fromBank;
		final Map<Integer, Long> pool;
		final Map<Skill, Double> xp = new EnumMap<>(Skill.class);

		Tally(Map<Integer, Long> pool)
		{
			this.pool = pool;
		}
	}

	private Costing()
	{
	}

	/** Prices and makes {@code count} of {@code product} from bought ingredients alone. */
	public static Quote quote(int product, long count, Prices prices)
	{
		return quote(product, count, prices, new HashMap<>());
	}

	/**
	 * Prices and makes {@code count} of {@code product}, which is always made at the top.
	 *
	 * @param pool what is held and not yet spoken for; the ingredients this quote uses are taken out
	 *     of it, so quoting each supply in turn from one pool never counts a held item twice
	 */
	public static Quote quote(int product, long count, Prices prices, Map<Integer, Long> pool)
	{
		long price = prices.price(product);
		long buy = price > 0 ? price * count : -1;
		// Worked on a copy, so a quote that cannot be made takes nothing from the pool.
		Tally tally = new Tally(pool == null ? new HashMap<>() : new HashMap<>(pool));
		long make = count <= 0 ? 0 : made(Cookbook.recipe(product), count, prices, tally, 0);
		if (make >= 0 && pool != null)
		{
			pool.clear();
			pool.putAll(tally.pool);
		}
		return new Quote(buy, make, make < 0 ? 0 : tally.fromBank, tally.xp);
	}

	/** What one of an item would fetch sold on the exchange, after its tax. */
	static long saleValue(long price)
	{
		if (price <= 0)
		{
			return 0;
		}
		return price - Math.min(TAX_CAP, price * TAX_PERCENT / 100);
	}

	/**
	 * The cheapest way to have {@code count} of an item: what is held first, then bought, or made
	 * when that is cheaper. Returns the coins to spend, or -1 when it cannot be had.
	 */
	private static long cheapest(int item, long count, Prices prices, Tally tally, int depth)
	{
		long price = prices.price(item);
		long held = tally.pool.getOrDefault(item, 0L);
		long take = Math.min(count, Math.max(0, held));
		if (take > 0)
		{
			tally.pool.put(item, held - take);
			tally.fromBank += take * saleValue(price);
			count -= take;
		}
		if (count <= 0)
		{
			return 0;
		}
		long buy = price > 0 ? price * count : -1;
		Recipe r = Cookbook.recipe(item);
		if (r.isSource() || depth > 8)
		{
			return buy;
		}
		// Try making it on a copy of the pool, and keep that only if it wins.
		Tally trial = new Tally(new HashMap<>(tally.pool));
		long make = made(r, count, prices, trial, depth + 1);
		if (make >= 0 && (buy < 0 || make + trial.fromBank < buy))
		{
			tally.pool.clear();
			tally.pool.putAll(trial.pool);
			tally.fromBank += trial.fromBank;
			trial.xp.forEach((k, v) -> tally.xp.merge(k, v, Double::sum));
			return make;
		}
		return buy;
	}

	private static long made(Recipe r, long count, Prices prices, Tally tally, int depth)
	{
		long crafts = (count + r.getMakes() - 1) / r.getMakes();
		long total = 0;
		for (Map.Entry<Integer, Integer> in : r.getInputs().entrySet())
		{
			long c = cheapest(in.getKey(), crafts * in.getValue(), prices, tally, depth);
			if (c < 0)
			{
				return -1;
			}
			total += c;
		}
		if (r.getXpSkill() != null && r.getXp() > 0)
		{
			tally.xp.merge(r.getXpSkill(), crafts * r.getXp(), Double::sum);
		}
		return total;
	}
}

package com.codex.provisioner.core;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

/**
 * Grimy herbs to grow, turned into herb runs: how many runs the patches take, how many seeds
 * that plants, and how long the herbs take to grow between runs. Yields depend on compost,
 * secateurs, diaries and luck, so the herbs one patch gives is the player's to set; the plan is
 * an estimate, never a promise.
 */
public final class HerbRuns
{
	/** Herbs take four 20-minute stages to grow. */
	public static final long GROW_MS = 80 * 60_000L;

	private static final Map<Integer, Integer> SEEDS = new HashMap<>();

	static
	{
		SEEDS.put(ItemID.UNIDENTIFIED_RANARR, ItemID.RANARR_SEED);
		SEEDS.put(ItemID.UNIDENTIFIED_TOADFLAX, ItemID.TOADFLAX_SEED);
		SEEDS.put(ItemID.UNIDENTIFIED_IRIT, ItemID.IRIT_SEED);
		SEEDS.put(ItemID.UNIDENTIFIED_AVANTOE, ItemID.AVANTOE_SEED);
		SEEDS.put(ItemID.UNIDENTIFIED_KWUARM, ItemID.KWUARM_SEED);
		SEEDS.put(ItemID.UNIDENTIFIED_SNAPDRAGON, ItemID.SNAPDRAGON_SEED);
		SEEDS.put(ItemID.UNIDENTIFIED_CADANTINE, ItemID.CADANTINE_SEED);
		SEEDS.put(ItemID.UNIDENTIFIED_LANTADYME, ItemID.LANTADYME_SEED);
		SEEDS.put(ItemID.UNIDENTIFIED_DWARF_WEED, ItemID.DWARF_WEED_SEED);
		SEEDS.put(ItemID.UNIDENTIFIED_TORSTOL, ItemID.TORSTOL_SEED);
	}

	private HerbRuns()
	{
	}

	/** The seed a grimy herb grows from, or 0 when it is not a herb grown in herb patches. */
	public static int seed(int grimy)
	{
		return SEEDS.getOrDefault(grimy, 0);
	}

	/** The herb runs for one grimy herb. */
	public static final class Plan
	{
		private final int seed;
		private final long runs;
		private final long seeds;
		private final long seedsHeld;
		private final int patches;

		Plan(int seed, long runs, long seeds, long seedsHeld, int patches)
		{
			this.seed = seed;
			this.runs = runs;
			this.seeds = seeds;
			this.seedsHeld = seedsHeld;
			this.patches = patches;
		}

		public int getSeed()
		{
			return seed;
		}

		/** Herb runs, every patch planted with this herb. */
		public long getRuns()
		{
			return runs;
		}

		/** Seeds those runs plant; the last run may need fewer than every patch. */
		public long getSeeds()
		{
			return seeds;
		}

		public long getSeedsHeld()
		{
			return seedsHeld;
		}

		public long getSeedsShort()
		{
			return Math.max(0, seeds - seedsHeld);
		}

		public int getPatches()
		{
			return patches;
		}

		/** Patches the fullest run plants: every patch, or fewer when the herbs need fewer seeds. */
		public int getPatchesUsed()
		{
			return (int) Math.min(patches, seeds);
		}

		/** The soonest the last run can be picked, from planting the first: one growth between runs. */
		public long getSoonestMs()
		{
			return runs * GROW_MS;
		}
	}

	/**
	 * @param herbs grimy herbs still to gather
	 * @param patches herb patches the player runs; 0 or less plans nothing
	 * @param perPatch herbs one patch gives on average
	 * @param held what is held, for the seeds
	 * @return the plan, or null when the item is not a herb, nothing is left, or no patches are run
	 */
	public static Plan plan(int grimy, long herbs, int patches, double perPatch, Map<Integer, Long> held)
	{
		int seed = seed(grimy);
		if (seed == 0 || herbs <= 0 || patches <= 0 || perPatch <= 0)
		{
			return null;
		}
		long seeds = (long) Math.ceil(herbs / perPatch - 1e-9);
		long runs = (seeds + patches - 1) / patches;
		return new Plan(seed, runs, seeds, held.getOrDefault(seed, 0L), patches);
	}
}

package com.codex.provisioner.core;

import com.google.gson.JsonElement;
import java.math.BigDecimal;

/** Careful reading of numbers from saves this plugin did not write, or that may be damaged. */
final class Json
{
	private static final BigDecimal MIN = BigDecimal.valueOf(Long.MIN_VALUE);
	private static final BigDecimal MAX = BigDecimal.valueOf(Long.MAX_VALUE);

	private Json()
	{
	}

	/**
	 * A whole number, held to what a long can hold and rounded down from a fraction; null when
	 * the value is not a number at all. Gson's own reading of a number too big for a long gives
	 * back whatever its low bits happen to be, which can be any count at all.
	 */
	static Long whole(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		try
		{
			BigDecimal d = e.getAsBigDecimal();
			return d.compareTo(MAX) >= 0 ? Long.MAX_VALUE : d.compareTo(MIN) <= 0 ? Long.MIN_VALUE : d.longValue();
		}
		catch (NumberFormatException | ArithmeticException ex)
		{
			return null;
		}
	}

	/** A count of items: at least 0 and no more than one stack can hold. */
	static long count(long n)
	{
		return Math.max(0, Math.min(Integer.MAX_VALUE, n));
	}
}

package com.codex.provisioner.core;

import java.util.ArrayList;
import java.util.List;

/**
 * What a trip to one piece of content takes. Presets ship with the plugin and start from typical
 * numbers; kits the player saves are taken from what they actually carried.
 */
public class Kit
{
	private String id;
	private String name;
	private List<Need> needs = new ArrayList<>();
	private transient boolean preset;

	public Kit()
	{
	}

	public Kit(String id, String name, List<Need> needs, boolean preset)
	{
		this.id = id;
		this.name = name;
		this.needs = new ArrayList<>(needs);
		this.preset = preset;
	}

	public String getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	public List<Need> getNeeds()
	{
		return needs;
	}

	public boolean isPreset()
	{
		return preset;
	}

	public Need need(String supply)
	{
		for (Need n : needs)
		{
			if (n.getSupply().equals(supply))
			{
				return n;
			}
		}
		return null;
	}

	/** Drops a supply from a saved kit, for things that were carried but are not supplies. */
	public boolean remove(String supply)
	{
		return needs.removeIf(n -> n.getSupply().equals(supply));
	}

	/** Restores what saved data can leave out. */
	Kit repair()
	{
		if (needs == null)
		{
			needs = new ArrayList<>();
		}
		needs.removeIf(n -> n == null || n.getSupply() == null || Supplies.get(n.getSupply()) == null || n.getPerTrip() < 0);
		return this;
	}
}

package com.codex.provisioner.core;

import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntPredicate;

/**
 * How a step splits into bank trips: what to take out of the bank for each inventory, and how
 * many inventories the step has left. A mix of an unfinished potion and its secondary fits
 * fourteen of each; cleaning herbs fits twenty-eight; a tool takes a slot, and a stack, such as
 * Zulrah's scales or the bait for karambwans, takes one however big it is.
 *
 * <p>An inventory has to hold the inputs before the work and what is made after it, so whichever
 * of the two takes more room sets how many goes fit.
 */
public final class Loads
{
	public static final int SLOTS = 28;

	private final long perLoad;
	private final long loads;
	private final Map<Integer, Long> withdraw;

	private Loads(long perLoad, long loads, Map<Integer, Long> withdraw)
	{
		this.perLoad = perLoad;
		this.loads = loads;
		this.withdraw = withdraw;
	}

	/**
	 * @param stackable whether an item stacks in one slot
	 * @return the split, or null for a step with no inventories to fill: done, farmed, bought, or
	 *     a stock to bring as it is
	 */
	public static Loads of(Step step, IntPredicate stackable)
	{
		Recipe r = step.getRecipe();
		Verb verb = r.getVerb();
		if (step.getState() == Step.State.DONE || step.getNet() <= 0 || verb == Verb.BUY || verb == Verb.STOCK
			|| (r.isSource() && verb != Verb.CATCH))
		{
			return null;
		}
		long crafts = (step.getNet() + r.getMakes() - 1) / r.getMakes();
		int fixed = r.getTools().size();
		int in = 0;
		for (Map.Entry<Integer, Integer> e : r.getInputs().entrySet())
		{
			if (stackable.test(e.getKey()))
			{
				fixed++;
			}
			else
			{
				in += e.getValue();
			}
		}
		boolean stackedOutput = stackable.test(r.getOutput());
		int out = stackedOutput ? 0 : r.getMakes();
		if (stackedOutput)
		{
			fixed++;
		}
		int room = SLOTS - fixed;
		int each = Math.max(in, out);
		if (room <= 0)
		{
			return null;
		}
		long perLoad = each == 0 ? crafts : Math.min(crafts, room / each);
		if (perLoad <= 0)
		{
			return null;
		}
		long loads = (crafts + perLoad - 1) / perLoad;
		Map<Integer, Long> withdraw = new LinkedHashMap<>();
		for (Map.Entry<Integer, Integer> e : r.getInputs().entrySet())
		{
			withdraw.put(e.getKey(), perLoad * e.getValue());
		}
		return new Loads(perLoad * r.getMakes(), loads, Collections.unmodifiableMap(withdraw));
	}

	/**
	 * What is still to come out of the bank for the inventory in hand: one load's inputs and one of
	 * each tool, less what is already carried, so the marks go as the items come out.
	 *
	 * @param loads the split, or null to mark only the tools
	 * @param carried the inventory and worn items, or null for none
	 */
	public static Map<Integer, Long> toTake(Loads loads, Collection<Integer> tools, Map<Integer, Long> carried)
	{
		Map<Integer, Long> have = carried == null ? Collections.emptyMap() : carried;
		Map<Integer, Long> take = new LinkedHashMap<>();
		if (loads != null)
		{
			loads.withdraw.forEach((item, n) ->
			{
				long left = n - have.getOrDefault(item, 0L);
				if (left > 0)
				{
					take.put(item, left);
				}
			});
		}
		for (int tool : tools)
		{
			if (have.getOrDefault(tool, 0L) <= 0)
			{
				take.putIfAbsent(tool, 1L);
			}
		}
		return take;
	}

	/** Items one full inventory makes or catches. */
	public long getPerLoad()
	{
		return perLoad;
	}

	/** Inventories still to go for the whole step, the one in hand included. */
	public long getLoads()
	{
		return loads;
	}

	/** What to take out of the bank for one full inventory, by item, in recipe order; tools aside. */
	public Map<Integer, Long> getWithdraw()
	{
		return withdraw;
	}
}

