	}
}

package com.codex.provisioner.core;

/** Where the Provisioner learns what an item costs on the Grand Exchange today. */
public interface Prices
{
	/** @return the item's price in coins, or 0 or less when it has none */
	long price(int itemId);
}

package com.codex.provisioner.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.IOException;
import java.io.StringReader;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

/**
 * Everything the Provisioner keeps for one account: the bank as last seen, the kit and number of
 * trips being provisioned for, the product picked for each supply, the player's levels as last
 * seen, and how much each step had to go at its most, so progress bars have a fixed end.
 */
public class Provisions
{
	public static final int DEFAULT_TRIPS = 10;

	private Map<Integer, Long> bank = new HashMap<>();
	private long bankSeen;
	/** The bank as last seen came from Codex Bank Steward rather than the Provisioner's own look. */
	private boolean bankShared;
	private String kit;
	private int trips = DEFAULT_TRIPS;
	private Map<String, Integer> choices = new HashMap<>();
	private Map<Integer, Long> baselines = new HashMap<>();
	private Map<String, Integer> levels = new HashMap<>();
	/** Experience in each skill as last seen, for what the chain trains. */
	private Map<String, Long> xp = new HashMap<>();
	/** Potion doses in the bank's potion storage, by each potion's 1-dose item; null until first read. */
	private Map<Integer, Long> stored;
	/** Supplies bought finished on the Grand Exchange rather than made. */
	private Set<String> bought = new HashSet<>();
	/** An iron account, remembered so the panel stays right while logged out. */
	private boolean iron;
	private Pace pace = new Pace();
	private transient boolean baselinesChanged;

	public Map<Integer, Long> getBank()
	{
		return bank;
	}

	public long getBankSeen()
	{
		return bankSeen;
	}

	public boolean hasBank()
	{
		return bankSeen > 0;
	}

	public void observeBank(Map<Integer, Long> items, long now)
	{
		bank = new HashMap<>(items);
		bankSeen = now;
		bankShared = false;
	}

	/**
	 * Takes the bank another Codex plugin saw, when it saw it later than this one did. A minute's
	 * grace keeps the two from trading the same look back and forth when both saw it.
	 *
	 * @return true when it was taken
	 */
	public boolean adoptShared(SharedBank shared)
	{
		if (shared == null || shared.getSavedAt() <= bankSeen + 60_000)
		{
			return false;
		}
		bank = new HashMap<>(shared.getItems());
		bankSeen = shared.getSavedAt();
		bankShared = true;
		return true;
	}

	/** Whether the bank as last seen is the one Codex Bank Steward shared. */
	public boolean isBankShared()
	{
		return bankShared;
	}

	/** The bank as last seen, its potion storage, and what is carried, together. */
	public Map<Integer, Long> holdings(Map<Integer, Long> carried)
	{
		return holdings(carried, null);
	}

	/**
	 * @param fallback potion storage to count until the Provisioner has read it itself, such as
	 *     what Codex Quartermaster last saw; null for none
	 */
	public Map<Integer, Long> holdings(Map<Integer, Long> carried, Map<Integer, Long> fallback)
	{
		Map<Integer, Long> all = new HashMap<>(bank);
		carried.forEach((id, q) -> all.merge(id, q, Long::sum));
		Map<Integer, Long> doses = stored != null ? stored : fallback;
		if (doses != null)
		{
			// Filed under the 1-dose potion, one each, so they count as doses toward their supply.
			doses.forEach((id, q) -> all.merge(id, q, Long::sum));
		}
		return all;
	}

	/** @return true when the doses in potion storage changed */
	public boolean observeStorage(Map<Integer, Long> doses)
	{
		if (doses.equals(stored))
		{
			return false;
		}
		stored = new HashMap<>(doses);
		return true;
	}

	public Map<Integer, Long> getStored()
	{
		return stored;
	}

	public boolean isIron()
	{
		return iron;
	}

	public void setIron(boolean iron)
	{
		this.iron = iron;
	}

	/** Supplies bought finished; an iron account buys none, whatever was picked before. */
	public Set<String> getBought()
	{
		return iron ? Collections.emptySet() : bought;
	}

	/** Buys a supply finished instead of making it, or goes back to making it. */
	public void setBought(String supply, boolean buy)
	{
		if (buy ? bought.add(supply) : bought.remove(supply))
		{
			baselines.clear();
		}
	}

	public Pace getPace()
	{
		return pace;
	}

	public String getKit()
	{
		return kit;
	}

	/** Picks the kit to provision for; a new kit starts its progress afresh. */
	public void setKit(String id)
	{
		if (id != null && !id.equals(kit))
		{
			kit = id;
			baselines.clear();
		}
	}

	public int getTrips()
	{
		return trips;
	}

	public void setTrips(int value)
	{
		value = Math.max(1, Math.min(1000, value));
		if (value != trips)
		{
			trips = value;
			baselines.clear();
		}
	}

	public Map<String, Integer> getChoices()
	{
		return choices;
	}

	public void choose(String supply, int product)
	{
		Integer old = choices.put(supply, product);
		if (old == null || old != product)
		{
			baselines.clear();
		}
	}

	/** Starts every progress bar again from what is still to do. */
	public void restart()
	{
		baselines.clear();
	}

	public Map<Skill, Integer> levels()
	{
		Map<Skill, Integer> out = new HashMap<>();
		for (Map.Entry<String, Integer> e : levels.entrySet())
		{
			try
			{
				out.put(Skill.valueOf(e.getKey()), e.getValue());
			}
			catch (IllegalArgumentException ignored)
			{
				// A skill from a newer client; not one any recipe asks for.
			}
		}
		return out;
	}

	/** @return true when a level changed */
	public boolean observeLevels(Map<Skill, Integer> seen)
	{
		boolean changed = false;
		for (Map.Entry<Skill, Integer> e : seen.entrySet())
		{
			if (e.getValue() == null || e.getValue() <= 0)
			{
				// Not a real reading: a skill not sent yet, as during a world hop, would lock every step.
				continue;
			}
			Integer old = levels.put(e.getKey().name(), e.getValue());
			changed |= old == null || !old.equals(e.getValue());
		}
		return changed;
	}

	public Map<Skill, Long> xp()
	{
		Map<Skill, Long> out = new HashMap<>();
		for (Map.Entry<String, Long> e : xp.entrySet())
		{
			try
			{
				out.put(Skill.valueOf(e.getKey()), e.getValue());
			}
			catch (IllegalArgumentException ignored)
			{
				// A skill from a newer client.
			}
		}
		return out;
	}

	/**
	 * Takes in experience as the game sends it. A reading of nothing for a skill already known is
	 * a skill the game has not sent yet, not a real one, and is passed over.
	 *
	 * @return true when anything changed
	 */
	public boolean observeXp(Map<Skill, Long> seen)
	{
		boolean changed = false;
		for (Map.Entry<Skill, Long> e : seen.entrySet())
		{
			if (e.getValue() <= 0 && xp.containsKey(e.getKey().name()))
			{
				continue;
			}
			Long old = xp.put(e.getKey().name(), e.getValue());
			changed |= old == null || !old.equals(e.getValue());
		}
		return changed;
	}

	/** Works out the chain and remembers the most each step has had to go. */
	public Chain plan(Kit kit, Map<String, Double> perTrip, Map<Integer, Long> carried)
	{
		return plan(kit, perTrip, carried, null);
	}

	/** @param fallback potion storage to count until it has been read here, or null */
	public Chain plan(Kit kit, Map<String, Double> perTrip, Map<Integer, Long> carried, Map<Integer, Long> fallback)
	{
		Chain chain = Chain.build(kit, perTrip, trips, choices, getBought(), holdings(carried, fallback), levels(), baselines);
		Map<Integer, Long> next = new HashMap<>();
		for (Step s : chain.getSteps())
		{
			if (s.getBaseline() > 0)
			{
				next.put(s.getItem(), s.getBaseline());
			}
		}
		baselinesChanged = !next.equals(baselines);
		baselines = next;
		return chain;
	}

	/** Item counts with nothing below one or past a stack. */
	private static Map<Integer, Long> counts(Map<Integer, Long> in)
	{
		Map<Integer, Long> out = new HashMap<>();
		in.forEach((id, q) ->
		{
			if (id != null && id > 0 && q != null && q > 0)
			{
				out.put(id, Json.count(q));
			}
		});
		return out;
	}

	/** Whether the last plan moved a progress bar's end, which is worth saving. */
	public boolean baselinesChanged()
	{
		return baselinesChanged;
	}

	/** A saved provisions entry as read back: what could be kept, and whether anything was left out. */
	public static final class Loaded
	{
		/** What was read; fresh provisions when nothing could be. Never null. */
		public final Provisions provisions;
		/** True when the save was not read whole, so it is worth setting aside as it was. */
		public final boolean damaged;

		Loaded(Provisions provisions, boolean damaged)
		{
			this.provisions = provisions;
			this.damaged = damaged;
		}
	}

	/**
	 * Reads the saved provisions. A save that reads whole is repaired and kept; one that does not
	 * (a figure of the wrong kind or too big for its field, one bad entry in the bank, a save cut
	 * short) keeps every field and every entry that still reads, so one damaged figure never
	 * costs the bank, the choices or the levels.
	 *
	 * @param now the time now; a bank seen later than this is taken as seen now
	 */
	public static Loaded read(Gson gson, String saved, long now)
	{
		if (saved == null || saved.trim().isEmpty())
		{
			return new Loaded(new Provisions(), false);
		}
		try
		{
			Provisions whole = gson.fromJson(saved, Provisions.class);
			if (whole != null)
			{
				// It read, but a field a later version keeps would be dropped by the next save.
				whole.repair(now);
				return new Loaded(whole, Unread.any(gson, saved, whole));
			}
		}
		catch (RuntimeException e)
		{
			// Read it field by field below.
		}
		Provisions p = new Provisions();
		JsonReader in = new JsonReader(new StringReader(saved));
		in.setLenient(true);
		try
		{
			if (in.peek() == JsonToken.BEGIN_OBJECT)
			{
				in.beginObject();
				while (in.hasNext())
				{
					String name = in.nextName();
					p.field(gson, name, gson.fromJson(in, JsonElement.class));
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			// A save cut short keeps every field before the cut.
		}
		return new Loaded(p.repair(now), true);
	}

	/** Sets one field from a damaged save, keeping each entry of it that reads. */
	private void field(Gson gson, String name, JsonElement value)
	{
		try
		{
			switch (name)
			{
				case "bank":
					bank = items(value);
					break;
				case "baselines":
					baselines = items(value);
					break;
				case "stored":
					stored = items(value);
					break;
				case "bankSeen":
					Long seen = Json.whole(value);
					bankSeen = seen == null ? 0 : seen;
					break;
				case "trips":
					Long t = Json.whole(value);
					trips = t == null ? DEFAULT_TRIPS : (int) Math.max(1, Math.min(1000, t));
					break;
				case "kit":
					kit = value.isJsonPrimitive() ? value.getAsString() : null;
					break;
				case "bankShared":
					bankShared = value.isJsonPrimitive() && value.getAsBoolean();
					break;
				case "iron":
					iron = value.isJsonPrimitive() && value.getAsBoolean();
					break;
				case "choices":
				case "levels":
					Map<String, Integer> small = new HashMap<>();
					named(value).forEach((k, v) -> small.put(k, (int) Math.max(Integer.MIN_VALUE, Math.min(Integer.MAX_VALUE, v))));
					if ("choices".equals(name))
					{
						choices = small;
					}
					else
					{
						levels = small;
					}
					break;
				case "xp":
					xp = named(value);
					break;
				case "bought":
					bought = new HashSet<>();
					if (value.isJsonArray())
					{
						value.getAsJsonArray().forEach(e -> bought.add(e.isJsonPrimitive() ? e.getAsString() : null));
					}
					break;
				case "pace":
					pace = gson.fromJson(value, Pace.class);
					break;
				default:
					// A field a later version keeps, unknown here.
			}
		}
		catch (RuntimeException e)
		{
			// This field is lost; the rest are not.
		}
	}

	/** Item counts by id, every entry that reads. */
	private static Map<Integer, Long> items(JsonElement value)
	{
		Map<Integer, Long> out = new HashMap<>();
		named(value).forEach((k, v) ->
		{
			try
			{
				out.put(Integer.parseInt(k), v);
			}
			catch (NumberFormatException ignored)
			{
				// Not an item id.
			}
		});
		return out;
	}

	/** Whole numbers by name, every entry that reads. */
	private static Map<String, Long> named(JsonElement value)
	{
		Map<String, Long> out = new HashMap<>();
		if (value != null && value.isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : value.getAsJsonObject().entrySet())
			{
				Long n = Json.whole(e.getValue());
				if (n != null)
				{
					out.put(e.getKey(), n);
				}
			}
		}
		return out;
	}

	/** Restores what saved data can leave out. */
	public Provisions repair()
	{
		return repair(Long.MAX_VALUE);
	}

	/**
	 * Restores what saved data can leave out, and sets right what damage can put in: counts below
	 * zero or past a stack, levels and experience past the game's own, a bank seen after now.
	 */
	Provisions repair(long now)
	{
		if (bank == null)
		{
			bank = new HashMap<>();
		}
		if (choices == null)
		{
			choices = new HashMap<>();
		}
		if (baselines == null)
		{
			baselines = new HashMap<>();
		}
		if (levels == null)
		{
			levels = new HashMap<>();
		}
		if (xp == null)
		{
			xp = new HashMap<>();
		}
		if (bought == null)
		{
			bought = new HashSet<>();
		}
		pace = pace == null ? new Pace() : pace.repair();
		if (trips <= 0)
		{
			trips = DEFAULT_TRIPS;
		}
		trips = Math.min(1000, trips);
		bank = counts(bank);
		baselines = counts(baselines);
		stored = stored == null ? null : counts(stored);
		choices.entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null);
		levels.entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null || e.getValue() <= 0);
		levels.replaceAll((k, v) -> Math.min(Experience.MAX_VIRT_LEVEL, v));
		xp.entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null || e.getValue() < 0);
		xp.replaceAll((k, v) -> Math.min(Experience.MAX_SKILL_XP, v));
		bought.removeIf(b -> b == null || b.isEmpty());
		kit = kit == null || kit.isEmpty() ? null : kit;
		bankSeen = Math.max(0, Math.min(now, bankSeen));
		return this;
	}
}

package com.codex.provisioner.core;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * What Codex Quartermaster keeps for the account: the kits the player saved, the kit they last
 * chose, and what each kit has been measured using on real trips. The Provisioner only reads it;
 * without Quartermaster it works from the presets alone.
 *
 * <p>Quartermaster publishes its kits in a documented shape under {@link #KITS_KEY}, which only
 * grows. Its own {@link #QUARTERS_KEY} entry may change between versions, so it is read only for
 * what the published one leaves out (how many trips were measured, and the potion storage), and
 * on its own only when Quartermaster is too old to publish.
 */
public class Quarters
{
	/** Quartermaster's config group, read and never written. */
	public static final String GROUP = "codexquartermaster";
	/** The published kits: {"version":1,"active":id,"kits":[{id,name,preset,needs:[{supply,perTrip,measured}]}]}. */
	public static final String KITS_KEY = "kitsV1";
	/** Quartermaster's own saved state. */
	public static final String QUARTERS_KEY = "quarters";

	/**
	 * The most of a supply one trip is taken to use. A bigger figure is damage, and read as it
	 * was it overflowed into a kit needing less than nothing.
	 */
	static final double MOST = 1_000_000;

	/** Trips before Quartermaster trusts its measured amounts; the Provisioner does the same. */
	static final int TRUSTED = 2;

	private List<Kit> kits = new ArrayList<>();
	private String active;
	private Map<String, Usage> usage;
	/** Potion storage doses as Quartermaster last read them, by 1-dose item. */
	private Map<Integer, Long> stored;

	static final class Usage
	{
		private int trips;
		private Map<String, Double> perTrip;
	}

	public static Quarters none()
	{
		return new Quarters();
	}

	/**
	 * Reads what Quartermaster saved, the published kits first.
	 *
	 * @param kitsV1 the {@link #KITS_KEY} entry, or null
	 * @param quarters the {@link #QUARTERS_KEY} entry, or null
	 */
	public static Quarters read(Gson gson, String kitsV1, String quarters)
	{
		Quarters old = null;
		try
		{
			old = quarters == null || quarters.trim().isEmpty() ? null : gson.fromJson(quarters, Quarters.class);
		}
		catch (RuntimeException e)
		{
			// Quartermaster's own entry may change shape between versions; read as none.
			old = null;
		}
		JsonObject book = object(gson, kitsV1);
		if (book == null || !(book.get("kits") instanceof JsonArray))
		{
			return old == null ? none() : old;
		}
		Quarters q = new Quarters();
		// Older Quartermasters published the preset they showed on a fresh install as if it were
		// chosen; their own entry names only a kit the player really picked, so it has the say.
		q.active = old != null ? old.active : string(book, "active");
		q.stored = old == null ? null : old.stored;
		q.usage = new HashMap<>();
		for (JsonElement e : book.getAsJsonArray("kits"))
		{
			if (!e.isJsonObject())
			{
				continue;
			}
			JsonObject kit = e.getAsJsonObject();
			String id = string(kit, "id");
			String name = string(kit, "name");
			if (id == null || name == null)
			{
				continue;
			}
			List<Need> needs = new ArrayList<>();
			Map<String, Double> measured = new HashMap<>();
			JsonElement lines = kit.get("needs");
			if (lines instanceof JsonArray)
			{
				for (JsonElement l : lines.getAsJsonArray())
				{
					if (!l.isJsonObject())
					{
						continue;
					}
					JsonObject line = l.getAsJsonObject();
					String supply = string(line, "supply");
					Double perTrip = number(line, "perTrip");
					if (supply == null || perTrip == null)
					{
						continue;
					}
					needs.add(new Need(supply, (int) Math.round(Math.max(0, Math.min(MOST, perTrip)))));
					Double used = number(line, "measured");
					if (used != null && used >= 0 && used <= MOST)
					{
						measured.put(supply, used);
					}
				}
			}
			boolean preset = kit.get("preset") != null && kit.get("preset").isJsonPrimitive() && kit.get("preset").getAsBoolean();
			if (!preset)
			{
				q.kits.add(new Kit(id, name, needs, false));
			}
			if (!measured.isEmpty())
			{
				// Published only once trusted; the trip count itself is Quartermaster's own detail.
				Usage u = new Usage();
				u.trips = Math.max(TRUSTED, old == null ? 0 : old.measuredTrips(id));
				u.perTrip = measured;
				q.usage.put(id, u);
			}
		}
		return q;
	}

	private static JsonObject object(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = gson.fromJson(json, JsonElement.class);
			return root != null && root.isJsonObject() ? root.getAsJsonObject() : null;
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return null;
		}
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isString() ? e.getAsString() : null;
	}

	private static Double number(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		double d = e.getAsDouble();
		return Double.isNaN(d) || Double.isInfinite(d) ? null : d;
	}

	/** The player's own kits, then the presets. */
	public List<Kit> allKits()
	{
		List<Kit> all = new ArrayList<>();
		if (kits != null)
		{
			for (Kit k : kits)
			{
				if (k != null && k.getId() != null && k.getName() != null)
				{
					all.add(k.repair());
				}
			}
		}
		all.addAll(Presets.all());
		return all;
	}

	public boolean hasSavedKits()
	{
		return kits != null && !kits.isEmpty();
	}

	/** The kit last chosen in Quartermaster, or null. */
	public String getActive()
	{
		return active;
	}

	/** What a kit has really used a trip, once measured over enough trips; empty otherwise. */
	public Map<String, Double> measured(String kitId)
	{
		Usage u = usage == null ? null : usage.get(kitId);
		if (u == null || u.trips < TRUSTED || u.perTrip == null)
		{
			return Collections.emptyMap();
		}
		// Quartermaster's own entry is read as it stands, so a damaged figure is left out here.
		Map<String, Double> out = new HashMap<>();
		u.perTrip.forEach((supply, used) ->
		{
			if (supply != null && used != null && used >= 0 && used <= MOST)
			{
				out.put(supply, used);
			}
		});
		return Collections.unmodifiableMap(out);
	}

	/** The potion storage as Quartermaster last read it, or null without Quartermaster. */
	public Map<Integer, Long> getStored()
	{
		if (stored == null)
		{
			return null;
		}
		Map<Integer, Long> out = new HashMap<>();
		stored.forEach((id, doses) ->
		{
			if (id != null && doses != null && doses > 0)
			{
				out.put(id, Json.count(doses));
			}
		});
		return out;
	}

	public int measuredTrips(String kitId)
	{
		Usage u = usage == null ? null : usage.get(kitId);
		return u == null ? 0 : u.trips;
	}
}

package com.codex.provisioner.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;

/**
 * How one item comes to be: what goes in, how many come out, the levels it asks for, any tools
 * that are not used up, and a line on where or how to do it. An item with nothing going in is
 * gathered, caught or bought, which is where a chain starts.
 */
public final class Recipe
{
	/** Buying a stack is a few seconds at the exchange, whatever its size. */
	static final int BOUGHT_RATE = 100_000;

	private final int output;
	private final Verb verb;
	private int makes = 1;
	private final Map<Integer, Integer> inputs = new LinkedHashMap<>();
	private final List<Req> reqs = new ArrayList<>();
	private final List<Integer> tools = new ArrayList<>();
	private String how;
	private Skill xpSkill;
	private double xp;
	private int rate;

	Recipe(Verb verb, int output)
	{
		this.verb = verb;
		this.output = output;
	}

	/** A supply with nothing to make, such as a teleport tablet a kit carries as it is. */
	static Recipe stock(int itemId)
	{
		return new Recipe(Verb.STOCK, itemId).how("Bring these as they are; there is nothing to make.");
	}

	/** A finished supply bought whole on the Grand Exchange instead of made. */
	static Recipe buy(int itemId)
	{
		return new Recipe(Verb.BUY, itemId).how("Buy them on the Grand Exchange.").rate(BOUGHT_RATE);
	}

	/** Experience one go gives. */
	Recipe xp(Skill skill, double amount)
	{
		xpSkill = skill;
		xp = amount;
		return this;
	}

	/** A typical number of items an hour, banking included, for estimates before the player's own pace is known. */
	Recipe rate(int perHour)
	{
		rate = perHour;
		return this;
	}

	Recipe makes(int count)
	{
		makes = count;
		return this;
	}

	Recipe from(int itemId, int qty)
	{
		inputs.put(itemId, qty);
		return this;
	}

	Recipe needs(Skill skill, int level)
	{
		reqs.add(new Req(skill, level, false));
		return this;
	}

	Recipe grows(Skill skill, int level)
	{
		reqs.add(new Req(skill, level, true));
		return this;
	}

	Recipe tool(int itemId)
	{
		tools.add(itemId);
		return this;
	}

	Recipe how(String text)
	{
		how = text;
		return this;
	}

	public int getOutput()
	{
		return output;
	}

	public Verb getVerb()
	{
		return verb;
	}

	/** How many items one go makes, such as three 4-dose potions from four 3-dose ones. */
	public int getMakes()
	{
		return makes;
	}

	public Map<Integer, Integer> getInputs()
	{
		return Collections.unmodifiableMap(inputs);
	}

	public List<Req> getReqs()
	{
		return Collections.unmodifiableList(reqs);
	}

	public List<Integer> getTools()
	{
		return Collections.unmodifiableList(tools);
	}

	public String getHow()
	{
		return how;
	}

	/** The skill one go trains, or null. */
	public Skill getXpSkill()
	{
		return xpSkill;
	}

	/** Experience one go gives, or 0. */
	public double getXp()
	{
		return xp;
	}

	/** Typical items an hour, or 0 when it depends too much on luck or farm runs to say. */
	public int getRate()
	{
		return rate;
	}

	public boolean isSource()
	{
		return inputs.isEmpty();
	}

	/** The first hard requirement the player's levels do not meet, or null. */
	public Req unmet(Map<Skill, Integer> levels)
	{
		for (Req r : reqs)
		{
			if (!r.isSoft() && !r.met(levels))
			{
				return r;
			}
		}
		return null;
	}
}

package com.codex.provisioner.core;

import java.util.Map;
import net.runelite.api.Skill;

/**
 * A level a step asks for. A hard requirement stops the step until it is met; a soft one is only
 * a way in, such as the Farming level to grow a herb that monsters also drop.
 */
public final class Req
{
	private final Skill skill;
	private final int level;
	private final boolean soft;

	Req(Skill skill, int level, boolean soft)
	{
		this.skill = skill;
		this.level = level;
		this.soft = soft;
	}

	public Skill getSkill()
	{
		return skill;
	}

	public int getLevel()
	{
		return level;
	}

	public boolean isSoft()
	{
		return soft;
	}

	/** @return true when met, or when the player's levels are not known yet */
	public boolean met(Map<Skill, Integer> levels)
	{
		Integer have = levels.get(skill);
		return have == null || have >= level;
	}
}

package com.codex.provisioner.core;

import java.util.Locale;
import java.util.function.IntFunction;

/**
 * The word at the bank when the kit is running low: how many whole trips what is held covers,
 * which supply runs out first, and how many more of what it is made as would see the warning
 * mark through. Given as the bank opens, and not again for the same shortfall until it grows
 * or half an hour has passed, so a player banking between loads is not told at every visit.
 */
public final class Restock
{
	/** The same warning comes again no sooner than this. */
	static final long QUIET_MS = 30 * 60_000L;

	/** The kit last warned of, and the trips then held. */
	private String lastKey;
	private long lastReady;
	private long lastAt;

	/**
	 * What to say as the bank opens, or null for nothing. A player working through the chain at
	 * the bank sees the count fall with each load, so the same kit is warned of again
	 * only once fewer trips are held than last time, or after half an hour, whichever supply is
	 * first to run out.
	 *
	 * @param chosen the kit the player picked on the Kits tab, or null: a kit only shown by
	 *     default, never picked, is not one the player is stocking for, so it is never warned of
	 * @param below warn when fewer whole trips than this are held; 0 never warns
	 * @param names an item's name by its id
	 */
	public String onBank(Chain chain, String chosen, int below, IntFunction<String> names, long now)
	{
		String text = chain == null || chosen == null || !chosen.equals(chain.getKit().getId()) ? null : warning(chain, below, names);
		if (text == null)
		{
			// Stocked again: a later shortfall is news, even within the half hour.
			lastKey = null;
			return null;
		}
		// Keyed by the kit alone: with two supplies near level, the one first to run out swaps
		// from visit to visit while the trips held stay the same, which is no news.
		String key = chain.getKit().getId();
		long ready = chain.limiting().tripsHeld();
		if (key.equals(lastKey) && ready >= lastReady && now - lastAt < QUIET_MS)
		{
			return null;
		}
		lastKey = key;
		lastReady = ready;
		lastAt = now;
		return text;
	}

	/** Forgets what was said, for another account. */
	public void reset()
	{
		lastKey = null;
		lastReady = 0;
		lastAt = 0;
	}

	/**
	 * "Ready for 2 trips of Vorkath. First to run out: food; 18 more shark cover 3 trips.", or null when
	 * the kit is stocked for at least {@code below} trips, uses nothing up, or the check is off.
	 */
	public static String warning(Chain chain, int below, IntFunction<String> names)
	{
		if (chain == null || below <= 0)
		{
			return null;
		}
		// Never more than the trips the plan is for: stocking for one trip asks for no more.
		below = Math.min(below, chain.getTrips());
		Chain.Line first = chain.limiting();
		if (first == null || first.tripsHeld() >= below)
		{
			return null;
		}
		long ready = first.tripsHeld();
		String kit = chain.getKit().getName();
		// Worded as the Chain tab words it under the step in hand.
		String head = ready == 0 ? "Not stocked for a single trip of " + kit + "." : "Ready for " + plural(ready, "trip") + " of " + kit + ".";
		Supply supply = first.getSupply();
		String what = supply.getName() != null ? supply.getName() : names.apply(supply.getIcon());
		Integer each = supply.getUnits().get(first.getProduct());
		long more = more(first, below, each == null ? 0 : each);
		String product = names.apply(first.getProduct());
		String lead = head + " First to run out: " + (what == null ? "one supply" : what.toLowerCase(Locale.ENGLISH));
		if (more <= 0 || product == null)
		{
			return lead + ".";
		}
		return lead + "; " + String.format(Locale.ENGLISH, "%,d", more) + " more " + product.toLowerCase(Locale.ENGLISH) + " cover " + plural(below, "trip") + ".";
	}

	/** How many more of the product it takes for a supply to cover so many trips; 0 when it cannot be told. */
	static long more(Chain.Line line, int trips, int unitsEach)
	{
		if (unitsEach <= 0 || line.getPerTrip() <= 0)
		{
			return 0;
		}
		double missing = line.getPerTrip() * trips - line.getHave();
		return missing <= 0 ? 0 : (long) Math.ceil(missing / unitsEach - 1e-9);
	}

	private static String plural(long n, String one)
	{
		return n + " " + (n == 1 ? one : one + "s");
	}
}

package com.codex.provisioner.core;

/**
 * Counts the game ticks after a login or a world hop until the account can be read. The game
 * says the player is logged in before it has sent their levels and varbits, which arrive over the
 * first ticks; read too soon, every skill is level 1 and no account is an ironman. RuneLite's own
 * experience tracker waits two ticks the same way.
 */
public final class Settle
{
	/** Ticks after logging in before levels and varbits are trusted. */
	static final int TICKS = 2;

	private int wait = TICKS;

	/** Logging in or hopping: the account is not to be read until it has settled. */
	public void restart()
	{
		wait = TICKS;
	}

	/**
	 * A game tick passed while logged in.
	 *
	 * @return true on the one tick the account settles, when it should be read afresh
	 */
	public boolean tick()
	{
		if (wait <= 0)
		{
			return false;
		}
		wait--;
		return wait == 0;
	}

	/** Whether levels and varbits read now are the account's own. */
	public boolean isSettled()
	{
		return wait <= 0;
	}
}

package com.codex.provisioner.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * The whole bank as Codex Bank Steward last saw it, which it publishes for the other Codex
 * plugins under {@link #KEY} of its config group:
 * {@code {"version":1,"savedAt":ms,"items":{"id":qty},"truncated":false}}, item ids canonical,
 * potion storage and the inventory left out. Read only, and only taken when it is newer than
 * the bank the Provisioner saw itself, such as on the first login after installing.
 */
public final class SharedBank
{
	public static final String GROUP = "codexbanksteward";
	public static final String KEY = "bankV1";

	private final long savedAt;
	private final Map<Integer, Long> items;

	private SharedBank(long savedAt, Map<Integer, Long> items)
	{
		this.savedAt = savedAt;
		this.items = items;
	}

	/** Reads a published snapshot; null when there is none or it cannot be read. */
	public static SharedBank read(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = gson.fromJson(json, JsonElement.class);
			if (root == null || !root.isJsonObject())
			{
				return null;
			}
			JsonObject o = root.getAsJsonObject();
			JsonElement at = o.get("savedAt");
			JsonElement list = o.get("items");
			Long savedAt = Json.whole(at);
			if (savedAt == null || list == null || !list.isJsonObject())
			{
				return null;
			}
			Map<Integer, Long> items = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : list.getAsJsonObject().entrySet())
			{
				try
				{
					int id = Integer.parseInt(e.getKey());
					Long qty = Json.whole(e.getValue());
					if (id > 0 && qty != null && qty > 0)
					{
						// No stack holds more than an int; a bigger figure is damage, not items.
						items.put(id, Json.count(qty));
					}
				}
				catch (NumberFormatException ignored)
				{
					// One unreadable entry does not spoil the rest.
				}
			}
			return savedAt > 0 ? new SharedBank(savedAt, items) : null;
		}
		catch (JsonParseException | IllegalStateException | NumberFormatException e)
		{
			return null;
		}
	}

	public long getSavedAt()
	{
		return savedAt;
	}

	public Map<Integer, Long> getItems()
	{
		return Collections.unmodifiableMap(items);
	}
}

package com.codex.provisioner.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * What one sitting of a given length gets through, at the player's own pace where it is known:
 * the step in hand first, then the chain in its order, each step as far as the time and its
 * inputs allow. A step that waits on an earlier one counts only what the sitting has made of its
 * inputs by then. A shop run is taken as quickly done, since the steps after it need what it buys;
 * other steps that cannot be timed, herbs grown on runs and steps above the player's levels are
 * passed over and named.
 */
public final class Sitting
{
	/** One step's share of the sitting. */
	public static final class Piece
	{
		private final Step step;
		private final long amount;
		private final long ms;

		Piece(Step step, long amount, long ms)
		{
			this.step = step;
			this.amount = amount;
			this.ms = ms;
		}

		public Step getStep()
		{
			return step;
		}

		/** Items of the step the sitting gets. */
		public long getAmount()
		{
			return amount;
		}

		/** Time they take. */
		public long getMs()
		{
			return ms;
		}

		/** Whether the sitting finishes the step. */
		public boolean finishes()
		{
			return amount >= step.getNet();
		}
	}

	private final long budget;
	private final List<Piece> pieces;
	private final long used;
	/** Open steps the sitting does not reach or cannot plan, in chain order. */
	private final List<Step> left;
	private final boolean everything;
	/** Times the chain is walked while time is left. */
	private static final int PASSES = 4;

	private Sitting(long budget, List<Piece> pieces, long used, List<Step> left, boolean everything)
	{
		this.budget = budget;
		this.pieces = pieces;
		this.used = used;
		this.left = left;
		this.everything = everything;
	}

	/**
	 * @param estimates milliseconds each open step's remaining items take, by item; -1 or missing when it cannot be timed
	 * @param grown items grown on herb runs rather than worked in a sitting
	 * @param budget the sitting's length in milliseconds
	 */
	public static Sitting plan(Chain chain, Map<Integer, Long> estimates, Set<Integer> grown, long budget)
	{
		List<Step> order = new ArrayList<>();
		Step now = chain.current();
		if (now != null && now.getState() != Step.State.DONE)
		{
			order.add(now);
		}
		for (Step s : chain.getSteps())
		{
			if (s != now && s.getState() != Step.State.DONE)
			{
				order.add(s);
			}
		}
		// Inputs still to be got: a step can use only what the sitting makes of them. Inputs whose
		// step is done are held in full, so they hold nothing back.
		Set<Integer> inChain = new java.util.HashSet<>();
		for (Step s : chain.getSteps())
		{
			if (s.getState() != Step.State.DONE)
			{
				inChain.add(s.getItem());
			}
		}

		// Each step's share so far, in the order first reached. The chain is walked again while time is
		// left, so a load caught after its cooking step was passed over is still cooked in the sitting.
		Map<Step, long[]> share = new java.util.LinkedHashMap<>();
		Map<Integer, Long> made = new HashMap<>();
		long remaining = Math.max(0, budget);
		for (int pass = 0; pass < PASSES && remaining > 0; pass++)
		{
			boolean progress = false;
			for (Step s : order)
			{
				long[] got = share.computeIfAbsent(s, k -> new long[2]);
				long still = s.getNet() - got[0];
				if (still <= 0 || s.getState() == Step.State.LOCKED)
				{
					continue;
				}
				if (s.getRecipe().getVerb() == Verb.BUY)
				{
					// A shop run cannot be timed, but it is quickly done and the steps after it need it.
					got[0] += still;
					made.merge(s.getItem(), still, Long::sum);
					progress = true;
					continue;
				}
				long est = estimates.getOrDefault(s.getItem(), -1L);
				if (grown.contains(s.getItem()) || est < 0)
				{
					continue;
				}
				long most = still;
				long fromHeld = 0;
				if (!s.getRecipe().isSource())
				{
					// What the held inputs make, and as much more as the sitting has made of what goes in.
					fromHeld = Math.max(0, s.getCanNow() - got[0]);
					long extra = Long.MAX_VALUE;
					for (Map.Entry<Integer, Integer> in : s.getRecipe().getInputs().entrySet())
					{
						if (inChain.contains(in.getKey()) && in.getValue() > 0)
						{
							extra = Math.min(extra, made.getOrDefault(in.getKey(), 0L) / in.getValue() * Math.max(1, s.getRecipe().getMakes()));
						}
					}
					most = Math.min(most, fromHeld + (extra == Long.MAX_VALUE ? 0 : extra));
				}
				double perItem = est / (double) s.getNet();
				long fits = perItem <= 0 ? most : (long) Math.floor(remaining / perItem);
				long amount = Math.min(most, fits);
				if (amount <= 0)
				{
					continue;
				}
				long ms = Math.round(amount * perItem);
				remaining -= ms;
				got[0] += amount;
				got[1] += ms;
				made.merge(s.getItem(), amount, Long::sum);
				// What came from the sitting's own work is used up, so two steps never share one load.
				long fromMade = amount - Math.min(amount, fromHeld);
				if (fromMade > 0)
				{
					int makes = Math.max(1, s.getRecipe().getMakes());
					for (Map.Entry<Integer, Integer> in : s.getRecipe().getInputs().entrySet())
					{
						if (inChain.contains(in.getKey()))
						{
							made.merge(in.getKey(), -((fromMade + makes - 1) / makes) * in.getValue(), Long::sum);
						}
					}
				}
				progress = true;
			}
			if (!progress)
			{
				break;
			}
		}

		List<Piece> pieces = new ArrayList<>();
		List<Step> left = new ArrayList<>();
		for (Step s : order)
		{
			long[] got = share.get(s);
			if (got != null && got[0] > 0)
			{
				pieces.add(new Piece(s, Math.min(s.getNet(), got[0]), got[1]));
			}
			if (got == null || got[0] < s.getNet())
			{
				left.add(s);
			}
		}
		return new Sitting(budget, Collections.unmodifiableList(pieces), budget - remaining,
			Collections.unmodifiableList(left), left.isEmpty() && !pieces.isEmpty());
	}

	/** Why a step is left after the sitting. */
	public enum Reason
	{
		/** Above the player's levels. */
		LOCKED,
		/** Grown on herb runs, dropped or otherwise not timed. */
		UNTIMED,
		/** Its inputs come from a step the sitting cannot do. */
		WAITING,
		/** The sitting ran out of time. */
		TIME
	}

	/** Why a step the sitting leaves is left; only for steps in {@link #getLeft()}. */
	public Reason reason(Step s, Map<Integer, Long> estimates, Set<Integer> grown)
	{
		if (s.getState() == Step.State.LOCKED)
		{
			return Reason.LOCKED;
		}
		if (grown.contains(s.getItem()) || estimates.getOrDefault(s.getItem(), -1L) < 0)
		{
			return Reason.UNTIMED;
		}
		// Time enough left for one more item, and still left: it waits on something the sitting cannot get.
		double perItem = s.getNet() <= 0 ? 0 : estimates.get(s.getItem()) / (double) s.getNet();
		return budget - used >= Math.max(1, perItem) ? Reason.WAITING : Reason.TIME;
	}

	public long getBudget()
	{
		return budget;
	}

	public List<Piece> getPieces()
	{
		return pieces;
	}

	/** Time the pieces take together, at most the budget. */
	public long getUsed()
	{
		return used;
	}

	/** Open steps left after the sitting, or that it could not plan. */
	public List<Step> getLeft()
	{
		return left;
	}

	/** Whether the sitting finishes every open step. */
	public boolean isEverything()
	{
		return everything;
	}
}

package com.codex.provisioner.core;

import java.util.Map;

/** One thing to do in the chain: gather, catch or make some number of one item. */
public final class Step
{
	public enum State
	{
		/** Enough is held, now or for everything above it in the chain. */
		DONE,
		/** Can be worked on now: a source, or something with inputs to hand. */
		READY,
		/** Waits for an earlier step to supply its inputs. */
		WAITING,
		/** The player's levels do not reach it yet. */
		LOCKED
	}

	private final Recipe recipe;
	private final String supply;
	private final long net;
	private final long held;
	private final long canNow;
	private final State state;
	private final Req unmet;
	private final long baseline;

	Step(Recipe recipe, String supply, long net, long held, long canNow, State state, Req unmet, long baseline)
	{
		this.recipe = recipe;
		this.supply = supply;
		this.net = net;
		this.held = held;
		this.canNow = canNow;
		this.state = state;
		this.unmet = unmet;
		this.baseline = baseline;
	}

	public int getItem()
	{
		return recipe.getOutput();
	}

	public Recipe getRecipe()
	{
		return recipe;
	}

	/** The kit supply whose chain this step was first reached from. */
	public String getSupply()
	{
		return supply;
	}

	/** Items still to get. */
	public long getNet()
	{
		return net;
	}

	public long getHeld()
	{
		return held;
	}

	/** How many could be made from what is held right now, at most what is still to get. */
	public long getCanNow()
	{
		return canNow;
	}

	public State getState()
	{
		return state;
	}

	/** The requirement holding a locked step back, or null. */
	public Req getUnmet()
	{
		return unmet;
	}

	/** The most this step has ever had to go, so progress has a fixed end. */
	public long getBaseline()
	{
		return baseline;
	}

	public long getDone()
	{
		return Math.max(0, baseline - net);
	}

	public double progress()
	{
		if (state == State.DONE || baseline <= 0)
		{
			return 1;
		}
		return Math.max(0, Math.min(1, (baseline - net) / (double) baseline));
	}

	/** How many of each tool is held, for "bring" lines; tools are never used up. */
	public boolean hasTool(int tool, Map<Integer, Long> holdings)
	{
		return holdings.getOrDefault(tool, 0L) > 0;
	}
}

