package com.codex.provisioner.core;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One thing a trip uses up, counted in its own unit: food in hitpoints healed, potions in doses,
 * bolts one by one. A supply can be met by several items, so four doses of prayer potion and four
 * of super restore count the same, and a shark and a manta ray both count as food.
 */
public final class Supply
{
	private static final String ITEM = "item:";

	private final String key;
	private final String name;
	private final String unit;
	private final int icon;
	private final Map<Integer, Integer> units;

	Supply(String key, String name, String unit, int icon, Map<Integer, Integer> units)
	{
		this.key = key;
		this.name = name;
		this.unit = unit;
		this.icon = icon;
		this.units = Collections.unmodifiableMap(new LinkedHashMap<>(units));
	}

	/** A supply that is one item and nothing else, such as a teleport tablet or a rune. */
	public static Supply item(int itemId)
	{
		return new Supply(itemKey(itemId), null, null, itemId, Collections.singletonMap(itemId, 1));
	}

	public static String itemKey(int itemId)
	{
		return ITEM + itemId;
	}

	public String getKey()
	{
		return key;
	}

	/** @return the supply's name, or null for a single item, which is named after the item */
	public String getName()
	{
		return name;
	}

	/** @return "hp", "doses" and the like, or null when it is counted in items */
	public String getUnit()
	{
		return unit;
	}

	public int getIcon()
	{
		return icon;
	}

	public boolean isItem()
	{
		return key.startsWith(ITEM);
	}

	/** Every item that counts, with how many units one of it is worth. */
	public Map<Integer, Integer> getUnits()
	{
		return units;
	}

	/** How much of this supply a set of items holds, in units. */
	public long count(Map<Integer, Long> items)
	{
		long total = 0;
		for (Map.Entry<Integer, Integer> e : units.entrySet())
		{
			Long qty = items.get(e.getKey());
			if (qty != null && qty > 0)
			{
				total += qty * e.getValue();
			}
		}
		return total;
	}
}

package com.codex.provisioner.core;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

/**
 * What working through the rest of a chain trains: the experience every open step gives, skill by
 * skill, and the level each skill will stand at once it is all done. Locked steps count too, since
 * the chain cannot be finished without them.
 */
public final class Training
{
	/** One skill's share of the chain. */
	public static final class Gain
	{
		private final Skill skill;
		private final double xp;
		private final long before;

		Gain(Skill skill, double xp, long before)
		{
			this.skill = skill;
			this.xp = xp;
			this.before = before;
		}

		public Skill getSkill()
		{
			return skill;
		}

		/** Experience the chain's open steps give in this skill. */
		public double getXp()
		{
			return xp;
		}

		/** The skill's experience now. */
		public long getBefore()
		{
			return before;
		}

		public int levelBefore()
		{
			return level(before);
		}

		public int levelAfter()
		{
			return level(before + Math.round(xp));
		}

		/** How far through the level after the chain the skill will be, 0 to 1; 1 at 99. */
		public double progressAfter()
		{
			int level = levelAfter();
			if (level >= Experience.MAX_REAL_LEVEL)
			{
				return 1;
			}
			long at = before + Math.round(xp);
			long low = Experience.getXpForLevel(level);
			long high = Experience.getXpForLevel(level + 1);
			return high <= low ? 1 : Math.max(0, Math.min(1, (at - low) / (double) (high - low)));
		}

		private static int level(long xp)
		{
			// The table runs on into virtual levels past 99, which the game never shows.
			return Math.min(Experience.MAX_REAL_LEVEL, Experience.getLevelForXp((int) Math.max(0, Math.min(Experience.MAX_SKILL_XP, xp))));
		}
	}

	private Training()
	{
	}

	/**
	 * @param xp each skill's experience now; a skill left out is taken from its level, or as new
	 * @param levels the levels as last seen, for skills whose experience is not known
	 * @return each skill trained, the most experience first
	 */
	public static List<Gain> of(Chain chain, Map<Skill, Long> xp, Map<Skill, Integer> levels)
	{
		Map<Skill, Double> gained = new EnumMap<>(Skill.class);
		for (Step s : chain.getSteps())
		{
			Recipe r = s.getRecipe();
			if (s.getState() == Step.State.DONE || r.getXpSkill() == null || r.getXp() <= 0 || r.getVerb() == Verb.BUY)
			{
				continue;
			}
			long crafts = (s.getNet() + r.getMakes() - 1) / r.getMakes();
			gained.merge(r.getXpSkill(), crafts * r.getXp(), Double::sum);
		}
		List<Gain> out = new ArrayList<>();
		for (Map.Entry<Skill, Double> e : gained.entrySet())
		{
			// Experience read before the game sent it can lag the level; the level's own floor is the least it can be.
			Integer level = levels.get(e.getKey());
			long floor = Experience.getXpForLevel(Math.max(1, Math.min(Experience.MAX_REAL_LEVEL, level == null ? 1 : level)));
			Long now = xp.get(e.getKey());
			out.add(new Gain(e.getKey(), e.getValue(), now == null ? floor : Math.max(floor, now)));
		}
		out.sort((a, b) -> Double.compare(b.xp, a.xp));
		return out;
	}
}

package com.codex.provisioner.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * A supply's chain drawn as the tree it is: the finished product at the root, what goes into it
 * beneath, down to the things gathered by hand at the leaves. A part already stocked is a leaf of
 * its own, since nothing beneath it is needed; a part the tree has already shown, such as vials of
 * water shared by two potions, is named again but not opened twice. Tools are not inputs and stay out.
 */
public final class Tree
{
	/** No chain the Cookbook knows is deeper than this; a guard against a recipe that loops. */
	static final int MAX_DEPTH = 8;

	/** One line of the tree. */
	public static final class Node
	{
		private final int item;
		private final int depth;
		private final Step step;
		private final boolean repeat;
		private final boolean last;
		private final boolean[] rails;

		Node(int item, int depth, Step step, boolean repeat, boolean last, boolean[] rails)
		{
			this.item = item;
			this.depth = depth;
			this.step = step;
			this.repeat = repeat;
			this.last = last;
			this.rails = rails;
		}

		public int getItem()
		{
			return item;
		}

		/** How far below the root it sits; the root is 0. */
		public int getDepth()
		{
			return depth;
		}

		/** Its step in the chain, or null when the chain holds none, as for a product already stocked. */
		public Step getStep()
		{
			return step;
		}

		/** Whether the tree has already shown this part, here named again without what goes into it. */
		public boolean isRepeat()
		{
			return repeat;
		}

		/** Whether it is the last input of its parent, so its branch ends here. */
		public boolean isLast()
		{
			return last;
		}

		/** Whether the branch at a depth above it still runs on below it, for drawing the lines. */
		public boolean rail(int depth)
		{
			return depth >= 0 && depth < rails.length && rails[depth];
		}

		/** Whether nothing more of it is needed. */
		public boolean isDone()
		{
			return step == null || step.getState() == Step.State.DONE;
		}
	}

	private Tree()
	{
	}

	/** Every supply's tree, in the kit's order, with each shared part opened only the first time. */
	public static Map<Chain.Line, List<Node>> of(Chain chain)
	{
		Map<Integer, Step> steps = new HashMap<>();
		for (Step s : chain.getSteps())
		{
			steps.put(s.getItem(), s);
		}
		Set<Integer> shown = new HashSet<>();
		Map<Chain.Line, List<Node>> trees = new java.util.LinkedHashMap<>();
		for (Chain.Line line : chain.getLines())
		{
			List<Node> nodes = new ArrayList<>();
			walk(line.getProduct(), 0, true, new boolean[0], steps, shown, nodes);
			trees.put(line, Collections.unmodifiableList(nodes));
		}
		return trees;
	}

	private static void walk(int item, int depth, boolean last, boolean[] rails, Map<Integer, Step> steps, Set<Integer> shown, List<Node> out)
	{
		Step step = steps.get(item);
		boolean repeat = !shown.add(item);
		out.add(new Node(item, depth, step, repeat, last, rails));
		// A stocked part needs nothing beneath it; a repeated one was opened where it first came.
		if (repeat || step == null || step.getState() == Step.State.DONE || depth >= MAX_DEPTH)
		{
			return;
		}
		Recipe recipe = step.getRecipe();
		List<Integer> inputs = new ArrayList<>(recipe.getInputs().keySet());
		boolean[] below = new boolean[depth + 1];
		System.arraycopy(rails, 0, below, 0, rails.length);
		// The line from this node down to its inputs runs on past each one but the last.
		for (int i = 0; i < inputs.size(); i++)
		{
			boolean lastInput = i == inputs.size() - 1;
			boolean[] r = below.clone();
			r[depth] = !lastInput;
			walk(inputs.get(i), depth + 1, lastInput, r, steps, shown, out);
		}
	}
}

package com.codex.provisioner.core;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.util.Map;

/**
 * Tells whether a save holds anything its read-back lacks: a field or an entry of a kind a later
 * version keeps, or something damage put in that reading had to leave out. Such a save reads
 * without an error, but the next save would quietly drop what this version did not understand,
 * so it is worth setting aside first. Figures set right in reading (a count below zero brought
 * up to it) are not counted; nor is a nothing (zero, false, empty) that the read-back leaves out.
 */
final class Unread
{
	private Unread()
	{
	}

	/** True when the save holds anything that reading it back left out. */
	static boolean any(Gson gson, String saved, Object read)
	{
		try
		{
			return lost(gson.fromJson(saved, JsonElement.class), gson.toJsonTree(read));
		}
		catch (RuntimeException e)
		{
			return true;
		}
	}

	private static boolean lost(JsonElement saved, JsonElement back)
	{
		if (nothing(saved))
		{
			return false;
		}
		if (back == null || back.isJsonNull())
		{
			return true;
		}
		if (saved.isJsonObject())
		{
			if (!back.isJsonObject())
			{
				return true;
			}
			JsonObject b = back.getAsJsonObject();
			for (Map.Entry<String, JsonElement> e : saved.getAsJsonObject().entrySet())
			{
				if (lost(e.getValue(), b.get(e.getKey())))
				{
					return true;
				}
			}
			return false;
		}
		if (saved.isJsonArray())
		{
			if (!back.isJsonArray())
			{
				return true;
			}
			JsonArray s = saved.getAsJsonArray();
			JsonArray b = back.getAsJsonArray();
			if (s.size() > b.size())
			{
				return true;
			}
			// Reading can add to a list (a field an older save had not yet) but not take from it;
			// a list read back the same length is checked item by item.
			if (s.size() == b.size())
			{
				for (int i = 0; i < s.size(); i++)
				{
					if (lost(s.get(i), b.get(i)))
					{
						return true;
					}
				}
			}
			return false;
		}
		// A figure: kept when the read-back has one in its place, set right or not.
		return !back.isJsonPrimitive();
	}

	private static boolean nothing(JsonElement e)
	{
		if (e == null || e.isJsonNull())
		{
			return true;
		}
		if (e.isJsonPrimitive())
		{
			JsonPrimitive p = e.getAsJsonPrimitive();
			if (p.isBoolean())
			{
				return !p.getAsBoolean();
			}
			if (p.isNumber())
			{
				return p.getAsBigDecimal().signum() == 0;
			}
			return p.getAsString().isEmpty();
		}
		return e.isJsonArray() ? e.getAsJsonArray().size() == 0 : e.getAsJsonObject().size() == 0;
	}
}

