package com.codex.provisioner.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.provisioner.ui;

import java.util.Collections;
import java.util.Set;
import java.util.WeakHashMap;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Which item pictures have arrived. RuneLite runs a picture's loaded callback again, a moment
 * later, for every ask after it has loaded; a panel that rebuilds or repaints on that callback
 * and asks again as it does would go round for as long as it is shown. Once a picture is in,
 * nothing waits on it any more.
 *
 * <p>Pictures are told apart by the picture itself, not the item: RuneLite keeps only the last
 * 128 item pictures, so one asked for again after a busy while is a new, blank picture that has
 * to be waited on like the first. They are held weakly, so a forgotten picture is not kept.
 * Safe from any thread.
 */
public final class Arrivals
{
	private final Set<AsyncBufferedImage> arrived = Collections.synchronizedSet(Collections.newSetFromMap(new WeakHashMap<>()));

	/** Whether this picture has arrived, so there is nothing to wait for. */
	public boolean arrived(AsyncBufferedImage image)
	{
		return arrived.contains(image);
	}

	/**
	 * Runs onLoaded once the picture is in, unless it already is. A picture that arrives between
	 * the check and the ask still answers: RuneLite then runs the callback a moment later.
	 */
	public void ask(AsyncBufferedImage image, Runnable onLoaded)
	{
		if (image == null || arrived.contains(image))
		{
			return;
		}
		image.onLoaded(() ->
		{
			arrived.add(image);
			if (onLoaded != null)
			{
				onLoaded.run();
			}
		});
	}
}

package com.codex.provisioner.ui;

import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;

/** A slim engraved progress bar, ember when just begun, gold midway, teal near the end and green when done. */
final class Bar
{
	private Bar()
	{
	}

	static void paint(Graphics2D g, int x, int y, int width, int height, double progress)
	{
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(x, y, width, height, height, height));
		float fill = (float) (width * Math.max(0, Math.min(1, progress)));
		if (fill > 0)
		{
			Color c = Theme.progressColor(progress);
			g.setPaint(new GradientPaint(x, 0, Theme.mix(c, Theme.INK, 0.4), x + width, 0, c));
			g.fill(new RoundRectangle2D.Float(x, y, Math.max(height, fill), height, height, height));
			g.setColor(Theme.alpha(Color.WHITE, 40));
			g.drawLine(x + 1, y, Math.round(x + Math.max(height, fill)) - 2, y);
		}
	}
}

