package com.codex.provisioner.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import javax.swing.JPanel;

/** A kit to provision for, with what its chain would take for the chosen number of trips. */
class KitCard extends Card
{
	KitCard(View.KitSummary summary, boolean chosen, int trips, Runnable onChoose, int width)
	{
		super(new BorderLayout(0, 2));
		Color accent = chosen ? Theme.GOLD : summary.kit.isPreset() ? Theme.GOLD_DIM : Theme.TEAL;
		accent(accent);
		highlighted(chosen);
		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		top.add(Ui.label(summary.kit.getName(), Theme.body(), chosen ? Theme.GOLD_BRIGHT : Theme.TEXT), BorderLayout.WEST);
		String tag = chosen ? "chosen" : summary.kit.isPreset() ? "preset" : "your kit";
		top.add(Ui.label(tag, Theme.small(), chosen ? Theme.GOLD : Theme.TEXT_FAINT), BorderLayout.EAST);
		add(top, BorderLayout.NORTH);
		String detail;
		if (summary.shortSupplies == 0)
		{
			detail = "Stocked for " + trips + " trips";
		}
		else
		{
			detail = summary.shortSupplies + (summary.shortSupplies == 1 ? " supply" : " supplies") + " short \u00b7 "
				+ summary.steps + (summary.steps == 1 ? " step" : " steps");
		}
		if (summary.ready > 0 && summary.shortSupplies > 0)
		{
			detail += " \u00b7 ready for " + summary.ready + (summary.ready == 1 ? " trip" : " trips");
		}
		if (summary.measured >= 2)
		{
			detail += " \u00b7 measured";
		}
		add(Ui.wrapped(detail, Theme.small(), summary.shortSupplies == 0 ? Theme.GREEN : Theme.TEXT_MUTED, width), BorderLayout.CENTER);
		if (!chosen)
		{
			// After the children are in, so the whole card answers the click.
			onClick(onChoose);
		}
	}
}

package com.codex.provisioner.ui;

import com.codex.provisioner.core.Loads;
import com.codex.provisioner.core.Step;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.JComponent;

/**
 * One inventory of the step in hand, drawn as bank slots: what to take out of the bank for each
 * trip, with the stacks in the game's own colours, and how many trips the step has left. For a
 * catch, the slot shows what one inventory brings back.
 */
class LoadStrip extends JComponent
{
	private static final int GAP = 14;

	private final Map<Integer, Long> slots;
	private final String label;
	private final long loads;
	private final ItemIcons icons;
	private final String tip;

	LoadStrip(Step step, Loads loads, View view, ItemIcons icons)
	{
		this.icons = icons;
		this.loads = loads.getLoads();
		boolean catching = loads.getWithdraw().isEmpty();
		if (catching)
		{
			slots = new LinkedHashMap<>();
			slots.put(step.getItem(), loads.getPerLoad());
			label = "EACH INVENTORY";
		}
		else
		{
			slots = loads.getWithdraw();
			label = "TAKE OUT EACH TRIP";
		}
		List<String> parts = new ArrayList<>();
		slots.forEach((id, n) -> parts.add(Format.amount(n) + " " + view.name(id).toLowerCase(Locale.ENGLISH)));
		tip = (catching ? "Each inventory holds " : "Each trip, take out ") + String.join(" and ", parts) + "; "
			+ this.loads + (this.loads == 1 ? " trip" : " trips") + " to go.";
		setToolTipText(tip);
		setOpaque(false);
		setPreferredSize(new Dimension(10, 14 + Well.SIZE + 2));
	}

	/** The step from one slot to the next: a roomy gap with a plus between, closed up when the slots would not fit. */
	static int pitch(int slots, int room)
	{
		int full = Well.SIZE + 4 + GAP;
		if (slots <= 1)
		{
			return full;
		}
		return Math.max(Well.SIZE + 6, Math.min(full, (room - (Well.SIZE + 4)) / (slots - 1)));
	}

	/** Whether that many slots fit in the room at their closest. */
	static boolean fits(int slots, int room)
	{
		return slots <= 1 ? Well.SIZE + 4 <= room : Well.SIZE + 4 + (slots - 1) * (Well.SIZE + 6) <= room;
	}

	String tip()
	{
		return tip;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.GOLD_DIM);
		g.drawString(label, 0, small.getAscent());

		String count = String.valueOf(loads);
		String unit = loads == 1 ? "trip" : "trips";
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		int top = 14;
		int right = Math.max(bold.stringWidth(count), small.stringWidth(unit));
		int room = w - right - 8;
		// A super combat takes four ingredients: when they would not all fit beside the trips, the
		// trips move up beside the label and the slots take the whole width, rather than leave one out.
		boolean beside = fits(slots.size(), room);
		if (beside)
		{
			// The trips left, large on the right.
			Ui.shadowed(g, count, w - (right + bold.stringWidth(count)) / 2, top + bold.getAscent() + 1, Theme.GOLD_BRIGHT);
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(unit, w - (right + small.stringWidth(unit)) / 2, top + Well.SIZE - 2);
		}
		else
		{
			room = w;
			String trips = count + " " + unit;
			g.setFont(Theme.small());
			Ui.shadowed(g, trips, w - small.stringWidth(trips), small.getAscent(), Theme.GOLD_BRIGHT);
		}

		int x = 0;
		int pitch = pitch(slots.size(), room);
		int gap = pitch - (Well.SIZE + 4);
		int i = 0;
		for (Map.Entry<Integer, Long> e : slots.entrySet())
		{
			if (x + Well.SIZE + 4 > room)
			{
				break;
			}
			if (i++ > 0 && gap >= 8)
			{
				g.setFont(Theme.small());
				g.setColor(Theme.GOLD_DIM);
				g.drawString("+", x - gap + (gap - small.stringWidth("+")) / 2, top + Well.SIZE / 2 + small.getAscent() / 2);
			}
			BufferedImage icon = icons == null ? null : icons.icon(e.getKey(), this::repaint);
			Well.paint(g, x, top, icon, Theme.alpha(Theme.TEAL, 150));
			String stack = Format.stack(e.getValue());
			g.setFont(Theme.small());
			Ui.shadowed(g, stack, x + 3, top + small.getAscent(), Format.stackColor(e.getValue()));
			x += pitch;
		}
		g.dispose();
	}
}

package com.codex.provisioner.ui;

import com.codex.provisioner.core.Chain;
import com.codex.provisioner.core.Req;
import com.codex.provisioner.core.Step;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.util.Locale;
import java.util.Map;
import javax.swing.JComponent;

/**
 * The step in hand, given the room it deserves: what to do and to what, how many are left, how far
 * along it is, the levels it asks for, what goes in and how much of it is held, and what to bring.
 */
class NowCard extends Card
{
	NowCard(Chain chain, Step step, View view, ItemIcons icons, int width)
	{
		super(new BorderLayout());
		accent(StepRow.color(step, true));
		highlighted(true);
		StackPanel stack = new StackPanel(5, 0);
		stack.add(new Headline(chain, step, view, icons));
		stack.add(Ui.wrapped(step.getRecipe().getHow(), Theme.small(), Theme.TEXT_MUTED, width));

		for (Req req : step.getRecipe().getReqs())
		{
			Integer have = view.level(req.getSkill());
			boolean met = req.met(view.levels);
			String text = Ui.skill(req.getSkill()) + " " + req.getLevel() + (req.isSoft() ? " to grow" : "")
				+ (have == null ? "" : met ? (req.isSoft() ? "; you have " : " \u00b7 you have ") + have : " \u00b7 you have " + have + ", " + (req.getLevel() - have) + " to go");
			stack.add(new Fact(met ? Fact.TICK : Fact.CROSS, text, req.isSoft() ? Theme.TEXT_FAINT : met ? Theme.TEAL : Theme.BLOOD));
		}
		for (Map.Entry<Integer, Integer> in : step.getRecipe().getInputs().entrySet())
		{
			long held = view.held(in.getKey());
			long need = (step.getNet() + step.getRecipe().getMakes() - 1) / step.getRecipe().getMakes() * in.getValue();
			String each = in.getValue() == 1 && step.getRecipe().getMakes() == 1 ? "" : "  (" + in.getValue() + " a go)";
			String[] pair = Format.pair(held, need);
			String text = view.name(in.getKey()) + each + ": " + pair[0] + " of " + pair[1];
			stack.add(new Fact(Fact.DIAMOND, text, held >= need ? Theme.GREEN : held > 0 ? Theme.GOLD : Theme.TEXT_FAINT));
		}
		if (view.loads != null && step.getState() == Step.State.READY)
		{
			stack.add(new LoadStrip(step, view.loads, view, icons));
		}
		for (int tool : step.getRecipe().getTools())
		{
			boolean has = view.held(tool) > 0;
			stack.add(new Fact(has ? Fact.TICK : Fact.CROSS, "Bring a " + view.name(tool).toLowerCase(Locale.ENGLISH) + (has ? "" : "; none in your bank"),
				has ? Theme.TEAL : Theme.EMBER));
		}
		com.codex.provisioner.core.HerbRuns.Plan herbs = view.herbRuns(step.getItem());
		if (herbs != null)
		{
			int used = herbs.getPatchesUsed();
			String planted = used == 1 ? "1 patch" : used + " patches";
			stack.add(new Fact(Fact.CLOCK, View.runs(herbs.getRuns()) + " on " + planted + " \u00b7 "
				+ Format.estimate(herbs.getSoonestMs()), Theme.TEXT_MUTED,
				"About " + View.runs(herbs.getRuns()) + " planting " + (used < herbs.getPatches() ? planted + " of your " + herbs.getPatches() : "all " + planted)
					+ "; herbs take 80 minutes to grow, so "
					+ Format.estimate(herbs.getSoonestMs()) + " at the soonest. Set your patches and yield in the plugin's settings."));
			long seeds = herbs.getSeeds();
			long held = herbs.getSeedsHeld();
			stack.add(new Fact(held >= seeds ? Fact.TICK : Fact.DIAMOND, view.name(herbs.getSeed()) + ": " + Format.amount(seeds) + " to plant, " + Format.amount(held) + " held",
				held >= seeds ? Theme.GREEN : held > 0 ? Theme.GOLD : Theme.TEXT_FAINT));
		}
		long time = view.estimate(step.getItem());
		if (time >= 0 && step.getState() != Step.State.LOCKED && step.getRecipe().getVerb() != com.codex.provisioner.core.Verb.BUY)
		{
			boolean own = view.ownPace(step.getItem());
			stack.add(new Fact(Fact.CLOCK, "About " + Format.estimate(time) + (own ? " at your pace" : " at a typical pace"),
				own ? Theme.TEAL : Theme.TEXT_FAINT));
		}
		if (step.getState() == Step.State.READY && !step.getRecipe().isSource() && step.getCanNow() < step.getNet())
		{
			stack.add(Ui.wrapped("What you hold makes " + Format.amount(step.getCanNow()) + " now; the rest waits on earlier steps.",
				Theme.small(), Theme.TEXT_FAINT, width));
		}
		add(stack, BorderLayout.CENTER);
	}

	/** The big line: the item, the verb, what is left and the bar. */
	private static final class Headline extends JComponent
	{
		private final Step step;
		private final String name;
		private final String position;
		private final ItemIcons icons;

		Headline(Chain chain, Step step, View view, ItemIcons icons)
		{
			this.step = step;
			this.name = view.shortName(step.getItem());
			this.position = "STEP " + chain.number(step) + " OF " + chain.getSteps().size();
			this.icons = icons;
			setOpaque(false);
			setPreferredSize(new Dimension(10, Well.SIZE + 40));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			int w = getWidth();
			Color color = StepRow.color(step, true);
			g.setFont(Theme.small());
			FontMetrics small = g.getFontMetrics();
			g.setColor(Theme.GOLD_DIM);
			g.drawString("NOW", 0, small.getAscent());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(position, w - small.stringWidth(position), small.getAscent());

			int top = small.getHeight() + 2;
			Well.paint(g, 0, top, icons == null ? null : icons.icon(step.getItem(), this::repaint), Theme.alpha(color, 200));
			int tx = Well.SIZE + 12;

			String left = step.getState() == Step.State.LOCKED ? "Lv " + step.getUnmet().getLevel() : Format.amount(step.getNet());
			// The count is drawn large unless that would cut the name short; then the name comes first.
			int large = largeWidth(g, left);
			boolean squeezed = g.getFontMetrics(Theme.body()).stringWidth(name) > w - tx - large - 6;
			int lw;
			if (squeezed)
			{
				g.setFont(Theme.title());
				FontMetrics fig = g.getFontMetrics();
				lw = fig.stringWidth(left);
				Ui.shadowed(g, left, w - lw, top + fig.getAscent() + 6, color);
			}
			else
			{
				lw = Crest.paintLarge(g, left, w - large, top + 2, color);
			}
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			String to = step.getState() == Step.State.LOCKED ? "locked" : "to go";
			g.drawString(to, w - small.stringWidth(to), top + Well.SIZE + 2);

			g.setFont(Theme.small());
			g.setColor(color);
			g.drawString(step.getRecipe().getVerb().label().toUpperCase(Locale.ENGLISH), tx, top + small.getAscent() + 1);
			// A long name beside a big count steps down to the body face before it is cut short.
			int room = w - tx - lw - 6;
			g.setFont(Theme.title());
			if (g.getFontMetrics().stringWidth(name) > room)
			{
				g.setFont(Theme.body());
			}
			FontMetrics bold = g.getFontMetrics();
			Ui.shadowed(g, Ui.clip(name, bold, room), tx, top + small.getHeight() + g.getFontMetrics(Theme.title()).getAscent() + 2, Theme.TEXT);

			int by = top + Well.SIZE + 8;
			Bar.paint(g, 0, by, w, 5, step.progress());
			String[] pair = Format.pair(step.getDone(), step.getBaseline());
			String count = pair[0] + " / " + pair[1];
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(count, 0, by + 16);
			String pct = Format.percent(step.progress());
			g.drawString(pct, w - small.stringWidth(pct), by + 16);
			g.dispose();
		}

		private static int largeWidth(Graphics2D g, String text)
		{
			return (g.getFontMetrics(Theme.title()).stringWidth(text) + 1) * 2;
		}
	}

	/** A small marked line: a requirement, an input, or a tool. */
	private static final class Fact extends JComponent
	{
		static final int TICK = 0;
		static final int CROSS = 1;
		static final int DIAMOND = 2;
		static final int CLOCK = 3;

		private final int mark;
		private final String text;
		private final Color color;

		Fact(int mark, String text, Color color)
		{
			this(mark, text, color, text);
		}

		Fact(int mark, String text, Color color, String tip)
		{
			this.mark = mark;
			this.text = text;
			this.color = color;
			setOpaque(false);
			setPreferredSize(new Dimension(10, 14));
			setToolTipText(tip);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			g.setFont(Theme.small());
			FontMetrics fm = g.getFontMetrics();
			int base = fm.getAscent();
			int cy = base - 4;
			g.setColor(color);
			g.setStroke(new java.awt.BasicStroke(1.5f, java.awt.BasicStroke.CAP_ROUND, java.awt.BasicStroke.JOIN_ROUND));
			java.awt.geom.Path2D p = new java.awt.geom.Path2D.Float();
			if (mark == TICK)
			{
				p.moveTo(1, cy);
				p.lineTo(3.5f, cy + 2.5f);
				p.lineTo(8, cy - 3);
				g.draw(p);
			}
			else if (mark == CROSS)
			{
				g.drawLine(2, cy - 3, 7, cy + 2);
				g.drawLine(7, cy - 3, 2, cy + 2);
			}
			else if (mark == CLOCK)
			{
				g.draw(new java.awt.geom.Ellipse2D.Float(1, cy - 3.5f, 7, 7));
				g.drawLine(4, cy, 4, cy - 2);
				g.drawLine(4, cy, 6, cy);
			}
			else
			{
				p.moveTo(4.5f, cy - 3.5f);
				p.lineTo(8, cy);
				p.lineTo(4.5f, cy + 3.5f);
				p.lineTo(1, cy);
				p.closePath();
				g.fill(p);
			}
			g.setColor(Theme.mix(Theme.TEXT_MUTED, color, 0.25));
			g.drawString(Ui.clip(text, fm, getWidth() - 12), 12, base);
			g.dispose();
		}
	}
}

package com.codex.provisioner.ui;

import com.codex.provisioner.core.Chain;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Map;
import javax.swing.JComponent;
import net.runelite.api.Skill;

/** One item a supply can be made as, in its slot: gilt when chosen, dimmed when the levels fall short. */
class OptionChip extends JComponent
{
	private final int itemId;
	private final boolean chosen;
	private final boolean reachable;
	private final ItemIcons icons;
	private boolean hover;

	OptionChip(int itemId, boolean chosen, View view, ItemIcons icons, Runnable onPick)
	{
		this.itemId = itemId;
		this.chosen = chosen;
		this.icons = icons;
		this.reachable = Chain.reachable(itemId, view.levels, new java.util.HashSet<>());
		setOpaque(false);
		Dimension d = new Dimension(Well.SIZE + 5, Well.SIZE + 1);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		StringBuilder tip = new StringBuilder("<html><b>").append(Ui.escape(view.name(itemId))).append("</b>");
		for (Map.Entry<Skill, Integer> e : Chain.requirements(itemId).entrySet())
		{
			Integer have = view.level(e.getKey());
			boolean met = have == null || have >= e.getValue();
			tip.append("<br>").append(met ? "" : "<font color='#cc463c'>").append(Ui.skill(e.getKey())).append(' ').append(e.getValue())
				.append(met ? "" : "</font>");
		}
		setToolTipText(tip.append("</html>").toString());
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (contains(e.getPoint()) && !chosen)
				{
					onPick.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		Color rim = chosen ? Theme.GOLD_BRIGHT : hover ? Theme.alpha(Theme.GOLD, 140) : null;
		if (!reachable && !chosen)
		{
			g.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.45f));
		}
		Well.paint(g, 0, 0, icons == null ? null : icons.icon(itemId, this::repaint), rim);
		g.setComposite(java.awt.AlphaComposite.SrcOver);
		if (chosen)
		{
			g.setColor(Theme.GOLD_BRIGHT);
			g.fillRect(Well.SIZE / 2 - 4, Well.SIZE - 2, 14, 2);
		}
		if (!reachable)
		{
			g.setColor(Theme.BLOOD);
			g.fillOval(Well.SIZE - 4, 3, 6, 6);
		}
		g.dispose();
	}
}

package com.codex.provisioner.ui;

import com.codex.provisioner.core.Chain;
import com.codex.provisioner.core.Sitting;
import com.codex.provisioner.core.Step;
import com.codex.provisioner.core.Tree;
import com.codex.provisioner.core.Supplies;
import com.codex.provisioner.core.Supply;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Provisioner side panel: the crest, then three pages. Chain is the step in hand and every
 * step after it, Stores is each supply against the target with what it is made as, and Kits is
 * where the content and its kit are chosen.
 */
public class ProvisionerPanel extends PluginPanel
{
	static final int WIDTH = 200;
	private static final String[] TABS = {"chain", "tree", "stores", "kits"};
	private static final int[] TRIPS = {5, 10, 25, 50, 100};

	private final ItemIcons icons;
	private final Actions actions;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Chain", "Tree", "Stores", "Kits");
	private final Segmented trips = new Segmented(false, "5", "10", "25", "50", "100");
	/** How long a sitting the Chain page plans, in minutes. */
	private static final int[] SITTINGS = {30, 60, 120, 180};
	private final Segmented sittingLength = new Segmented(false, "30m", "1h", "2h", "3h");
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane chainPage = scroller();
	private final JScrollPane treePage = scroller();
	private final JScrollPane storesPage = scroller();
	private final JScrollPane kitsPage = scroller();

	private View view = View.loggedOut();
	/** Which pages still show an older view; a page is only rebuilt when it is looked at. */
	private final boolean[] stale = {true, true, true, true};

	public ProvisionerPanel(ItemIcons icons, Actions actions)
	{
		super(false);
		this.icons = icons;
		this.actions = actions;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		content.add(chainPage, TABS[0]);
		content.add(treePage, TABS[1]);
		content.add(storesPage, TABS[2]);
		content.add(kitsPage, TABS[3]);
		add(content, BorderLayout.CENTER);

		tabs.onChange(this::showTab);
		trips.setSelected(1, false);
		trips.onChange(i -> actions.trips(TRIPS[i]));
		sittingLength.setSelected(1, false);
		sittingLength.onChange(i ->
		{
			stale[0] = true;
			refresh(true);
		});
		refresh(true);
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/** Called on the Swing thread whenever anything shown changes. */
	public void update(View view)
	{
		this.view = view;
		if (view.chain != null)
		{
			for (int i = 0; i < TRIPS.length; i++)
			{
				if (TRIPS[i] == view.chain.getTrips())
				{
					trips.setSelected(i, false);
				}
			}
		}
		updateCrest();
		java.util.Arrays.fill(stale, true);
		refresh(false);
	}

	/** Opens one tab. */
	public void showTab(int index)
	{
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
		refresh(true);
	}

	@Override
	public void onActivate()
	{
		refresh(true);
	}

	/**
	 * Rebuilds the page on show if it is out of date. Every withdrawal changes the view, so while
	 * the panel is closed nothing is rebuilt at all, and while it is open only the page in view is.
	 */
	private void refresh(boolean force)
	{
		if (!force && !isShowing())
		{
			return;
		}
		int page = tabs.getSelected();
		if (!stale[page])
		{
			return;
		}
		stale[page] = false;
		if (page == 0)
		{
			rebuildChain();
		}
		else if (page == 1)
		{
			rebuildTree();
		}
		else if (page == 2)
		{
			rebuildStores();
		}
		else
		{
			rebuildKits();
		}
	}

	private void updateCrest()
	{
		Chain chain = view.chain;
		if (chain == null)
		{
			crest.update("PROVISIONS", null, 0, false, -1, "Log in to plan your supplies", null, Theme.TEXT_MUTED, Theme.GOLD);
			return;
		}
		// A long kit name keeps the heading to itself; the trips are on the Stores tab, and a cut "100 TR..." helps no one.
		String full = chain.getKit().getName() + " \u00b7 " + chain.getTrips() + " trips";
		String heading = (full.length() > 24 ? chain.getKit().getName() : full).toUpperCase(Locale.ENGLISH);
		if (view.state == View.State.WAITING_FOR_BANK)
		{
			crest.update(heading, null, 0, false, -1, "Open your bank to begin", null, Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.3), Theme.GOLD);
			return;
		}
		if (chain.provisioned())
		{
			crest.update(heading, chain.getSteps().size(), chain.getSteps().size(), true, 1, "Every supply is stocked", "All stocked", Theme.GREEN, Theme.GREEN);
			return;
		}
		Step now = chain.current();
		String status;
		String shortStatus;
		Color color;
		if (now == null)
		{
			status = "Nothing left to do";
			shortStatus = null;
			color = Theme.TEXT_MUTED;
		}
		else if (now.getState() == Step.State.LOCKED)
		{
			status = "Needs " + Ui.skill(now.getUnmet().getSkill()) + " " + now.getUnmet().getLevel();
			shortStatus = null;
			color = Theme.BLOOD;
		}
		else
		{
			status = "Now: " + now.getRecipe().getVerb().label().toLowerCase(Locale.ENGLISH) + " " + view.name(now.getItem()).toLowerCase(Locale.ENGLISH);
			shortStatus = now.getRecipe().getVerb().label() + " " + Format.amount(now.getNet()) + " more";
			color = Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.45);
		}
		crest.update(heading, chain.doneCount(), chain.getSteps().size(), false, chain.progress(), status, shortStatus, color, Theme.GOLD);
	}

	private boolean waiting(StackPanel stack)
	{
		if (view.chain == null)
		{
			stack.add(note("The larder is closed", "Log in and Codex Provisioner walks you through gathering and making the supplies a kit needs, one step at a time, from the raw fish and grimy herbs to the finished potions."));
			return true;
		}
		if (view.state == View.State.WAITING_FOR_BANK)
		{
			stack.add(note("Open your bank once", "The Provisioner counts what you already hold at every stage of the chain. After the first look it remembers the bank as last seen, so the panel works anywhere. With Codex Bank Steward sharing its bank, this step is done for you."));
			return true;
		}
		return false;
	}

	// The Tree tab.

	/** Each supply as the tree of parts it is made from, root to leaves. */
	private void rebuildTree()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(treePage, stack);
			return;
		}
		Chain chain = view.chain;
		Step now = chain.current();
		stack.add(Ui.wrapped("Each supply from the finished product down to what is gathered by hand. A part already stocked needs nothing beneath it.",
			Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		for (Map.Entry<Chain.Line, List<Tree.Node>> tree : Tree.of(chain).entrySet())
		{
			Chain.Line line = tree.getKey();
			String trailing = line.getShort() <= 0 ? "stocked" : Format.amount(line.getShort()) + " short";
			stack.add(new SectionHeader(view.name(line.getSupply()), trailing));
			stack.add(new TreeCard(tree.getValue(), view, icons, now));
		}
		replace(treePage, stack);
	}

	// The Chain tab.

	private void rebuildChain()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(chainPage, stack);
			return;
		}
		Chain chain = view.chain;
		Step now = chain.current();
		if (chain.provisioned())
		{
			Card done = note("Provisioned", "Your bank holds everything " + chain.getTrips() + " trips of " + chain.getKit().getName()
				+ " take. Pick more trips in Stores to plan the next batch.");
			done.accent(Theme.GREEN);
			stack.add(done);
		}
		else if (now != null)
		{
			stack.add(new NowCard(chain, now, view, icons, WIDTH - 30));
		}
		String runway = runway(chain);
		if (runway != null && !chain.provisioned())
		{
			stack.add(Ui.wrapped(runway, Theme.small(), chain.readyTrips() == 0 ? Theme.EMBER : Theme.TEAL, WIDTH - 16));
		}
		if (!chain.provisioned())
		{
			sitting(stack, chain);
		}

		Map<String, List<Step>> groups = new LinkedHashMap<>();
		for (Step s : chain.getSteps())
		{
			groups.computeIfAbsent(s.getSupply(), k -> new ArrayList<>()).add(s);
		}
		for (Map.Entry<String, List<Step>> group : groups.entrySet())
		{
			Supply supply = Supplies.get(group.getKey());
			Chain.Line line = line(group.getKey());
			String trailing = line == null ? null : line.getShort() <= 0 ? "stocked" : Format.amount(line.getShort()) + " short";
			stack.add(new SectionHeader(supply == null ? "Supplies" : view.name(supply), trailing));
			Card card = new Card(new BorderLayout());
			StackPanel rows = new StackPanel(0, 0);
			List<Step> steps = group.getValue();
			for (int i = 0; i < steps.size(); i++)
			{
				rows.add(new StepRow(steps.get(i), view, steps.get(i) == now, i == steps.size() - 1, icons));
			}
			card.add(rows, BorderLayout.CENTER);
			stack.add(card);
		}
		if (!view.training.isEmpty())
		{
			double total = 0;
			for (com.codex.provisioner.core.Training.Gain g : view.training)
			{
				total += g.getXp();
			}
			stack.add(new SectionHeader("What it trains", Format.amount(Math.round(total)) + " xp"));
			Card card = new Card(new BorderLayout());
			StackPanel rows = new StackPanel(4, 0);
			for (int i = 0; i < view.training.size(); i++)
			{
				rows.add(new TrainRow(view.training.get(i), i == view.training.size() - 1));
			}
			card.add(rows, BorderLayout.CENTER);
			stack.add(card);
		}
		long work = 0;
		int untimed = 0;
		long herbSeeds = 0;
		int patches = 0;
		for (Step s : chain.getSteps())
		{
			if (s.getState() == Step.State.DONE)
			{
				continue;
			}
			com.codex.provisioner.core.HerbRuns.Plan herbs = view.herbRuns(s.getItem());
			long t = view.estimate(s.getItem());
			if (herbs != null)
			{
				// Herbs of different kinds share a run, each patch planted with whichever is needed.
				herbSeeds += herbs.getSeeds();
				patches = herbs.getPatches();
			}
			else if (t >= 0)
			{
				work += t;
			}
			else
			{
				untimed++;
			}
		}
		long herbRuns = patches == 0 ? 0 : (herbSeeds + patches - 1) / patches;
		if (work > 0 || herbRuns > 0)
		{
			List<String> parts = new ArrayList<>();
			if (herbRuns > 0)
			{
				parts.add(View.runs(herbRuns));
			}
			if (untimed > 0)
			{
				parts.add(untimed + (untimed == 1 ? " step" : " steps") + " that cannot be timed, such as drops and shop runs");
			}
			String time = (work > 0 ? "About " + Format.estimate(work) + " of work left" : "No timed work left")
				+ (parts.isEmpty() ? "." : ", plus " + String.join(" and ", parts) + ".");
			stack.add(Ui.wrapped(time, Theme.small(), Theme.TEXT_MUTED, WIDTH - 16));
		}
		String foot = view.measured >= 2
			? "Planned from " + view.measured + " trips Codex Quartermaster measured with this kit."
			: "Counts what your bank and inventory hold at every stage, so each step shrinks as you work.";
		stack.add(Ui.wrapped(foot, Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		if (!view.bankOpen && view.bankSeen > 0)
		{
			stack.add(Ui.wrapped(view.bankShared
					? "Bank as Codex Bank Steward saw it " + Format.ago(view.now - view.bankSeen) + "; open it once to count it here."
					: "Bank as last seen " + Format.ago(view.now - view.bankSeen),
				Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		}
		replace(chainPage, stack);
	}

	/** What one sitting of the chosen length gets through, the step in hand first. */
	private void sitting(StackPanel stack, Chain chain)
	{
		long budget = SITTINGS[Math.max(0, Math.min(SITTINGS.length - 1, sittingLength.getSelected()))] * 60_000L;
		java.util.Set<Integer> grown = new java.util.HashSet<>(view.herbRuns.keySet());
		Sitting plan = Sitting.plan(chain, view.estimates, grown, budget);
		boolean own = false;
		for (Sitting.Piece p : plan.getPieces())
		{
			own |= view.ownPace(p.getStep().getItem());
		}
		stack.add(new SectionHeader("In one sitting", own ? "at your pace" : "at a typical pace"));
		stack.add(sittingLength);
		Card card = new Card(new BorderLayout());
		StackPanel rows = new StackPanel(4, 0);
		if (plan.getPieces().isEmpty())
		{
			rows.add(Ui.wrapped("Nothing left can be worked in a sitting yet; it waits on what is grown, dropped or above your levels.",
				Theme.small(), Theme.TEXT_MUTED, WIDTH - 30));
		}
		for (Sitting.Piece p : plan.getPieces())
		{
			Step s = p.getStep();
			String what = s.getRecipe().getVerb().label() + " " + Format.amount(p.getAmount())
				+ (p.finishes() ? "" : " of " + Format.amount(s.getNet())) + " " + view.name(s.getItem()).toLowerCase(Locale.ENGLISH);
			JPanel row = new JPanel(new BorderLayout(6, 0));
			row.setOpaque(false);
			row.add(Ui.wrapped(what, Theme.small(), p.finishes() ? Theme.TEXT : Theme.mix(Theme.TEXT, Theme.GOLD, 0.35), WIDTH - 80), BorderLayout.CENTER);
			JPanel time = new JPanel(new BorderLayout());
			time.setOpaque(false);
			boolean shop = s.getRecipe().getVerb() == com.codex.provisioner.core.Verb.BUY;
			// Buying is quickly done, so it is given no time of its own.
			time.add(Ui.label(shop ? "" : Format.estimate(p.getMs()), Theme.small(), Theme.GOLD), BorderLayout.NORTH);
			row.add(time, BorderLayout.EAST);
			rows.add(row);
		}
		card.add(rows, BorderLayout.CENTER);
		stack.add(card);
		String foot;
		if (plan.isEverything())
		{
			foot = "That is every timed step, in about " + Format.estimate(plan.getUsed()) + ".";
		}
		else
		{
			int later = 0;
			int locked = 0;
			int untimed = 0;
			int waiting = 0;
			for (Step s : plan.getLeft())
			{
				switch (plan.reason(s, view.estimates, grown))
				{
					case LOCKED:
						locked++;
						break;
					case UNTIMED:
						untimed++;
						break;
					case WAITING:
						waiting++;
						break;
					default:
						later++;
						break;
				}
			}
			List<String> parts = new ArrayList<>();
			if (later > 0)
			{
				parts.add(later + (later == 1 ? " step" : " steps") + " for another sitting");
			}
			if (untimed > 0)
			{
				parts.add(untimed + (untimed == 1 ? " grown or untimed step" : " grown or untimed steps"));
			}
			if (waiting > 0)
			{
				parts.add(waiting + (waiting == 1 ? " step waiting on those" : " steps waiting on those"));
			}
			if (locked > 0)
			{
				parts.add(locked + (locked == 1 ? " step" : " steps") + " above your levels");
			}
			foot = parts.isEmpty() ? null : "Left after it: " + String.join(", ", parts) + ".";
		}
		if (foot != null)
		{
			stack.add(Ui.wrapped(foot, Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		}
	}

	/** "Ready for 4 of 10 trips now; prayer runs out first.", or null when the kit uses nothing up. */
	private String runway(Chain chain)
	{
		Chain.Line first = chain.limiting();
		if (first == null)
		{
			return null;
		}
		long ready = first.tripsHeld();
		String trips = ready >= chain.getTrips() ? ready + (ready == 1 ? " trip" : " trips")
			: ready + " of " + chain.getTrips() + " trips";
		String head = ready == 0 ? "Not stocked for a single trip yet." : "Ready for " + trips + " now.";
		return head + " First to run out: " + view.name(first.getSupply()).toLowerCase(java.util.Locale.ENGLISH) + ".";
	}

	private Chain.Line line(String supply)
	{
		for (Chain.Line l : view.chain.getLines())
		{
			if (l.getSupply().getKey().equals(supply))
			{
				return l;
			}
		}
		return null;
	}

	// The Stores tab.

	private void rebuildStores()
	{
		StackPanel stack = new StackPanel(8, 8);
		stack.add(new SectionHeader("Provision for", "trips"));
		stack.add(trips);
		if (waiting(stack))
		{
			replace(storesPage, stack);
			return;
		}
		Chain chain = view.chain;
		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
		tiles.setOpaque(false);
		int done = chain.doneCount();
		int total = chain.getSteps().size();
		Chain.Line first = chain.limiting();
		if (first != null)
		{
			long ready = first.tripsHeld();
			tiles.add(new StatTile(String.valueOf(ready), "Ready for", ready >= chain.getTrips() ? "trips, all stocked"
				: "of " + chain.getTrips() + " trips", ready >= chain.getTrips() ? Theme.GREEN : ready == 0 ? Theme.EMBER : Theme.GOLD));
		}
		else
		{
			tiles.add(new StatTile(total == 0 ? "-" : done + " / " + total, "Steps", chain.provisioned() ? "all done" : Format.percent(chain.progress()) + " of the way", Theme.GOLD));
		}
		List<Step> sources = chain.sources();
		tiles.add(new StatTile(String.valueOf(sources.size()), "To gather", sources.isEmpty() ? "nothing left" : sources.size() == 1 ? "one source" : "sources", sources.isEmpty() ? Theme.GREEN : Theme.TEAL));
		stack.add(tiles);

		stack.add(new SectionHeader("Supplies", chain.getKit().getName()));
		for (Chain.Line line : chain.getLines())
		{
			stack.add(new SupplyCard(line, view, icons, actions, WIDTH - 30));
		}

		if (!sources.isEmpty())
		{
			stack.add(new SectionHeader("Gathering list"));
			Card list = new Card(new BorderLayout());
			StackPanel rows = new StackPanel(2, 0);
			for (Step s : sources)
			{
				com.codex.provisioner.core.HerbRuns.Plan herbs = view.herbRuns(s.getItem());
				String note = s.getState() == Step.State.LOCKED
					? "Needs " + Ui.skill(s.getUnmet().getSkill()) + " " + s.getUnmet().getLevel()
					: herbs != null ? View.runs(herbs.getRuns()) + ", " + Format.amount(herbs.getSeeds()) + (herbs.getSeeds() == 1 ? " seed" : " seeds")
					: s.getRecipe().getVerb().label() + (s.getHeld() > 0 ? ", " + Format.amount(s.getHeld()) + " held" : "");
				rows.add(new SourceRow(s.getItem(), view.name(s.getItem()), note, Format.amount(s.getNet()),
					s.getState() == Step.State.LOCKED ? Theme.BLOOD : Theme.GOLD, s.getRecipe().getHow(), icons));
			}
			list.add(rows, BorderLayout.CENTER);
			stack.add(list);
		}
		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		buttons.setOpaque(false);
		buttons.add(new CodexButton("Restart progress bars", false, actions::restart));
		stack.add(buttons);
		stack.add(Ui.wrapped(view.iron
				? "Pick what each supply is made as; a red dot means a level in its chain is not reached yet. Iron account: no step needs trading with anyone."
				: "Pick what each supply is made as; a red dot means a level in its chain is not reached yet. Making is priced from bought ingredients at Grand Exchange prices.",
			Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		replace(storesPage, stack);
	}

	// The Kits tab.

	private void rebuildKits()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (view.chain == null)
		{
			waiting(stack);
			replace(kitsPage, stack);
			return;
		}
		Card intro = new Card(new BorderLayout(0, 4));
		intro.accent(Theme.TEAL);
		intro.add(Ui.label(view.quartermaster ? "Kits from Codex Quartermaster" : "Pick what you are stocking for", Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		intro.add(Ui.wrapped(view.quartermaster
				? "Your saved Quartermaster kits are here, and kits it has measured on real trips are planned from what you really used."
				: "Choose the content and the Provisioner plans every supply it takes. Kits you save in Codex Quartermaster show up here too.",
			Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		stack.add(intro);

		String chosen = view.chain.getKit().getId();
		boolean anySaved = false;
		for (View.KitSummary k : view.kits)
		{
			if (!k.kit.isPreset())
			{
				if (!anySaved)
				{
					stack.add(new SectionHeader("Your kits"));
					anySaved = true;
				}
				stack.add(new KitCard(k, k.kit.getId().equals(chosen), view.chain.getTrips(), () -> actions.kit(k.kit.getId()), WIDTH - 30));
			}
		}
		stack.add(new SectionHeader("Presets"));
		for (View.KitSummary k : view.kits)
		{
			if (k.kit.isPreset())
			{
				stack.add(new KitCard(k, k.kit.getId().equals(chosen), view.chain.getTrips(), () -> actions.kit(k.kit.getId()), WIDTH - 30));
			}
		}
		replace(kitsPage, stack);
	}

	static Card note(String title, String text)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD_DIM);
		card.add(Ui.label(title, Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		return card;
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.codex.provisioner.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.provisioner.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.codex.provisioner.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Arc2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/** The Provisioner's mark: a gilt mortar with its pestle, and a teal herb leaf rising from the bowl. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float stroke = Math.max(0.6f, 0.55f * s);
		g.setStroke(new BasicStroke(stroke, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

		// The leaf, behind the bowl: a pointed teal blade with a pale vein.
		Path2D leaf = new Path2D.Float();
		leaf.moveTo(x + 6.2f * s, y + 8.4f * s);
		leaf.curveTo(x + 3.6f * s, y + 5.6f * s, x + 4.4f * s, y + 2.2f * s, x + 7.4f * s, y + 0.8f * s);
		leaf.curveTo(x + 8.6f * s, y + 3.4f * s, x + 8.4f * s, y + 6.4f * s, x + 6.2f * s, y + 8.4f * s);
		leaf.closePath();
		g.setPaint(new GradientPaint(x, y, Theme.mix(Theme.TEAL, java.awt.Color.WHITE, 0.25f), x, y + 9 * s, Theme.mix(Theme.TEAL, Theme.INK_DEEP, 0.35f)));
		g.fill(leaf);
		g.setColor(Theme.INK_DEEP);
		g.draw(leaf);
		g.setColor(Theme.alpha(java.awt.Color.WHITE, 120));
		g.drawLine(Math.round(x + 6.4f * s), Math.round(y + 7.6f * s), Math.round(x + 7.2f * s), Math.round(y + 2.4f * s));

		// The pestle, leaning out of the bowl to the right.
		Path2D pestle = new Path2D.Float();
		pestle.moveTo(x + 8.6f * s, y + 9.4f * s);
		pestle.lineTo(x + 13.4f * s, y + 2.6f * s);
		pestle.lineTo(x + 15.0f * s, y + 3.8f * s);
		pestle.lineTo(x + 10.4f * s, y + 10.4f * s);
		pestle.closePath();
		g.setPaint(new GradientPaint(x + 9 * s, y, Theme.GOLD_BRIGHT, x + 15 * s, y + 10 * s, Theme.GOLD_DIM));
		g.fill(pestle);
		g.setColor(Theme.INK_DEEP);
		g.draw(pestle);

		// The bowl: a half round of gilt with a dark mouth and a foot.
		Arc2D bowl = new Arc2D.Float(x + 1.2f * s, y + 3.6f * s, 13.6f * s, 11.2f * s, 180, 180, Arc2D.CHORD);
		g.setPaint(new GradientPaint(x, y + 8 * s, Theme.GOLD, x, y + 15 * s, Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.4f)));
		g.fill(bowl);
		g.setColor(Theme.INK_DEEP);
		g.draw(bowl);
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.fill(new RoundRectangle2D.Float(x + 1.6f * s, y + 8.6f * s, 12.8f * s, 1.4f * s, 1.4f * s, 1.4f * s));
		g.setColor(Theme.alpha(java.awt.Color.WHITE, 70));
		g.drawLine(Math.round(x + 3.4f * s), Math.round(y + 10.8f * s), Math.round(x + 5.4f * s), Math.round(y + 12.6f * s));
		RoundRectangle2D foot = new RoundRectangle2D.Float(x + 5.2f * s, y + 14.0f * s, 5.6f * s, 1.6f * s, 0.8f * s, 0.8f * s);
		g.setColor(Theme.GOLD_DIM);
		g.fill(foot);
		g.setColor(Theme.INK_DEEP);
		g.draw(foot);
	}
}

package com.codex.provisioner.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JComponent;

/** One thing to gather: the item in its slot, how it is got, and how many are still needed. */
class SourceRow extends JComponent
{
	private final int itemId;
	private final String name;
	private final String note;
	private final String amount;
	private final Color color;
	private final ItemIcons icons;

	SourceRow(int itemId, String name, String note, String amount, Color color, String how, ItemIcons icons)
	{
		this.itemId = itemId;
		this.name = name;
		this.note = note;
		this.amount = amount;
		this.color = color;
		this.icons = icons;
		setOpaque(false);
		setPreferredSize(new Dimension(10, Well.SIZE + 4));
		setToolTipText("<html><b>" + Ui.escape(name) + "</b><br>" + Ui.escape(how) + "</html>");
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		Well.paint(g, 0, 2, icons == null || itemId < 0 ? null : icons.icon(itemId, this::repaint), null);
		int tx = Well.SIZE + 12;
		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		int aw = fm.stringWidth(amount);
		int base = 2 + fm.getAscent() + 1;
		Ui.shadowed(g, amount, w - aw, base, color);
		Ui.shadowed(g, Ui.clip(name, fm, w - tx - aw - 8), tx, base, Theme.TEXT);
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(Ui.clip(note, g.getFontMetrics(), w - tx), tx, 2 + Well.SIZE - 6);
		g.dispose();
	}
}

package com.codex.provisioner.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.provisioner.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, bold, w - 16), x + 8, y + 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.codex.provisioner.ui;

import com.codex.provisioner.core.Step;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.util.Locale;
import javax.swing.JComponent;

/**
 * One step of the chain: a mark for its state down the left like beads on a string, the item in
 * its slot, what to do and how far along it is, what is left on the right, and a slim bar.
 */
class StepRow extends JComponent
{
	static final int HEIGHT = Well.SIZE + 12;

	private final Step step;
	private final String name;
	private final boolean current;
	private final boolean last;
	private final ItemIcons icons;
	/** Time left on this step, or -1 when it cannot be told. */
	private final long estimate;
	/** Herb runs for a herb still to grow, or null. */
	private final com.codex.provisioner.core.HerbRuns.Plan herbs;

	StepRow(Step step, View view, boolean current, boolean last, ItemIcons icons)
	{
		this.step = step;
		this.name = view.shortName(step.getItem());
		this.herbs = view.herbRuns(step.getItem());
		this.current = current;
		this.last = last;
		this.icons = icons;
		this.estimate = view.estimate(step.getItem());
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		String time = estimate < 0 || step.getState() == Step.State.DONE ? ""
			: "<br>About " + Format.estimate(estimate) + (view.ownPace(step.getItem()) ? " at your own pace" : " at a typical pace");
		if (herbs != null && step.getState() != Step.State.DONE)
		{
			time = "<br>About " + View.runs(herbs.getRuns()) + " on " + herbs.getPatchesUsed() + (herbs.getPatchesUsed() == 1 ? " patch, " : " patches, ")
				+ Format.amount(herbs.getSeeds()) + (herbs.getSeeds() == 1 ? " seed" : " seeds");
		}
		setToolTipText("<html><b>" + Ui.escape(step.getRecipe().getVerb().label() + " " + view.name(step.getItem())) + "</b><br>"
			+ Ui.escape(step.getRecipe().getHow()) + time + "</html>");
	}

	static Color color(Step step, boolean current)
	{
		switch (step.getState())
		{
			case DONE:
				return Theme.GREEN;
			case LOCKED:
				return Theme.BLOOD;
			case WAITING:
				return Theme.TEXT_FAINT;
			default:
				return current ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		Color color = color(step, current);
		boolean done = step.getState() == Step.State.DONE;

		// The string between beads, then this step's bead.
		int cx = 6;
		int cy = 4 + Well.SIZE / 2;
		g.setColor(Theme.STROKE);
		g.drawLine(cx, 0, cx, cy - 6);
		if (!last)
		{
			g.drawLine(cx, cy + 6, cx, HEIGHT);
		}
		paintBead(g, cx, cy, step.getState(), current, color);

		int wx = 16;
		Well.paint(g, wx, 4, icons == null ? null : icons.icon(step.getItem(), this::repaint), current ? Theme.alpha(Theme.GOLD, 200) : null);
		int tx = wx + Well.SIZE + 10;

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		int base = 4 + bold.getAscent();
		String right;
		Color rightColor = color;
		if (done)
		{
			right = "done";
		}
		else if (step.getState() == Step.State.LOCKED)
		{
			right = "Lv " + step.getUnmet().getLevel();
		}
		else
		{
			right = Format.amount(step.getNet());
		}
		g.setFont(done || step.getState() == Step.State.LOCKED ? Theme.small() : Theme.title());
		FontMetrics rf = g.getFontMetrics();
		int rw = rf.stringWidth(right);
		Ui.shadowed(g, right, w - rw, base, rightColor);

		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		Color nameColor = done ? Theme.TEXT_MUTED : current ? Theme.TEXT : Theme.mix(Theme.TEXT, Theme.TEXT_MUTED, 0.3);
		Ui.shadowed(g, Ui.clip(name, fm, w - tx - rw - 8), tx, base, nameColor);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String verb = step.getRecipe().getVerb().label().toUpperCase(Locale.ENGLISH);
		g.setColor(done ? Theme.TEXT_FAINT : Theme.mix(color, Theme.TEXT_FAINT, 0.35));
		g.drawString(verb, tx, base + 13);
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(Ui.clip("  " + detail(), small, w - tx - small.stringWidth(verb)), tx + small.stringWidth(verb), base + 13);

		if (!done)
		{
			Bar.paint(g, tx, Well.SIZE + 5, w - tx, 3, step.progress());
		}
		g.dispose();
	}

	private String detail()
	{
		switch (step.getState())
		{
			case DONE:
				return step.getBaseline() > 0 ? Format.amount(step.getBaseline()) + " ready" : "enough in hand";
			case LOCKED:
				return "needs " + Ui.skill(step.getUnmet().getSkill()) + " " + step.getUnmet().getLevel();
			case WAITING:
				return "waits for inputs";
			default:
				long done = step.getDone();
				String[] pair = Format.pair(done, step.getBaseline());
				String text = done > 0 ? pair[0] + " of " + pair[1] : Format.amount(step.getNet()) + " to go";
				if (herbs != null)
				{
					return View.runs(herbs.getRuns());
				}
				return estimate >= 0 ? text + " \u00b7 " + Format.estimate(estimate) : text;
		}
	}

	static void paintBead(Graphics2D g, int cx, int cy, Step.State state, boolean current, Color color)
	{
		g.setStroke(new BasicStroke(1.4f));
		if (current)
		{
			g.setColor(Theme.alpha(Theme.GOLD, 60));
			g.fill(new Ellipse2D.Float(cx - 7, cy - 7, 14, 14));
			Path2D diamond = new Path2D.Float();
			diamond.moveTo(cx, cy - 5);
			diamond.lineTo(cx + 5, cy);
			diamond.lineTo(cx, cy + 5);
			diamond.lineTo(cx - 5, cy);
			diamond.closePath();
			g.setColor(Theme.GOLD_BRIGHT);
			g.fill(diamond);
			g.setColor(Theme.INK_DEEP);
			g.draw(diamond);
			return;
		}
		Ellipse2D bead = new Ellipse2D.Float(cx - 4.5f, cy - 4.5f, 9, 9);
		switch (state)
		{
			case DONE:
				g.setColor(color);
				g.fill(bead);
				g.setColor(Theme.INK_DEEP);
				Path2D tick = new Path2D.Float();
				tick.moveTo(cx - 2.4f, cy);
				tick.lineTo(cx - 0.6f, cy + 1.8f);
				tick.lineTo(cx + 2.6f, cy - 1.8f);
				g.draw(tick);
				break;
			case LOCKED:
				g.setColor(Theme.alpha(color, 60));
				g.fill(bead);
				g.setColor(color);
				g.draw(bead);
				g.drawLine(cx - 2, cy, cx + 2, cy);
				break;
			default:
				g.setColor(Theme.INK_DEEP);
				g.fill(bead);
				g.setColor(color);
				g.draw(bead);
		}
		g.setStroke(new BasicStroke(1f));
	}
}

package com.codex.provisioner.ui;

import com.codex.provisioner.core.Chain;
import com.codex.provisioner.core.Costing;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JComponent;
import javax.swing.JPanel;

/** One supply of the kit: how much of the target is held, and the items it can be made as to pick from. */
class SupplyCard extends Card
{
	SupplyCard(Chain.Line line, View view, ItemIcons icons, Actions actions, int width)
	{
		super(new BorderLayout(0, 6));
		boolean stocked = line.getShort() <= 0;
		accent(stocked ? Theme.GREEN : Theme.GOLD);
		add(new Gauge(line, view), BorderLayout.NORTH);
		if (line.getOptions().size() > 1)
		{
			JPanel chips = new JPanel(new GridLayout(0, 4, 4, 4));
			chips.setOpaque(false);
			String key = line.getSupply().getKey();
			for (int option : line.getOptions())
			{
				JPanel cell = new JPanel(new BorderLayout());
				cell.setOpaque(false);
				cell.add(new OptionChip(option, option == line.getProduct(), view, icons, () -> actions.choose(key, option)), BorderLayout.WEST);
				chips.add(cell);
			}
			add(chips, BorderLayout.CENTER);
		}
		String key = line.getSupply().getKey();
		boolean bought = view.bought.contains(key);
		String made = stocked
			? "Stocked for " + view.chain.getTrips() + " trips."
			: (bought ? "Buy " : "Make ") + Format.amount(line.getToMake()) + " " + view.name(line.getProduct()) + ".";
		Costing.Quote quote = stocked ? null : view.quotes.get(key);
		if (quote == null)
		{
			add(Ui.wrapped(made, Theme.small(), stocked ? Theme.GREEN : Theme.TEXT_MUTED, width), BorderLayout.SOUTH);
			return;
		}
		StackPanel south = new StackPanel(4, 0);
		south.add(Ui.wrapped(made, Theme.small(), Theme.TEXT_MUTED, width));
		south.add(new Ledger(quote, bought));
		if (quote.getMake() >= 0 && quote.getFromBank() > 0)
		{
			// Making's coins are only what is still to buy; what comes out of the bank is said apart.
			south.add(Ui.wrapped("Make is coins still to spend. It also uses " + Format.coins(quote.getFromBank())
				+ " of what you hold, at what it would sell for.", Theme.small(), Theme.TEAL, width));
		}
		south.add(Ui.wrapped(verdict(quote, bought), Theme.small(), Theme.TEXT_FAINT, width));
		// Something the exchange does not sell cannot be bought instead.
		if (bought || quote.getBuy() >= 0)
		{
			JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
			buttons.setOpaque(false);
			buttons.add(new CodexButton(bought ? "Make them instead" : "Buy them instead", false, () -> actions.buy(key, !bought)));
			south.add(buttons);
		}
		add(south, BorderLayout.SOUTH);
	}

	/** What the numbers mean for this supply, in a line. */
	static String verdict(Costing.Quote q, boolean bought)
	{
		String xp = xpText(q);
		if (!q.known())
		{
			return q.getBuy() < 0 ? "No exchange price for it, so making is the way." : "Some ingredients have no exchange price.";
		}
		if (bought)
		{
			return q.makeIsCheaper()
				? "Making would save " + Format.coins(q.saving()) + (xp.isEmpty() ? "." : " and give " + xp + ".")
				: "Buying is cheaper by " + Format.coins(-q.saving()) + ".";
		}
		if (q.getFromBank() > 0)
		{
			return withHeld(q, xp);
		}
		if (q.makeIsCheaper())
		{
			return "Making saves " + Format.coins(q.saving()) + (xp.isEmpty() ? "." : " and gives " + xp + ".");
		}
		if (q.coinsPerXp() > 0)
		{
			return "Making costs " + Format.coins(-q.saving()) + " more, " + String.format(java.util.Locale.ENGLISH, "%.1f", q.coinsPerXp())
				+ " gp a point for " + xp + ".";
		}
		return "Buying is cheaper by " + Format.coins(-q.saving()) + ".";
	}

	/**
	 * The verdict when making uses ingredients already held. Those cost no coins, but buying
	 * finished would leave them to sell, so the fair comparison counts them at their sale value;
	 * the coins alone are said too when the two disagree.
	 */
	static String withHeld(Costing.Quote q, String xp)
	{
		String gives = xp.isEmpty() ? "." : ", and gives " + xp + ".";
		if (q.makeIsCheaper())
		{
			return "Making saves " + Format.coins(q.saving()) + " even counting what your ingredients would sell for" + gives;
		}
		if (q.cashSaving() > 0)
		{
			return "Making spends " + Format.coins(q.cashSaving()) + " fewer coins, but selling what you hold and buying them finished comes out "
				+ Format.coins(-q.saving()) + " ahead.";
		}
		return "Buying is cheaper by " + Format.coins(-q.cashSaving()) + ", even counting what you hold as free.";
	}

	/** "42k Herblore xp", or "42k Herblore and 2,400 Cooking xp". */
	static String xpText(Costing.Quote q)
	{
		StringBuilder text = new StringBuilder();
		for (java.util.Map.Entry<net.runelite.api.Skill, Double> e : q.getXp().entrySet())
		{
			if (e.getValue() < 1)
			{
				continue;
			}
			if (text.length() > 0)
			{
				text.append(" and ");
			}
			text.append(Format.amount(Math.round(e.getValue()))).append(' ').append(Ui.skill(e.getKey()));
		}
		return text.length() == 0 ? "" : text.append(" xp").toString();
	}

	/** Buy against make, side by side, the cheaper one lit. */
	private static final class Ledger extends JComponent
	{
		private final Costing.Quote quote;
		private final boolean bought;

		Ledger(Costing.Quote quote, boolean bought)
		{
			this.quote = quote;
			this.bought = bought;
			setOpaque(false);
			setPreferredSize(new Dimension(10, 30));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			int w = getWidth();
			int half = (w - 6) / 2;
			boolean makeWins = quote.makeIsCheaper() || quote.getBuy() < 0;
			cell(g, 0, half, "BUY", quote.getBuy() < 0 ? "-" : Format.coins(quote.getBuy()), bought, !makeWins && quote.known());
			cell(g, half + 6, half, "MAKE", quote.getMake() < 0 ? "-" : Format.coins(quote.getMake()), !bought, makeWins && quote.getMake() >= 0);
			g.dispose();
		}

		private static void cell(Graphics2D g, int x, int w, String label, String value, boolean chosen, boolean cheaper)
		{
			java.awt.geom.RoundRectangle2D r = new java.awt.geom.RoundRectangle2D.Float(x + 0.5f, 0.5f, w - 1, 29, 6, 6);
			g.setColor(Theme.INK_DEEP);
			g.fill(r);
			g.setColor(chosen ? Theme.alpha(Theme.GOLD, 170) : Theme.STROKE_SOFT);
			g.draw(r);
			g.setFont(Theme.small());
			FontMetrics small = g.getFontMetrics();
			g.setColor(chosen ? Theme.GOLD : Theme.TEXT_FAINT);
			g.drawString(label, x + 6, 3 + small.getAscent());
			if (chosen)
			{
				// The way the chain is planned: a small gilt pip beside the label.
				g.setColor(Theme.GOLD);
				g.fillOval(x + 6 + small.stringWidth(label) + 4, 6, 5, 5);
			}
			g.setFont(Theme.title());
			FontMetrics bold = g.getFontMetrics();
			Ui.shadowed(g, Ui.clip(value, bold, w - 12), x + 6, 26, cheaper ? Theme.GREEN : Theme.TEXT);
		}
	}

	private static final class Gauge extends JComponent
	{
		private final Chain.Line line;
		private final String name;

		Gauge(Chain.Line line, View view)
		{
			this.line = line;
			this.name = view.name(line.getSupply());
			setOpaque(false);
			setPreferredSize(new Dimension(10, 26));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			int w = getWidth();
			double share = line.getWant() <= 0 ? 1 : Math.min(1, line.getHave() / (double) line.getWant());
			Color color = share >= 1 ? Theme.GREEN : Theme.GOLD;
			g.setFont(Theme.small());
			FontMetrics small = g.getFontMetrics();
			String[] pair = Format.pair(line.getHave(), line.getWant());
			String figures = pair[0] + " / " + pair[1] + View.unit(line.getSupply());
			int fw = small.stringWidth(figures);
			g.setFont(Theme.body());
			FontMetrics fm = g.getFontMetrics();
			if (fm.stringWidth(name) > w - fw - 8)
			{
				// The name matters more than the unit, which the bar and the tooltip carry.
				figures = pair[0] + " / " + pair[1];
				fw = small.stringWidth(figures);
			}
			Ui.shadowed(g, Ui.clip(name, fm, w - fw - 8), 0, fm.getAscent(), Theme.TEXT);
			g.setFont(Theme.small());
			g.setColor(color);
			g.drawString(figures, w - fw, fm.getAscent());
			Bar.paint(g, 0, 20, w, 4, share);
			g.dispose();
		}
	}
}

package com.codex.provisioner.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * The Provisioner keeps gold for the step in hand, teal for what is done and blood for what
 * your levels do not reach yet, so the chain reads at a glance.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** Item quantities in the game's own colours: yellow, white from 100K, green from 10M. */
	public static final Color QTY_YELLOW = new Color(255, 255, 0);
	public static final Color QTY_WHITE = new Color(255, 255, 255);
	public static final Color QTY_GREEN = new Color(0, 255, 128);

	/**
	 * How long a supply lasts, as a colour: blood when it is out or will not last the trip,
	 * ember when only a few trips are left, gold when it is comfortable and green when plentiful.
	 */
	public static Color trips(int trips, int warn)
	{
		if (trips <= 0)
		{
			return BLOOD;
		}
		if (trips <= warn)
		{
			return EMBER;
		}
		if (trips >= warn * 8)
		{
			return GREEN;
		}
		return GOLD;
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.provisioner.ui;

import com.codex.provisioner.core.Training;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JComponent;

/**
 * One skill the rest of the chain trains: the experience it gives, the level now and the level it
 * ends at, and a bar for how far into that level the chain leaves the skill.
 */
class TrainRow extends JComponent
{
	private final Training.Gain gain;
	private final boolean last;

	TrainRow(Training.Gain gain, boolean last)
	{
		this.gain = gain;
		this.last = last;
		int before = gain.levelBefore();
		int after = gain.levelAfter();
		setToolTipText(Ui.skill(gain.getSkill()) + ": " + Format.amount(Math.round(gain.getXp())) + " xp, "
			+ (after > before ? "level " + before + " to " + after : "still level " + before));
		setOpaque(false);
		setPreferredSize(new Dimension(10, last ? 30 : 34));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int before = gain.levelBefore();
		int after = gain.levelAfter();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String levels = after > before ? before + " to " + after : "stays " + before;
		int lw = small.stringWidth(levels);
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(Ui.skill(gain.getSkill()), body, w - lw - 8), 0, body.getAscent(), Theme.TEXT);
		g.setFont(Theme.small());
		g.setColor(after > before ? Theme.GOLD : Theme.TEXT_FAINT);
		g.drawString(levels, w - lw, body.getAscent());

		// The experience, with a bar for how far into the level it ends at; teal throughout, since this is no warning.
		int base = body.getHeight() + small.getAscent();
		String xp = "+" + Format.amount(Math.round(gain.getXp())) + " xp";
		int xw = small.stringWidth(xp);
		g.setColor(Theme.TEAL);
		g.drawString(xp, w - xw, base);
		int bw = w - xw - 8;
		int y = base - small.getAscent() / 2 - 1;
		g.setColor(Theme.INK_DEEP);
		g.fill(new java.awt.geom.RoundRectangle2D.Float(0, y, bw, 4, 4, 4));
		float fill = (float) (bw * gain.progressAfter());
		if (fill > 0)
		{
			g.setColor(Theme.alpha(Theme.TEAL, 200));
			g.fill(new java.awt.geom.RoundRectangle2D.Float(0, y, Math.max(4, fill), 4, 4, 4));
		}
		if (!last)
		{
			g.setColor(Theme.STROKE_SOFT);
			g.drawLine(0, getHeight() - 1, w, getHeight() - 1);
		}
		g.dispose();
	}
}

package com.codex.provisioner.ui;

import com.codex.provisioner.core.Step;
import com.codex.provisioner.core.Tree;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Locale;
import javax.swing.JComponent;

/**
 * One supply's tree on a card: the finished product at the top and, branching beneath on gilt
 * lines, everything that goes into it down to what is gathered by hand. Each part shows its
 * picture ringed in its state's colour, its name, what is done to it and how many are still to
 * get, or a tick once enough is stocked. Painted in one pass, so a deep tree costs one component.
 */
class TreeCard extends JComponent
{
	static final int ROW = 30;
	private static final int PAD = 8;
	private static final int INDENT = 12;
	private static final int ICON = 22;

	private final List<Tree.Node> nodes;
	private final View view;
	private final ItemIcons icons;
	private final Step current;

	TreeCard(List<Tree.Node> nodes, View view, ItemIcons icons, Step current)
	{
		this.nodes = nodes;
		this.view = view;
		this.icons = icons;
		this.current = current;
		setOpaque(false);
		int h = nodes.size() * ROW + PAD * 2;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		StringBuilder tip = new StringBuilder("<html>");
		for (Tree.Node n : nodes)
		{
			tip.append("&nbsp;".repeat(n.getDepth() * 3)).append(Ui.escape(view.name(n.getItem()))).append(": ").append(Ui.escape(line(n))).append("<br>");
		}
		setToolTipText(tip.append("</html>").toString());
	}

	/** The node's centre line for a depth: where its picture sits and its branch hangs from. */
	private static int column(int depth)
	{
		return PAD + depth * INDENT + ICON / 2;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, getHeight() - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, getHeight(), Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		for (int i = 0; i < nodes.size(); i++)
		{
			Tree.Node n = nodes.get(i);
			int top = PAD + i * ROW;
			int mid = top + ROW / 2;
			int d = n.getDepth();
			boolean opened = i + 1 < nodes.size() && nodes.get(i + 1).getDepth() == d + 1;

			// The lines: rails of branches still running, this node's elbow, and its own branch down.
			g.setStroke(new BasicStroke(1f));
			g.setColor(Theme.alpha(Theme.GOLD_DIM, 150));
			for (int k = 0; k < d - 1; k++)
			{
				if (n.rail(k))
				{
					g.drawLine(column(k), top, column(k), top + ROW);
				}
			}
			if (d > 0)
			{
				int cx = column(d - 1);
				g.drawLine(cx, top, cx, n.isLast() ? mid : top + ROW);
				g.drawLine(cx, mid, PAD + d * INDENT - 1, mid);
			}
			if (opened)
			{
				g.drawLine(column(d), mid + ICON / 2, column(d), top + ROW);
			}

			Color tone = tone(n);
			int ix = PAD + d * INDENT;
			int iy = mid - ICON / 2;
			chip(g, ix, iy, tone, n);
			BufferedImage icon = icons == null ? null : icons.icon(n.getItem(), this::repaint);
			if (icon != null)
			{
				double scale = Math.min(1, (ICON - 2) / (double) Math.max(icon.getWidth(), icon.getHeight()));
				int iw = (int) Math.round(icon.getWidth() * scale);
				int ih = (int) Math.round(icon.getHeight() * scale);
				java.awt.Composite old = g.getComposite();
				if (n.isRepeat())
				{
					g.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.55f));
				}
				g.drawImage(icon, ix + (ICON - iw) / 2, iy + (ICON - ih) / 2, iw, ih, null);
				g.setComposite(old);
			}

			int tx = ix + ICON + 6;
			String figure = figure(n);
			g.setFont(Theme.body());
			int fw = body.stringWidth(figure);
			Color figureColor = n.isDone() ? Theme.GREEN : n.getStep() != null && n.getStep().getState() == Step.State.LOCKED ? Theme.BLOOD
				: n.getStep() != null && n.getStep().getState() == Step.State.WAITING ? Theme.TEXT_MUTED : Theme.GOLD_BRIGHT;
			if (n.isRepeat())
			{
				figureColor = Theme.TEXT_FAINT;
			}
			String name = view.shortName(n.getItem());
			String under = line(n);
			Layout at = layout(name, under, figure, body, small, w - PAD - tx);
			// Deep in a tree a long name first steps down a face, then takes the whole line,
			// its count moving down beside the shorter line under it.
			int figureY = at.figureBelow ? mid + small.getAscent() + 1 : mid - 1;
			if (at.figureBelow)
			{
				g.setFont(Theme.small());
				Ui.shadowed(g, figure, w - PAD - small.stringWidth(figure), figureY, figureColor);
			}
			else
			{
				Ui.shadowed(g, figure, w - PAD - fw, figureY, figureColor);
			}
			FontMetrics face = at.smallName ? small : body;
			g.setFont(at.smallName ? Theme.small() : Theme.body());
			Ui.shadowed(g, Ui.clip(name, face, at.nameRoom), tx, mid - 1, n.isRepeat() || n.isDone() ? Theme.TEXT_MUTED : Theme.TEXT);
			g.setFont(Theme.small());
			g.setColor(n.isRepeat() ? Theme.TEXT_FAINT : Theme.mix(tone, Theme.TEXT_MUTED, 0.45));
			g.drawString(Ui.clip(fit(under, small, at.lineRoom), small, at.lineRoom), tx, mid + small.getAscent() + 1);
			g.setFont(Theme.body());
		}
		g.dispose();
	}

	/** Where a row's name, its count and the line under it go, and how much room each has. */
	static final class Layout
	{
		final boolean smallName;
		final boolean figureBelow;
		final int nameRoom;
		final int lineRoom;

		Layout(boolean smallName, boolean figureBelow, int nameRoom, int lineRoom)
		{
			this.smallName = smallName;
			this.figureBelow = figureBelow;
			this.nameRoom = nameRoom;
			this.lineRoom = lineRoom;
		}
	}

	/**
	 * Fits a row into the width right of its picture. The name keeps the large face beside its
	 * count where it can, else steps down a face; if it is still too long, the count moves to the
	 * end of the line under it so the name has the whole width.
	 */
	static Layout layout(String name, String under, String figure, FontMetrics body, FontMetrics small, int room)
	{
		int beside = room - body.stringWidth(figure) - 6;
		if (body.stringWidth(name) <= beside)
		{
			return new Layout(false, false, beside, room);
		}
		if (small.stringWidth(name) <= beside)
		{
			return new Layout(true, false, beside, room);
		}
		int below = room - small.stringWidth(figure) - 6;
		return new Layout(body.stringWidth(name) > room, true, room, below);
	}

	/**
	 * The line under a name, cut to its point when it will not fit whole: "grow, 4 herb runs"
	 * becomes "4 herb runs", since the picture and the name already say what the part is.
	 */
	static String fit(String under, FontMetrics fm, int room)
	{
		int comma = under.indexOf(", ");
		if (fm.stringWidth(under) <= room || comma < 0)
		{
			return under;
		}
		return under.substring(comma + 2);
	}

	/** The colour of a part: done in green, the step in hand bright, ready in gold, waiting faint, locked red. */
	private Color tone(Tree.Node n)
	{
		if (n.getStep() == null)
		{
			return Theme.GREEN;
		}
		return StepRow.color(n.getStep(), n.getStep() == current);
	}

	/** The count to the right: how many are still to get, or a tick once enough is stocked. */
	private static String figure(Tree.Node n)
	{
		if (n.isDone())
		{
			return "✓";
		}
		return Format.amount(n.getStep().getNet());
	}

	/** The line under the name: what is done to the part and where it stands. */
	private String line(Tree.Node n)
	{
		Step s = n.getStep();
		if (s == null)
		{
			return "stocked";
		}
		String verb = s.getRecipe().getVerb().label().toLowerCase(Locale.ENGLISH);
		com.codex.provisioner.core.HerbRuns.Plan herbs = s.getState() == Step.State.DONE ? null : view.herbRuns(s.getItem());
		if (herbs != null && !n.isRepeat())
		{
			// Herbs still to grow are herb runs, as the Chain tab plans them.
			return "grow, " + View.runs(herbs.getRuns());
		}
		if (n.isRepeat())
		{
			return verb + ", counted above";
		}
		switch (s.getState())
		{
			case DONE:
				return "enough in hand";
			case LOCKED:
				return "needs " + Ui.skill(s.getUnmet().getSkill()) + " " + s.getUnmet().getLevel();
			case WAITING:
				return verb + ", waiting";
			default:
				return s == current ? verb + ", the step in hand" : verb + ", ready";
		}
	}

	/** The picture's setting: a dark round well with a ring in the part's colour, glowing for the step in hand. */
	private void chip(Graphics2D g, int x, int y, Color tone, Tree.Node n)
	{
		boolean now = n.getStep() != null && n.getStep() == current;
		if (now)
		{
			g.setColor(Theme.alpha(tone, 50));
			g.fill(new Ellipse2D.Float(x - 3, y - 3, ICON + 6, ICON + 6));
		}
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Float(x, y, ICON, ICON));
		g.setStroke(new BasicStroke(now ? 1.4f : 1f));
		g.setColor(Theme.alpha(tone, n.isRepeat() ? 70 : 170));
		g.draw(new Ellipse2D.Float(x + 0.5f, y + 0.5f, ICON - 1, ICON - 1));
		if (n.isDone() && !n.isRepeat())
		{
			// A small green seal on the rim: this part is stocked.
			float cx = x + ICON - 3;
			float cy = y + ICON - 3;
			g.setColor(Theme.INK_DEEP);
			g.fill(new Ellipse2D.Float(cx - 4, cy - 4, 8, 8));
			Path2D d = new Path2D.Float();
			d.moveTo(cx, cy - 3);
			d.lineTo(cx + 3, cy);
			d.lineTo(cx, cy + 3);
			d.lineTo(cx - 3, cy);
			d.closePath();
			g.setColor(Theme.GREEN);
			g.fill(d);
		}
	}
}

package com.codex.provisioner.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}

	/** A skill's name as the game writes it: "Herblore". */
	public static String skill(net.runelite.api.Skill skill)
	{
		return skill.getName();
	}
}

package com.codex.provisioner.ui;

import com.codex.provisioner.core.Chain;
import com.codex.provisioner.core.Costing;
import com.codex.provisioner.core.HerbRuns;
import com.codex.provisioner.core.Kit;
import com.codex.provisioner.core.Loads;
import com.codex.provisioner.core.Supply;
import com.codex.provisioner.core.Training;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;

/** Everything the panel shows, worked out on the client thread and handed over whole. */
public final class View
{
	public enum State
	{
		LOGGED_OUT,
		WAITING_FOR_BANK,
		READY
	}

	/** A kit in the Kits tab with what its chain would take. */
	public static final class KitSummary
	{
		final Kit kit;
		final int steps;
		final int shortSupplies;
		final int measured;
		/** Whole trips what is held covers now, or -1 when the kit uses nothing up. */
		long ready = -1;

		public KitSummary(Kit kit, int steps, int shortSupplies, int measured)
		{
			this.kit = kit;
			this.steps = steps;
			this.shortSupplies = shortSupplies;
			this.measured = measured;
		}

		public KitSummary ready(long trips)
		{
			this.ready = trips;
			return this;
		}
	}

	final State state;
	final Chain chain;
	final List<KitSummary> kits;
	final Map<Integer, String> names;
	final Map<Integer, Long> held;
	final Map<Skill, Integer> levels;
	final boolean quartermaster;
	final int measured;
	final long bankSeen;
	final boolean bankOpen;
	final long now;
	/** An iron account, which makes everything and is shown no prices. */
	boolean iron = true;
	Set<String> bought = Collections.emptySet();
	/** Buy or make for each supply still to fill, for accounts that can trade. */
	Map<String, Costing.Quote> quotes = Collections.emptyMap();
	/** Each open step's time left in milliseconds, -1 when it cannot be told. */
	Map<Integer, Long> estimates = Collections.emptyMap();
	/** Whether a step's estimate comes from the player's own pace rather than a typical one. */
	Map<Integer, Boolean> measuredPace = Collections.emptyMap();
	/** How the step in hand splits into inventories, or null. */
	Loads loads;
	/** What the rest of the chain trains, the most experience first. */
	List<Training.Gain> training = Collections.emptyList();
	/** Herb runs for each grimy herb still to grow, by the grimy herb. */
	Map<Integer, HerbRuns.Plan> herbRuns = Collections.emptyMap();
	/** The bank as last seen is the one Codex Bank Steward shared. */
	boolean bankShared;

	public View(State state, Chain chain, List<KitSummary> kits, Map<Integer, String> names, Map<Integer, Long> held,
		Map<Skill, Integer> levels, boolean quartermaster, int measured, long bankSeen, boolean bankOpen, long now)
	{
		this.state = state;
		this.chain = chain;
		this.kits = kits;
		this.names = names;
		this.held = held;
		this.levels = levels;
		this.quartermaster = quartermaster;
		this.measured = measured;
		this.bankSeen = bankSeen;
		this.bankOpen = bankOpen;
		this.now = now;
	}

	public static View loggedOut()
	{
		return new View(State.LOGGED_OUT, null, Collections.emptyList(), Collections.emptyMap(), Collections.emptyMap(),
			Collections.emptyMap(), false, 0, 0, false, 0);
	}

	public View trade(boolean iron, Set<String> bought, Map<String, Costing.Quote> quotes)
	{
		this.iron = iron;
		this.bought = bought == null ? Collections.emptySet() : new HashSet<>(bought);
		this.quotes = quotes == null ? Collections.emptyMap() : quotes;
		return this;
	}

	public View pace(Map<Integer, Long> estimates, Map<Integer, Boolean> measured)
	{
		this.estimates = estimates == null ? Collections.emptyMap() : estimates;
		this.measuredPace = measured == null ? Collections.emptyMap() : measured;
		return this;
	}

	public View work(Loads loads, List<Training.Gain> training)
	{
		this.loads = loads;
		this.training = training == null ? Collections.emptyList() : training;
		return this;
	}

	public View herbs(Map<Integer, HerbRuns.Plan> plans)
	{
		this.herbRuns = plans == null ? Collections.emptyMap() : plans;
		return this;
	}

	public View shared(boolean bankShared)
	{
		this.bankShared = bankShared;
		return this;
	}

	/** The herb runs a step takes, or null when it is not grown in herb patches. */
	HerbRuns.Plan herbRuns(int itemId)
	{
		return herbRuns.get(itemId);
	}

	/** Herb runs, said the way a player would: "1 herb run", "3 herb runs". */
	static String runs(long n)
	{
		return n + (n == 1 ? " herb run" : " herb runs");
	}

	/** A step's time left, or -1 when it cannot be told. */
	long estimate(int itemId)
	{
		return estimates.getOrDefault(itemId, -1L);
	}

	boolean ownPace(int itemId)
	{
		return measuredPace.getOrDefault(itemId, false);
	}

	String name(int itemId)
	{
		String n = names.get(itemId);
		return n == null ? "Item " + itemId : n;
	}

	/**
	 * A name short enough for a row: "Ranarr potion (unf)" reads as "Ranarr (unf)", since the
	 * vial is plain from the step around it.
	 */
	String shortName(int itemId)
	{
		String n = name(itemId).replace(" potion (unf)", " (unf)");
		// "Grimy ranarr weed" is plain as "Grimy ranarr"; dwarf weed is the herb's whole name.
		return n.startsWith("Grimy ") && n.endsWith(" weed") && !n.endsWith("dwarf weed") ? n.substring(0, n.length() - 5) : n;
	}

	String name(Supply supply)
	{
		return supply.getName() != null ? supply.getName() : name(supply.getIcon());
	}

	/** " hp", " doses" or "" for supplies counted in items. */
	static String unit(Supply supply)
	{
		return supply.getUnit() == null ? "" : " " + supply.getUnit();
	}

	long held(int itemId)
	{
		return held.getOrDefault(itemId, 0L);
	}

	Integer level(Skill skill)
	{
		return levels.get(skill);
	}
}

package com.codex.provisioner.ui;

import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/** The dark slot an item sits in, like a bank slot, with the stack drawn in the game's colours. */
final class Well
{
	static final int SIZE = 32;

	private Well()
	{
	}

	static void paint(Graphics2D g, int x, int y, BufferedImage icon, Color rim)
	{
		RoundRectangle2D well = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, SIZE + 4, SIZE - 1, 7, 7);
		g.setPaint(new GradientPaint(0, y, Theme.INK_DEEP, 0, y + SIZE, Theme.mix(Theme.INK_DEEP, Theme.CARD, 0.6)));
		g.fill(well);
		g.setColor(rim == null ? Theme.STROKE_SOFT : rim);
		g.draw(well);
		if (icon != null)
		{
			g.drawImage(icon, x + 2 + (SIZE - icon.getWidth()) / 2, y + (SIZE - icon.getHeight()) / 2 + 1, null);
		}
	}
}

package com.codex.provisioner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.Test;

/** Every setting has a short name, one plain sentence and a place of its own, worded as across the suite. */
public class SettingsTest
{
	@Test
	public void everySettingIsNamedAndPlacedClearly()
	{
		Set<String> sections = new HashSet<>();
		for (Field f : CodexProvisionerConfig.class.getFields())
		{
			if (f.isAnnotationPresent(ConfigSection.class))
			{
				ConfigSection section = f.getAnnotation(ConfigSection.class);
				assertFalse(section.name().isEmpty());
				assertFalse(section.description().isEmpty());
				try
				{
					sections.add((String) f.get(null));
				}
				catch (IllegalAccessException e)
				{
					throw new AssertionError(e);
				}
			}
		}
		Set<String> places = new HashSet<>();
		Set<String> names = new HashSet<>();
		for (Method m : CodexProvisionerConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item == null || item.hidden())
			{
				continue;
			}
			String name = item.name();
			String description = item.description();
			assertTrue(m.getName(), !name.isEmpty() && name.length() <= 26);
			assertTrue(m.getName(), names.add(name));
			assertTrue(m.getName(), Character.isUpperCase(name.charAt(0)) && !name.endsWith("."));
			assertTrue(m.getName() + " " + description.length(), description.length() >= 20 && description.length() <= 220);
			assertTrue(m.getName(), Character.isUpperCase(description.charAt(0)) && !description.endsWith("."));
			// Top-level settings come first; any other sits in a section that exists.
			assertTrue(m.getName() + " is in no known section", item.section().isEmpty() || sections.contains(item.section()));
			assertTrue(m.getName() + " shares its place", places.add(item.section() + "#" + item.position()));
			if ("nameOnCard".equals(item.keyName()))
			{
				assertEquals("Name on cards", name);
			}
			if ("worthOnCard".equals(item.keyName()))
			{
				assertEquals("Worth on cards", name);
			}
		}
		assertFalse(names.isEmpty());
	}

	@Test
	public void savedSettingsKeepTheirKeys()
	{
		// A setting's key is where its value is saved: renaming one quietly resets it for every player
		// who changed it. These are the keys as released; settings may be added and renamed on screen,
		// but not moved.
		assertEquals("codexprovisioner", CodexProvisionerConfig.GROUP);
		Set<String> keys = new HashSet<>();
		for (Method m : CodexProvisionerConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				keys.add(item.keyName());
			}
		}
		for (String key : new String[]{"announce", "measured", "plaque"})
		{
			assertTrue(key, keys.contains(key));
		}
	}
}

package com.codex.provisioner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class ChainTest
{
	private static Kit kit(Object... pairs)
	{
		Need[] needs = new Need[pairs.length / 2];
		for (int i = 0; i < needs.length; i++)
		{
			needs[i] = new Need((String) pairs[i * 2], (Integer) pairs[i * 2 + 1]);
		}
		return new Kit("test", "Test", Arrays.asList(needs), false);
	}

	private static Map<Skill, Integer> levels(int all)
	{
		Map<Skill, Integer> m = new EnumMap<>(Skill.class);
		for (Skill s : Skill.values())
		{
			m.put(s, all);
		}
		return m;
	}

	private static Step step(Chain c, int item)
	{
		for (Step s : c.getSteps())
		{
			if (s.getItem() == item)
			{
				return s;
			}
		}
		return null;
	}

	private static Chain build(Kit kit, int trips, Map<Integer, Long> held, Map<Skill, Integer> levels)
	{
		return Chain.build(kit, Collections.emptyMap(), trips, Collections.emptyMap(), held, levels, Collections.emptyMap());
	}

	@Test
	public void prayerChainFromNothing()
	{
		// 12 doses a trip for 10 trips is 120 doses, which is 40 three-dose potions.
		Chain c = build(kit("PRAYER", 12), 10, new HashMap<>(), levels(99));
		assertEquals(ItemID._3DOSEPRAYERRESTORE, c.getLines().get(0).getProduct());
		assertEquals(40, step(c, ItemID._3DOSEPRAYERRESTORE).getNet());
		assertEquals(40, step(c, ItemID.RANARRVIAL).getNet());
		assertEquals(40, step(c, ItemID.UNIDENTIFIED_RANARR).getNet());
		assertEquals(40, step(c, ItemID.VIAL_EMPTY).getNet());
		assertEquals(40, step(c, ItemID.SNAPE_GRASS).getNet());
		// Gathering leads.
		assertEquals(ItemID.UNIDENTIFIED_RANARR, c.getSteps().get(0).getItem());
		assertEquals(ItemID._3DOSEPRAYERRESTORE, c.getSteps().get(c.getSteps().size() - 1).getItem());
	}

	@Test
	public void heldStagesAreTakenOff()
	{
		Map<Integer, Long> held = new HashMap<>();
		held.put(ItemID._4DOSEPRAYERRESTORE, 10L); // 40 doses
		held.put(ItemID.RANARR_WEED, 15L);
		held.put(ItemID.VIAL_WATER, 100L);
		Chain c = build(kit("PRAYER", 12), 10, held, levels(99));
		// 80 doses short, 27 potions to make.
		assertEquals(80, c.getLines().get(0).getShort());
		assertEquals(27, step(c, ItemID._3DOSEPRAYERRESTORE).getNet());
		assertEquals(12, step(c, ItemID.UNIDENTIFIED_RANARR).getNet());
		assertEquals(Step.State.DONE, step(c, ItemID.VIAL_WATER).getState());
		assertNull(step(c, ItemID.VIAL_EMPTY));
		// Fifteen clean herbs and plenty of water: unfinished potions can be made now.
		assertEquals(15, step(c, ItemID.RANARRVIAL).getCanNow());
		assertEquals(ItemID.RANARRVIAL, c.current().getItem());
	}

	@Test
	public void decantingNeedsFourThreeDoseForThreeFourDose()
	{
		Chain c = build(kit("COMBAT", 4), 9, new HashMap<>(), levels(99));
		// 36 doses, 9 super combats, each one 4-dose super attack: 3 decants of 4 three-dose.
		assertEquals(9, step(c, ItemID._4DOSE2COMBAT).getNet());
		assertEquals(9, step(c, ItemID._4DOSE2ATTACK).getNet());
		assertEquals(12, step(c, ItemID._3DOSE2ATTACK).getNet());
		assertEquals(9, step(c, ItemID.TORSTOL).getNet());
	}

	@Test
	public void sharedVialsAreCountedOnce()
	{
		Chain c = build(kit("PRAYER", 3, "RANGING", 3), 10, new HashMap<>(), levels(99));
		assertEquals(20, step(c, ItemID.VIAL_WATER).getNet());
		long vialSteps = c.getSteps().stream().filter(s -> s.getItem() == ItemID.VIAL_WATER).count();
		assertEquals(1, vialSteps);
	}

	@Test
	public void foodPicksBestFishTheLevelsReach()
	{
		Map<Skill, Integer> lv = levels(70);
		lv.put(Skill.FISHING, 78);
		lv.put(Skill.COOKING, 81);
		Chain c = build(kit("FOOD", 200), 5, new HashMap<>(), lv);
		assertEquals(ItemID.SHARK, c.getLines().get(0).getProduct());
		assertEquals(50, step(c, ItemID.RAW_SHARK).getNet());

		lv.put(Skill.FISHING, 40);
		lv.put(Skill.COOKING, 40);
		c = build(kit("FOOD", 200), 5, new HashMap<>(), lv);
		assertEquals(ItemID.LOBSTER, c.getLines().get(0).getProduct());
	}

	@Test
	public void lockedStepsSayWhy()
	{
		Map<Skill, Integer> lv = levels(99);
		lv.put(Skill.HERBLORE, 60);
		Map<String, Integer> pick = new HashMap<>();
		pick.put("BREW", ItemID._3DOSEPOTIONOFSARADOMIN);
		Chain c = Chain.build(kit("BREW", 12), Collections.emptyMap(), 2, pick, new HashMap<>(), lv, Collections.emptyMap());
		Step brew = step(c, ItemID._3DOSEPOTIONOFSARADOMIN);
		assertEquals(Step.State.LOCKED, brew.getState());
		assertEquals(81, brew.getUnmet().getLevel());
	}

	@Test
	public void boltsEnchantInTens()
	{
		Chain c = build(kit("DRAGON_BOLTS", 150), 1, new HashMap<>(), levels(99));
		assertEquals(150, step(c, ItemID.DRAGON_BOLTS_UNENCHANTED_RUBY).getNet());
		assertEquals(15, step(c, ItemID.COSMICRUNE).getNet());
		assertEquals(75, step(c, ItemID.FIRERUNE).getNet());
	}

	@Test
	public void progressHasAFixedEnd()
	{
		Provisions p = new Provisions();
		p.observeBank(new HashMap<>(), 1);
		Kit k = kit("FOOD", 100);
		p.observeLevels(levels(99));
		p.choose("FOOD", ItemID.SHARK);
		Chain c = p.plan(k, Collections.emptyMap(), Collections.emptyMap());
		assertEquals(50, step(c, ItemID.RAW_SHARK).getBaseline());
		Map<Integer, Long> carried = new HashMap<>();
		carried.put(ItemID.RAW_SHARK, 20L);
		c = p.plan(k, Collections.emptyMap(), carried);
		Step raw = step(c, ItemID.RAW_SHARK);
		assertEquals(30, raw.getNet());
		assertEquals(50, raw.getBaseline());
		assertEquals(0.4, raw.progress(), 1e-9);
		// Cooking them leaves the catching step done, not gone.
		carried.clear();
		carried.put(ItemID.SHARK, 50L);
		c = p.plan(k, Collections.emptyMap(), carried);
		assertNotNull(step(c, ItemID.RAW_SHARK));
		assertEquals(Step.State.DONE, step(c, ItemID.RAW_SHARK).getState());
		assertTrue(c.provisioned());
		assertNull(c.current());
	}

	@Test
	public void everyPresetBuilds()
	{
		for (Kit k : Presets.all())
		{
			Chain c = build(k, 10, new HashMap<>(), new HashMap<>());
			assertTrue(k.getName(), !c.getSteps().isEmpty());
			for (Step s : c.getSteps())
			{
				assertNotNull(s.getRecipe().getHow());
			}
		}
	}
}

package com.codex.provisioner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/** Making from what is already held, and pace that is not fooled by buying. */
public class HeldCostAndPaceTest
{
	private static final Map<Integer, Long> PRICES = new HashMap<>();

	static
	{
		PRICES.put(ItemID._3DOSEPRAYERRESTORE, 6_000L);
		PRICES.put(ItemID.UNIDENTIFIED_RANARR, 5_000L);
		PRICES.put(ItemID.RANARR_WEED, 5_400L);
		PRICES.put(ItemID.RANARRVIAL, 5_600L);
		PRICES.put(ItemID.VIAL_WATER, 4L);
		PRICES.put(ItemID.VIAL_EMPTY, 2L);
		PRICES.put(ItemID.SNAPE_GRASS, 300L);
	}

	private static long price(int id)
	{
		return PRICES.getOrDefault(id, 0L);
	}

	@Test
	public void heldIngredientsCostNoCoinsButCountAtTheirSaleValue()
	{
		Map<Integer, Long> pool = new HashMap<>();
		pool.put(ItemID.UNIDENTIFIED_RANARR, 10L);
		Costing.Quote q = Costing.quote(ItemID._3DOSEPRAYERRESTORE, 10, HeldCostAndPaceTest::price, pool);
		// Only the vials and snape grass are bought: 10 x (2 + 300).
		assertEquals(3_020, q.getMake());
		// The ten ranarr would sell for 5,000 less 2% tax each.
		assertEquals(49_000, q.getFromBank());
		assertEquals(52_020, q.getMakeTotal());
		assertEquals(60_000 - 52_020, q.saving());
		assertEquals(60_000 - 3_020, q.cashSaving());
		assertTrue(q.makeIsCheaper());
		// They are spoken for now.
		assertEquals(0L, (long) pool.get(ItemID.UNIDENTIFIED_RANARR));
	}

	@Test
	public void onePoolNeverCountsAHeldItemTwice()
	{
		Map<Integer, Long> pool = new HashMap<>();
		pool.put(ItemID.UNIDENTIFIED_RANARR, 6L);
		Costing.Quote first = Costing.quote(ItemID._3DOSEPRAYERRESTORE, 4, HeldCostAndPaceTest::price, pool);
		Costing.Quote second = Costing.quote(ItemID._3DOSEPRAYERRESTORE, 4, HeldCostAndPaceTest::price, pool);
		assertEquals(4 * 4_900, first.getFromBank());
		// Two ranarr were left for the second, and two had to be bought.
		assertEquals(2 * 4_900, second.getFromBank());
		assertEquals(4 * 302 + 2 * 5_000, second.getMake());
	}

	@Test
	public void aHeldStageAboveSkipsEverythingBelowIt()
	{
		Map<Integer, Long> pool = new HashMap<>();
		pool.put(ItemID.RANARRVIAL, 10L);
		pool.put(ItemID.UNIDENTIFIED_RANARR, 50L);
		Costing.Quote q = Costing.quote(ItemID._3DOSEPRAYERRESTORE, 10, HeldCostAndPaceTest::price, pool);
		assertEquals(10 * 300, q.getMake());
		assertEquals(10 * (5_600 - 112), q.getFromBank());
		// The grimy herbs were never needed.
		assertEquals(50L, (long) pool.get(ItemID.UNIDENTIFIED_RANARR));
	}

	@Test
	public void aHeldIngredientWithNoPriceStillLetsTheQuoteBeTold()
	{
		Map<Integer, Long> pool = new HashMap<>();
		pool.put(ItemID.SNAPE_GRASS, 10L);
		Prices noSnape = id -> id == ItemID.SNAPE_GRASS ? 0 : price(id);
		Costing.Quote q = Costing.quote(ItemID._3DOSEPRAYERRESTORE, 10, noSnape, pool);
		assertTrue(q.known());
		assertEquals(0, q.getFromBank());
		assertEquals(10 * 5_002, q.getMake());
	}

	@Test
	public void aQuoteThatCannotBeMadeTakesNothing()
	{
		Map<Integer, Long> pool = new HashMap<>();
		pool.put(ItemID.UNIDENTIFIED_RANARR, 10L);
		// Without snape grass at any price, nothing can be made, and the ranarr stay in the pool.
		Prices noSnape = id -> id == ItemID.SNAPE_GRASS ? 0 : price(id);
		Costing.Quote q = Costing.quote(ItemID._3DOSEPRAYERRESTORE, 10, noSnape, pool);
		assertFalse(q.known());
		assertEquals(10L, (long) pool.get(ItemID.UNIDENTIFIED_RANARR));
	}

	@Test
	public void saleValueTakesTheTaxUpToItsCap()
	{
		assertEquals(49, Costing.saleValue(49));
		assertEquals(4_900, Costing.saleValue(5_000));
		assertEquals(1_000_000_000L - 5_000_000L, Costing.saleValue(1_000_000_000L));
		assertEquals(0, Costing.saleValue(0));
	}

	/** A pace fed one item's count each 24 seconds, as cooking a shark at a time. */
	private static long work(Pace pace, int item, long net, long t, int count)
	{
		for (int i = 0; i < count; i++)
		{
			t += 24_000;
			net--;
			pace.observe("p", Collections.singletonMap(item, net), Collections.emptyMap(), Collections.emptySet(), false, t);
		}
		return t;
	}

	@Test
	public void aSmallExchangeBuyIsNotWork()
	{
		Pace pace = new Pace();
		pace.observe("p", Collections.singletonMap(1, 100L), Collections.emptyMap(), 0);
		long t = work(pace, 1, 100, 0, 25);
		assertEquals(150, pace.measured(1), 0.01);
		// Five bought on the exchange and collected later: a drop of five a few seconds on, no work.
		pace.bought(1, t + 1_000);
		assertFalse(pace.observe("p", Collections.singletonMap(1, 70L), Collections.emptyMap(), Collections.emptySet(), false, t + 4_000));
		assertEquals(150, pace.measured(1), 0.01);
		// The mark is spent on that one drop; the next real one counts.
		assertTrue(pace.observe("p", Collections.singletonMap(1, 69L), Collections.emptyMap(), Collections.emptySet(), false, t + 28_000));
	}

	@Test
	public void nothingIsLearnedWhileTrading()
	{
		Pace pace = new Pace();
		pace.observe("p", Collections.singletonMap(1, 100L), Collections.emptyMap(), 0);
		long t = work(pace, 1, 100, 0, 25);
		// Three bought from a shop, a few seconds after the last fish.
		assertFalse(pace.observe("p", Collections.singletonMap(1, 72L), Collections.emptyMap(), Collections.emptySet(), true, t + 6_000));
		assertEquals(150, pace.measured(1), 0.01);
	}

	@Test
	public void buyingStepsAreNeverTimed()
	{
		Pace pace = new Pace();
		pace.observe("p", Collections.singletonMap(1, 100L), Collections.emptyMap(), 0);
		long t = 0;
		for (int i = 0; i < 40; i++)
		{
			t += 10_000;
			assertFalse(pace.observe("p", Collections.singletonMap(1, 99L - i), Collections.emptyMap(), Collections.singleton(1), false, t));
		}
		assertEquals(0, pace.measured(1), 0);
	}

	@Test
	public void anUncollectedPurchaseIsForgottenInTime()
	{
		for (long markAge : new long[]{60_000, Pace.TRADE_MS + 60_000})
		{
			Pace pace = new Pace();
			long t = 10 * Pace.TRADE_MS;
			pace.observe("p", Collections.singletonMap(1, 100L), Collections.emptyMap(), t);
			pace.bought(1, t + 1_000 - markAge);
			// A rise (a deposit of more needed, say) moves the clock on without spending the mark.
			pace.observe("p", Collections.singletonMap(1, 101L), Collections.emptyMap(), Collections.emptySet(), false, t + 1_000);
			boolean learned = pace.observe("p", Collections.singletonMap(1, 100L), Collections.emptyMap(), Collections.emptySet(), false, t + 21_000);
			// A fresh mark passes the drop over; one left uncollected past its time does not.
			assertEquals(markAge > Pace.TRADE_MS, learned);
		}
	}
}

package com.codex.provisioner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class HerbRunsAndRunwayTest
{
	private static Map<Integer, Long> items(long... pairs)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int i = 0; i + 1 < pairs.length; i += 2)
		{
			m.put((int) pairs[i], pairs[i + 1]);
		}
		return m;
	}

	@Test
	public void herbsBecomeRunsAndSeeds()
	{
		// 100 ranarr at 8 a patch is 13 seeds, two runs on seven patches.
		HerbRuns.Plan p = HerbRuns.plan(ItemID.UNIDENTIFIED_RANARR, 100, 7, 8, items(ItemID.RANARR_SEED, 5));
		assertEquals(ItemID.RANARR_SEED, p.getSeed());
		assertEquals(13, p.getSeeds());
		assertEquals(2, p.getRuns());
		assertEquals(8, p.getSeedsShort());
		assertEquals(2 * HerbRuns.GROW_MS, p.getSoonestMs());
		assertEquals(7, p.getPatchesUsed());
		// 28 ranarr need only 4 seeds: one run plants 4 of the 7 patches, not all of them.
		HerbRuns.Plan few = HerbRuns.plan(ItemID.UNIDENTIFIED_RANARR, 28, 7, 8, items());
		assertEquals(1, few.getRuns());
		assertEquals(4, few.getPatchesUsed());
		// Exactly a patch's worth is one seed, not two.
		assertEquals(1, HerbRuns.plan(ItemID.UNIDENTIFIED_TORSTOL, 8, 7, 8, items()).getSeeds());
		assertEquals(0, HerbRuns.plan(ItemID.UNIDENTIFIED_TORSTOL, 8, 7, 8, items(ItemID.TORSTOL_SEED, 3)).getSeedsShort());
	}

	@Test
	public void onlyHerbPatchHerbsWithPatchesArePlanned()
	{
		assertNull(HerbRuns.plan(ItemID.SNAPE_GRASS, 50, 7, 8, items()));
		assertNull(HerbRuns.plan(ItemID.UNIDENTIFIED_RANARR, 50, 0, 8, items()));
		assertNull(HerbRuns.plan(ItemID.UNIDENTIFIED_RANARR, 0, 7, 8, items()));
		assertEquals(0, HerbRuns.seed(ItemID.RANARR_WEED));
	}

	@Test
	public void everyHerbTheCookbookGrowsHasASeed()
	{
		for (int grimy : new int[]{ItemID.UNIDENTIFIED_RANARR, ItemID.UNIDENTIFIED_TOADFLAX, ItemID.UNIDENTIFIED_IRIT,
			ItemID.UNIDENTIFIED_AVANTOE, ItemID.UNIDENTIFIED_KWUARM, ItemID.UNIDENTIFIED_SNAPDRAGON, ItemID.UNIDENTIFIED_CADANTINE,
			ItemID.UNIDENTIFIED_LANTADYME, ItemID.UNIDENTIFIED_DWARF_WEED, ItemID.UNIDENTIFIED_TORSTOL})
		{
			Recipe r = Cookbook.recipe(grimy);
			assertEquals(Verb.GATHER, r.getVerb());
			assertEquals(true, HerbRuns.seed(grimy) > 0);
		}
	}

	@Test
	public void readyTripsAreTheSupplyThatRunsOutFirst()
	{
		Kit kit = new Kit("k", "K", Arrays.asList(new Need("FOOD", 200), new Need("PRAYER", 12), new Need("item:" + ItemID.SPADE, 0)), false);
		// 60 sharks (20 hp each) is 6 trips of food; 4 four-dose prayer potions is 1 trip.
		Map<Integer, Long> held = items(ItemID.SHARK, 60, ItemID._4DOSEPRAYERRESTORE, 4, ItemID.SPADE, 1);
		Chain c = Chain.build(kit, Collections.emptyMap(), 10, Collections.emptyMap(), held, Collections.emptyMap(), Collections.emptyMap());
		assertEquals(1, c.readyTrips());
		assertEquals("PRAYER", c.limiting().getSupply().getKey());
		assertEquals(6, c.getLines().get(0).tripsHeld());
		assertEquals(-1, c.getLines().get(2).tripsHeld());

		// Measured use counts: 9 doses a trip makes 16 doses last one trip still, 18 two.
		held.put(ItemID._4DOSEPRAYERRESTORE, 5L);
		Map<String, Double> measured = new HashMap<>();
		measured.put("PRAYER", 9.0);
		assertEquals(2, Chain.build(kit, measured, 10, Collections.emptyMap(), held, Collections.emptyMap(), Collections.emptyMap()).readyTrips());

		// Nothing used up: no runway at all.
		Kit tools = new Kit("t", "T", Collections.singletonList(new Need("item:" + ItemID.SPADE, 0)), false);
		Chain none = Chain.build(tools, Collections.emptyMap(), 10, Collections.emptyMap(), held, Collections.emptyMap(), Collections.emptyMap());
		assertEquals(-1, none.readyTrips());
		assertNull(none.limiting());
	}

	@Test
	public void aTieGoesToTheFirstSupplyInTheKit()
	{
		Kit kit = new Kit("k", "K", Arrays.asList(new Need("FOOD", 200), new Need("PRAYER", 16)), false);
		Chain c = Chain.build(kit, Collections.emptyMap(), 10, Collections.emptyMap(),
			items(ItemID.SHARK, 10, ItemID._4DOSEPRAYERRESTORE, 4), Collections.emptyMap(), Collections.emptyMap());
		assertEquals(1, c.readyTrips());
		assertSame(c.getLines().get(0), c.limiting());
	}
}

package com.codex.provisioner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntPredicate;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class LoadsAndTrainingTest
{
	private static final Set<Integer> STACKS = new HashSet<>(Arrays.asList(ItemID.SNAKEBOSS_SCALE, ItemID.AMYLASE,
		ItemID.TBWT_RAW_KARAMBWANJI, ItemID.DRAGON_BOLTS_UNENCHANTED_RUBY, ItemID.DRAGON_BOLTS_ENCHANTED_RUBY,
		ItemID.COSMICRUNE, ItemID.FIRERUNE, ItemID.BLOODRUNE));
	private static final IntPredicate STACKABLE = STACKS::contains;

	private static Kit kit(String supply, int perTrip)
	{
		return new Kit("k", "K", Collections.singletonList(new Need(supply, perTrip)), false);
	}

	private static Map<Skill, Integer> levels(int all)
	{
		Map<Skill, Integer> m = new EnumMap<>(Skill.class);
		for (Skill s : Skill.values())
		{
			m.put(s, all);
		}
		return m;
	}

	private static Chain chain(String supply, int perTrip, Map<String, Integer> choices)
	{
		return Chain.build(kit(supply, perTrip), Collections.emptyMap(), 10, choices, new HashMap<>(), levels(99), Collections.emptyMap());
	}

	private static Step step(Chain c, int item)
	{
		for (Step s : c.getSteps())
		{
			if (s.getItem() == item)
			{
				return s;
			}
		}
		throw new AssertionError("no step for " + item);
	}

	@Test
	public void bankMarksShrinkAsTheInventoryFills()
	{
		Chain c = chain("PRAYER", 12, Collections.emptyMap());
		Loads mix = Loads.of(step(c, ItemID._3DOSEPRAYERRESTORE), STACKABLE);
		Map<Integer, Long> carried = new HashMap<>();
		carried.put(ItemID.RANARRVIAL, 14L);
		carried.put(ItemID.SNAPE_GRASS, 5L);
		carried.put(ItemID.PESTLE_AND_MORTAR, 1L);
		Map<Integer, Long> take = Loads.toTake(mix, Arrays.asList(ItemID.PESTLE_AND_MORTAR, ItemID.CHISEL), carried);
		// The unfinished potions are all out already, and the pestle is in the pack: no marks for them.
		assertFalse(take.containsKey(ItemID.RANARRVIAL));
		assertFalse(take.containsKey(ItemID.PESTLE_AND_MORTAR));
		assertEquals(9L, (long) take.get(ItemID.SNAPE_GRASS));
		assertEquals(1L, (long) take.get(ItemID.CHISEL));
		// With nothing to split into trips, only the tools are marked.
		assertEquals(Collections.singletonMap(ItemID.CHISEL, 1L), Loads.toTake(null, Arrays.asList(ItemID.CHISEL), null));
	}

	@Test
	public void twoInputMixesFitFourteenOfEach()
	{
		Chain c = chain("PRAYER", 12, Collections.emptyMap());
		Loads mix = Loads.of(step(c, ItemID._3DOSEPRAYERRESTORE), STACKABLE);
		assertEquals(14, mix.getPerLoad());
		assertEquals(14L, (long) mix.getWithdraw().get(ItemID.RANARRVIAL));
		assertEquals(14L, (long) mix.getWithdraw().get(ItemID.SNAPE_GRASS));
		// Forty potions are three trips.
		assertEquals(3, mix.getLoads());
		Loads clean = Loads.of(step(c, ItemID.RANARR_WEED), STACKABLE);
		assertEquals(28, clean.getPerLoad());
		assertEquals(2, clean.getLoads());
	}

	@Test
	public void aStackTakesOneSlotAndAToolAnother()
	{
		Chain venom = chain("ANTIVENOM", 40, Collections.emptyMap());
		Loads scales = Loads.of(step(venom, ItemID.ANTIVENOM4), STACKABLE);
		// The scales stack in one slot: 27 antidotes, with 20 scales each.
		assertEquals(27, scales.getPerLoad());
		assertEquals(27L * 20, (long) scales.getWithdraw().get(ItemID.SNAKEBOSS_SCALE));
		Chain food = chain("FOOD", 200, Collections.singletonMap("FOOD", ItemID.TBWT_COOKED_KARAMBWAN));
		Loads catching = Loads.of(step(food, ItemID.TBWT_RAW_KARAMBWAN), STACKABLE);
		// The vessel and the stack of karambwanji leave 26 slots for the catch.
		assertEquals(26, catching.getPerLoad());
	}

	@Test
	public void decantingIsSetByWhatGoesIn()
	{
		// 400 doses is 100 super combats, each needing a four-dose of each stat potion: 34 decants each.
		Chain c = chain("COMBAT", 40, Collections.emptyMap());
		Step decant = null;
		for (Step s : c.getSteps())
		{
			if (s.getRecipe().getVerb() == Verb.DECANT)
			{
				decant = s;
			}
		}
		assertNotNull(decant);
		Loads l = Loads.of(decant, STACKABLE);
		// Four three-dose potions make three four-dose: seven goes fit, twenty-one made.
		assertEquals(21, l.getPerLoad());
		assertEquals(28L, (long) l.getWithdraw().values().iterator().next());
		assertEquals(5, l.getLoads());
	}

	@Test
	public void allStacksIsOneTrip()
	{
		Chain c = chain("DRAGON_BOLTS", 100, Collections.singletonMap("DRAGON_BOLTS", ItemID.DRAGON_BOLTS_ENCHANTED_RUBY));
		Loads l = Loads.of(step(c, ItemID.DRAGON_BOLTS_ENCHANTED_RUBY), STACKABLE);
		assertEquals(1, l.getLoads());
		assertEquals(1000, l.getPerLoad());
	}

	@Test
	public void farmRunsBuyingAndDoneStepsHaveNoTrips()
	{
		Chain c = chain("PRAYER", 12, Collections.emptyMap());
		assertNull(Loads.of(step(c, ItemID.UNIDENTIFIED_RANARR), STACKABLE));
		Chain bought = Chain.build(kit("PRAYER", 12), Collections.emptyMap(), 10, Collections.emptyMap(),
			Collections.singleton("PRAYER"), new HashMap<>(), levels(99), Collections.emptyMap());
		assertNull(Loads.of(bought.getSteps().get(0), STACKABLE));
	}

	@Test
	public void trainingAddsUpTheOpenStepsAndTheLevelsTheyReach()
	{
		Chain c = chain("PRAYER", 12, Collections.emptyMap());
		Map<Skill, Long> xp = new EnumMap<>(Skill.class);
		xp.put(Skill.HERBLORE, (long) Experience.getXpForLevel(38));
		List<Training.Gain> gains = Training.of(c, xp, levels(38));
		assertEquals(1, gains.size());
		Training.Gain herb = gains.get(0);
		assertEquals(Skill.HERBLORE, herb.getSkill());
		// Forty ranarr cleaned (7.5 each) and forty potions mixed (87.5 each).
		assertEquals(40 * 7.5 + 40 * 87.5, herb.getXp(), 0.01);
		assertEquals(38, herb.levelBefore());
		assertEquals(Experience.getLevelForXp(Experience.getXpForLevel(38) + 3_800), herb.levelAfter());
		assertTrue(herb.levelAfter() > herb.levelBefore());
	}

	@Test
	public void trainingFallsBackOnTheLevelWithoutExperience()
	{
		Chain c = chain("PRAYER", 12, Collections.emptyMap());
		Training.Gain herb = Training.of(c, Collections.emptyMap(), levels(90)).get(0);
		assertEquals(Experience.getXpForLevel(90), herb.getBefore());
		assertEquals(90, herb.levelBefore());
		// Experience read as nothing before the game sent it does not undo a known level.
		Training.Gain early = Training.of(c, Collections.singletonMap(Skill.HERBLORE, 0L), levels(90)).get(0);
		assertEquals(90, early.levelBefore());
	}

	@Test
	public void experienceReadAsNothingIsNotTakenIn()
	{
		Provisions p = new Provisions();
		assertTrue(p.observeXp(Collections.singletonMap(Skill.HERBLORE, 1_000_000L)));
		assertFalse(p.observeXp(Collections.singletonMap(Skill.HERBLORE, 0L)));
		assertEquals(1_000_000L, (long) p.xp().get(Skill.HERBLORE));
	}

	@Test
	public void aMaxedSkillStaysAtNinetyNine()
	{
		// Past 13m experience the table goes on into virtual levels, which the game never shows.
		Chain c = chain("PRAYER", 12, Collections.emptyMap());
		Training.Gain herb = Training.of(c, Collections.singletonMap(Skill.HERBLORE, 20_000_000L), levels(99)).get(0);
		assertEquals(99, herb.levelBefore());
		assertEquals(99, herb.levelAfter());
		assertEquals(1, herb.progressAfter(), 0);
		// Crossing into 99 still reads as reaching it.
		long nearly = Experience.getXpForLevel(99) - 100;
		Training.Gain last = Training.of(c, Collections.singletonMap(Skill.HERBLORE, nearly), levels(98)).get(0);
		assertEquals(98, last.levelBefore());
		assertEquals(99, last.levelAfter());
	}
}

package com.codex.provisioner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntFunction;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/** The word at the bank when the kit runs low. */
public class RestockTest
{
	private static final IntFunction<String> NAMES = id -> id == ItemID._3DOSEPRAYERRESTORE ? "Prayer potion(3)" : "Item " + id;

	/** Ten doses of prayer a trip of Vorkath, with so many four-dose potions held. */
	private static Chain vorkath(long potions)
	{
		Kit kit = new Kit("v", "Vorkath", Arrays.asList(new Need("PRAYER", 10)), false);
		Map<Integer, Long> held = new HashMap<>();
		held.put(ItemID._4DOSEPRAYERRESTORE, potions);
		return Chain.build(kit, Collections.emptyMap(), 10, Collections.emptyMap(), held, Collections.emptyMap(), Collections.emptyMap());
	}

	@Test
	public void saysHowManyTripsAndWhatCoversTheRest()
	{
		// 24 doses: two trips, and 6 doses short of three, two of the three-dose potions mixing makes.
		assertEquals("Ready for 2 trips of Vorkath. First to run out: prayer and restores; 2 more prayer potion(3) cover 3 trips.",
			Restock.warning(vorkath(6), 3, NAMES));
		assertEquals("Not stocked for a single trip of Vorkath. First to run out: prayer and restores; 10 more prayer potion(3) cover 3 trips.",
			Restock.warning(vorkath(0), 3, NAMES));
		// Stocked for the mark, or the warning off: nothing.
		assertNull(Restock.warning(vorkath(8), 3, NAMES));
		assertNull(Restock.warning(vorkath(0), 0, NAMES));
		// A mark above the plan's own trips asks no more than the plan: ten trips here, so 12 reads as 10.
		assertEquals("Ready for 2 trips of Vorkath. First to run out: prayer and restores; 26 more prayer potion(3) cover 10 trips.",
			Restock.warning(vorkath(6), 12, NAMES));
	}

	@Test
	public void saysNothingOfAKitNeverPicked()
	{
		// The first kit is only shown until one is picked; a player who never set one up is not nagged.
		assertNull(new Restock().onBank(vorkath(0), null, 3, NAMES, 1_000));
		assertNull(new Restock().onBank(vorkath(0), "zulrah", 3, NAMES, 1_000));
		assertNotNull(new Restock().onBank(vorkath(0), "v", 3, NAMES, 1_000));
	}

	@Test
	public void isNotRepeatedAtEveryBankVisitWhileTheStockGrows()
	{
		Restock r = new Restock();
		long t = 1_000_000;
		assertNotNull(r.onBank(vorkath(3), "v", 3, NAMES, t));
		// More made since: the same shortfall, smaller, is not told again.
		assertNull(r.onBank(vorkath(5), "v", 3, NAMES, t + 60_000));
		// Fewer trips than last told: news.
		assertNotNull(r.onBank(vorkath(0), "v", 3, NAMES, t + 120_000));
		assertNull(r.onBank(vorkath(0), "v", 3, NAMES, t + 180_000));
		// Half an hour on, a reminder.
		assertNotNull(r.onBank(vorkath(0), "v", 3, NAMES, t + 180_000 + Restock.QUIET_MS));
		// Stocked, then short again: told at once.
		assertNull(r.onBank(vorkath(8), "v", 3, NAMES, t + 200_000 + Restock.QUIET_MS));
		assertNotNull(r.onBank(vorkath(1), "v", 3, NAMES, t + 210_000 + Restock.QUIET_MS));
	}

	/** Food first, then prayer: 200 hitpoints and ten doses a trip, with so many sharks and four-dose potions held. */
	private static Chain twoSupplies(long sharks, long potions)
	{
		Kit kit = new Kit("v", "Vorkath", Arrays.asList(new Need("FOOD", 200), new Need("PRAYER", 10)), false);
		Map<Integer, Long> held = new HashMap<>();
		held.put(ItemID.SHARK, sharks);
		held.put(ItemID._4DOSEPRAYERRESTORE, potions);
		return Chain.build(kit, Collections.emptyMap(), 10, Collections.emptyMap(), held, Collections.emptyMap(), Collections.emptyMap());
	}

	@Test
	public void isNotRepeatedWhenAnotherSupplyRunsOutFirstAtTheSameTrips()
	{
		Restock r = new Restock();
		long t = 1_000_000;
		// Two trips of food, one of prayer: one trip, prayer first to run out.
		assertEquals(1, twoSupplies(20, 3).readyTrips());
		assertNotNull(r.onBank(twoSupplies(20, 3), "v", 3, NAMES, t));
		// A trip of food eaten: still one trip held, food now first to run out. Nothing new to tell.
		assertEquals(1, twoSupplies(10, 3).readyTrips());
		assertNull(r.onBank(twoSupplies(10, 3), "v", 3, NAMES, t + 60_000));
	}
}

package com.codex.provisioner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * What the Provisioner reads from other Codex plugins, against fixtures their real writers
 * produced: Quartermaster's published kits (kitsV1) with its own entry as fallback, and Bank
 * Steward's shared bank (bankV1).
 */
public class SharedSavesTest
{
	private static final Gson GSON = new Gson();

	private static String fixture(String name) throws IOException
	{
		try (InputStream in = SharedSavesTest.class.getResourceAsStream(name))
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			byte[] buf = new byte[4096];
			for (int n; (n = in.read(buf)) > 0; )
			{
				out.write(buf, 0, n);
			}
			return new String(out.toByteArray(), StandardCharsets.UTF_8);
		}
	}

	private static Kit kit(Quarters q, String id)
	{
		for (Kit k : q.allKits())
		{
			if (k.getId().equals(id))
			{
				return k;
			}
		}
		return null;
	}

	@Test
	public void publishedKitsAreReadWithTheirMeasuredUse() throws IOException
	{
		Quarters q = Quarters.read(GSON, fixture("quartermaster-measured-kitsV1.json"), fixture("quartermaster-measured-quarters.json"));
		assertTrue(q.hasSavedKits());
		assertEquals("kit:1", q.getActive());
		Kit mine = kit(q, "kit:1");
		assertEquals("My Vorkath", mine.getName());
		assertEquals(200, mine.need("FOOD").getPerTrip());
		assertEquals(150.0, q.measured("kit:1").get("FOOD"), 1e-9);
		assertEquals(9.0, q.measured("kit:1").get("PRAYER"), 1e-9);
		// The count of trips and the potion storage come from Quartermaster's own entry.
		assertEquals(3, q.measuredTrips("kit:1"));
		assertEquals(Long.valueOf(24), q.getStored().get(ItemID._1DOSEPRAYERRESTORE));
		// Presets are the Provisioner's own, listed once after the player's kits.
		assertEquals(1 + Presets.all().size(), q.allKits().size());
	}

	@Test
	public void publishedKitsAloneStillPlanFromMeasuredUse() throws IOException
	{
		Quarters q = Quarters.read(GSON, fixture("quartermaster-measured-kitsV1.json"), null);
		assertEquals("kit:1", q.getActive());
		assertEquals(150.0, q.measured("kit:1").get("FOOD"), 1e-9);
		// Published only once trusted, so at least the trusted count.
		assertEquals(Quarters.TRUSTED, q.measuredTrips("kit:1"));
		assertNull(q.getStored());
	}

	@Test
	public void quartermasterTooOldToPublishIsReadFromItsOwnEntry() throws IOException
	{
		Quarters q = Quarters.read(GSON, null, fixture("quartermaster-measured-quarters.json"));
		assertEquals("kit:1", q.getActive());
		assertEquals(150.0, q.measured("kit:1").get("FOOD"), 1e-9);
		assertEquals(3, q.measuredTrips("kit:1"));
		Quarters saved = Quarters.read(GSON, null, fixture("quartermaster-saved-quarters.json"));
		assertEquals("kit:1", saved.getActive());
		assertTrue(saved.measured("kit:1").isEmpty());
	}

	@Test
	public void aPresetIsChosenOnlyWhenQuartermasterSaysThePlayerPickedIt() throws IOException
	{
		// An older Quartermaster published the preset it showed on a fresh install as active.
		Quarters fresh = Quarters.read(GSON, fixture("quartermaster-fresh-kitsV1.json"), fixture("quartermaster-fresh-quarters.json"));
		assertNull(fresh.getActive());
		assertFalse(fresh.hasSavedKits());
		Quarters unchosen = Quarters.read(GSON, fixture("quartermaster-unchosen-kitsV1.json"), fixture("quartermaster-fresh-quarters.json"));
		assertNull(unchosen.getActive());
		Quarters saved = Quarters.read(GSON, fixture("quartermaster-saved-kitsV1.json"), fixture("quartermaster-saved-quarters.json"));
		assertEquals("kit:1", saved.getActive());
		// A carried item with no use per trip is kept, and plans nothing.
		assertEquals(0, kit(saved, "kit:1").need("item:952").getPerTrip());
	}

	@Test
	public void nothingOrRubbishFromQuartermasterLeavesThePresets()
	{
		assertEquals(Presets.all().size(), Quarters.read(GSON, null, null).allKits().size());
		assertEquals(Presets.all().size(), Quarters.read(GSON, "not json {", "[1,2]").allKits().size());
		Quarters odd = Quarters.read(GSON, "{\"kits\":[{\"id\":\"k\",\"name\":\"K\",\"needs\":[{\"supply\":\"FOOD\",\"perTrip\":\"lots\"},5]},7]}", null);
		assertEquals(0, kit(odd, "k").getNeeds().size());
	}

	@Test
	public void sharedBankIsReadFromBankStewardsSnapshot() throws IOException
	{
		SharedBank bank = SharedBank.read(GSON, fixture("bank-steward-bankV1.json"));
		assertEquals(1760000000000L, bank.getSavedAt());
		assertEquals(Long.valueOf(240), bank.getItems().get(ItemID.SHARK));
		assertEquals(Long.valueOf(1234567), bank.getItems().get(ItemID.COINS));
		assertNull(SharedBank.read(GSON, "{\"items\":{}}"));
		assertNull(SharedBank.read(GSON, "nonsense"));
		assertNull(SharedBank.read(GSON, null));
	}

	@Test
	public void sharedBankIsTakenOnlyWhenNewer() throws IOException
	{
		SharedBank shared = SharedBank.read(GSON, fixture("bank-steward-bankV1.json"));
		Provisions p = new Provisions();
		assertTrue("never seen here: taken", p.adoptShared(shared));
		assertTrue(p.isBankShared());
		assertEquals(shared.getSavedAt(), p.getBankSeen());
		assertEquals(Long.valueOf(240), p.getBank().get(ItemID.SHARK));

		Map<Integer, Long> own = new HashMap<>();
		own.put(ItemID.SHARK, 5L);
		p.observeBank(own, shared.getSavedAt() + 10_000);
		assertFalse(p.isBankShared());
		assertFalse("seen here later: kept", p.adoptShared(shared));
		p.observeBank(own, shared.getSavedAt() - 30_000);
		assertFalse("seen at much the same time: kept", p.adoptShared(shared));
		p.observeBank(own, shared.getSavedAt() - 3_600_000);
		assertTrue("seen here an hour before: taken", p.adoptShared(shared));
		assertFalse(p.adoptShared(null));
	}

	@Test
	public void sharedBankSurvivesASaveAndLoad() throws IOException
	{
		Provisions p = new Provisions();
		p.adoptShared(SharedBank.read(GSON, fixture("bank-steward-bankV1.json")));
		Provisions back = GSON.fromJson(GSON.toJson(p), Provisions.class).repair();
		assertTrue(back.isBankShared());
		assertTrue(back.hasBank());
		List<Kit> kits = Quarters.none().allKits();
		assertFalse(kits.isEmpty());
	}
}

package com.codex.provisioner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/** One sitting's worth of the chain, and the account read only once it has settled after a login. */
public class SittingTest
{
	private static Map<Skill, Integer> levels(int all)
	{
		Map<Skill, Integer> m = new EnumMap<>(Skill.class);
		for (Skill s : Skill.values())
		{
			m.put(s, all);
		}
		return m;
	}

	/** Prayer restores for 10 trips of 10 doses, with the grimy herbs and the snape grass in the bank. */
	private static Chain prayer(Map<Skill, Integer> levels, boolean herbs)
	{
		Kit kit = new Kit("t", "Test", Arrays.asList(new Need("PRAYER", 10)), false);
		Map<Integer, Long> held = new HashMap<>();
		if (herbs)
		{
			held.put(ItemID.UNIDENTIFIED_RANARR, 34L);
		}
		held.put(ItemID.SNAPE_GRASS, 34L);
		return Chain.build(kit, Collections.emptyMap(), 10, Collections.emptyMap(), held, levels, Collections.emptyMap());
	}

	/** A second an item to clean or fill, two to mix. */
	private static Map<Integer, Long> estimates(Chain chain)
	{
		Map<Integer, Long> out = new HashMap<>();
		for (Step s : chain.getSteps())
		{
			Verb v = s.getRecipe().getVerb();
			long each = v == Verb.CLEAN || v == Verb.FILL ? 1_000 : v == Verb.MIX ? 2_000 : -1;
			out.put(s.getItem(), each < 0 ? -1 : s.getNet() * each);
		}
		return out;
	}

	private static long amount(Sitting plan, int item)
	{
		for (Sitting.Piece p : plan.getPieces())
		{
			if (p.getStep().getItem() == item)
			{
				return p.getAmount();
			}
		}
		return 0;
	}

	@Test
	public void aShortSittingGoesAsFarAsTheTimeAndTheInputsAllow()
	{
		Chain chain = prayer(levels(99), true);
		Sitting plan = Sitting.plan(chain, estimates(chain), Collections.emptySet(), 100_000);
		// Clean every herb (34s), buy the vials, fill them (34s), then 16 unfinished potions in the 32s left.
		assertEquals(34, amount(plan, ItemID.RANARR_WEED));
		assertEquals(34, amount(plan, ItemID.VIAL_EMPTY));
		assertEquals(34, amount(plan, ItemID.VIAL_WATER));
		assertEquals(16, amount(plan, ItemID.RANARRVIAL));
		assertEquals(0, amount(plan, ItemID._3DOSEPRAYERRESTORE));
		assertEquals(100_000, plan.getUsed());
		assertFalse(plan.isEverything());
		// The step in hand comes first.
		assertEquals(chain.current(), plan.getPieces().get(0).getStep());
		assertFalse(plan.getPieces().get(3).finishes());
	}

	@Test
	public void aLongSittingFinishesTheChain()
	{
		Chain chain = prayer(levels(99), true);
		Sitting plan = Sitting.plan(chain, estimates(chain), Collections.emptySet(), 3_600_000);
		assertTrue(plan.isEverything());
		assertTrue(plan.getLeft().isEmpty());
		assertEquals(34, amount(plan, ItemID._3DOSEPRAYERRESTORE));
		// 34 cleaned, 34 filled, 34 + 34 mixed at two seconds each.
		assertEquals(204_000, plan.getUsed());
	}

	@Test
	public void aStepCannotOutrunItsInputs()
	{
		Chain chain = prayer(levels(99), true);
		Map<Integer, Long> est = estimates(chain);
		// The vials cannot be filled in time: the potions can only use what the sitting makes of them.
		est.put(ItemID.VIAL_WATER, 34 * 60_000L);
		// Clean 34 (34s), buy, fill 5 (5m), then 5 unfinished and 5 finished potions (10s each).
		Sitting plan = Sitting.plan(chain, est, Collections.emptySet(), 34_000 + 5 * 60_000 + 20_000);
		assertEquals(5, amount(plan, ItemID.VIAL_WATER));
		assertEquals(5, amount(plan, ItemID.RANARRVIAL));
		assertEquals(5, amount(plan, ItemID._3DOSEPRAYERRESTORE));
	}

	@Test
	public void grownAndLockedStepsArePassedOverAndLeft()
	{
		Chain grown = prayer(levels(99), false);
		Sitting plan = Sitting.plan(grown, estimates(grown), Collections.singleton(ItemID.UNIDENTIFIED_RANARR), 3_600_000);
		// No herbs grown yet: only the vials can be got ready.
		assertEquals(0, amount(plan, ItemID.RANARR_WEED));
		assertEquals(34, amount(plan, ItemID.VIAL_WATER));
		assertTrue(plan.getLeft().stream().anyMatch(s -> s.getItem() == ItemID.UNIDENTIFIED_RANARR));

		Chain locked = prayer(levels(1), true);
		Sitting low = Sitting.plan(locked, estimates(locked), Collections.emptySet(), 3_600_000);
		List<Step> left = low.getLeft();
		assertTrue(left.stream().anyMatch(s -> s.getState() == Step.State.LOCKED));
		assertEquals(0, amount(low, ItemID._3DOSEPRAYERRESTORE));
	}

	@Test
	public void theAccountIsReadOnlyOnceTheLoginHasSettled()
	{
		Settle settle = new Settle();
		settle.restart();
		assertFalse(settle.isSettled());
		assertFalse(settle.tick());
		assertTrue(settle.tick());
		assertTrue(settle.isSettled());
		// Read once, not on every tick after.
		assertFalse(settle.tick());
		settle.restart();
		assertFalse(settle.isSettled());
	}

	@Test
	public void aSkillNotSentYetIsNoReading()
	{
		Provisions p = new Provisions();
		p.observeLevels(Collections.singletonMap(Skill.HERBLORE, 80));
		// During a hop the game can report a skill as 0; that must not lock every Herblore step.
		assertFalse(p.observeLevels(Collections.singletonMap(Skill.HERBLORE, 0)));
		assertEquals(Integer.valueOf(80), p.levels().get(Skill.HERBLORE));
	}
}

package com.codex.provisioner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class TradeAndPaceTest
{
	private static final Map<Integer, Long> PRICES = new HashMap<>();

	static
	{
		PRICES.put(ItemID._3DOSEPRAYERRESTORE, 6_000L);
		PRICES.put(ItemID.UNIDENTIFIED_RANARR, 5_000L);
		PRICES.put(ItemID.RANARR_WEED, 5_400L);
		PRICES.put(ItemID.RANARRVIAL, 5_600L);
		PRICES.put(ItemID.VIAL_WATER, 4L);
		PRICES.put(ItemID.VIAL_EMPTY, 2L);
		PRICES.put(ItemID.SNAPE_GRASS, 300L);
		PRICES.put(ItemID.SHARK, 900L);
		PRICES.put(ItemID.RAW_SHARK, 1_000L);
	}

	private static long price(int id)
	{
		return PRICES.getOrDefault(id, 0L);
	}

	private static Kit kit(String supply, int perTrip)
	{
		return new Kit("k", "K", Collections.singletonList(new Need(supply, perTrip)), false);
	}

	@Test
	public void makingPrayerPotionsFromGrimyRanarr()
	{
		Costing.Quote q = Costing.quote(ItemID._3DOSEPRAYERRESTORE, 10, TradeAndPaceTest::price);
		assertEquals(60_000, q.getBuy());
		// Grimy ranarr (5,000) is cheaper than clean (5,400), so it is bought grimy and cleaned; the
		// vial is filled from an empty one; plus snape grass: 10 x (5,000 + 2 + 300).
		assertEquals(53_020, q.getMake());
		assertTrue(q.makeIsCheaper());
		assertEquals(6_980, q.saving());
		assertEquals(875 + 75, q.getXp().get(Skill.HERBLORE), 0.01);
		assertEquals(0, q.coinsPerXp(), 0);
	}

	@Test
	public void makingThatCostsMoreIsPricedPerXp()
	{
		// Raw sharks dearer than cooked: cooking costs 100 a fish for 210 xp.
		Costing.Quote q = Costing.quote(ItemID.SHARK, 100, TradeAndPaceTest::price);
		assertFalse(q.makeIsCheaper());
		assertEquals(-10_000, q.saving());
		assertEquals(10_000 / 21_000.0, q.coinsPerXp(), 1e-9);
	}

	@Test
	public void unpricedIngredientMakesTheQuoteUnknown()
	{
		Costing.Quote q = Costing.quote(ItemID._3DOSE2RESTORE, 5, TradeAndPaceTest::price);
		assertEquals(-1, q.getBuy());
		assertEquals(-1, q.getMake());
		assertFalse(q.known());
	}

	@Test
	public void boughtSupplyIsOneStep()
	{
		Chain c = Chain.build(kit("PRAYER", 12), Collections.emptyMap(), 10, Collections.emptyMap(),
			Collections.singleton("PRAYER"), new HashMap<>(), Collections.emptyMap(), Collections.emptyMap());
		assertEquals(1, c.getSteps().size());
		Step s = c.getSteps().get(0);
		assertEquals(ItemID._3DOSEPRAYERRESTORE, s.getItem());
		assertEquals(Verb.BUY, s.getRecipe().getVerb());
		assertEquals(40, s.getNet());
		assertEquals(Step.State.READY, s.getState());
	}

	@Test
	public void ironAccountsBuyNothing()
	{
		Provisions p = new Provisions();
		p.setBought("PRAYER", true);
		assertEquals(Collections.singleton("PRAYER"), p.getBought());
		p.setIron(true);
		assertTrue(p.getBought().isEmpty());
	}

	@Test
	public void potionStorageCountsTowardTheSupply()
	{
		Provisions p = new Provisions();
		p.observeBank(new HashMap<>(), 1);
		Map<Integer, Long> fromQuartermaster = Collections.singletonMap(ItemID._1DOSEPRAYERRESTORE, 60L);
		// 120 doses wanted; Quartermaster's reading of 60 stored doses halves the work.
		Chain c = p.plan(kit("PRAYER", 12), Collections.emptyMap(), new HashMap<>(), fromQuartermaster);
		assertEquals(60, c.getLines().get(0).getShort());
		// Once read here, the Provisioner's own reading wins.
		assertTrue(p.observeStorage(Collections.singletonMap(ItemID._1DOSEPRAYERRESTORE, 120L)));
		assertFalse(p.observeStorage(Collections.singletonMap(ItemID._1DOSEPRAYERRESTORE, 120L)));
		c = p.plan(kit("PRAYER", 12), Collections.emptyMap(), new HashMap<>(), fromQuartermaster);
		assertTrue(c.provisioned());
	}

	@Test
	public void paceLearnsFromSteadyWorkOnly()
	{
		Pace pace = new Pace();
		Map<Integer, Integer> makes = Collections.emptyMap();
		long t = 0;
		long net = 100;
		pace.observe("p", Collections.singletonMap(1, net), makes, t);
		// A shark every 24 seconds for 25 sharks: 150 an hour.
		for (int i = 0; i < 25; i++)
		{
			t += 24_000;
			net--;
			pace.observe("p", Collections.singletonMap(1, net), makes, t);
		}
		assertEquals(150, pace.measured(1), 0.01);
		// A long break and a stack bought at once teach nothing.
		t += 10 * 60_000;
		pace.observe("p", Collections.singletonMap(1, net - 1), makes, t);
		t += 1_000;
		pace.observe("p", Collections.singletonMap(1, net - 500), makes, t);
		assertEquals(150, pace.measured(1), 0.01);
		// A change of plan starts the counts afresh rather than reading the drop as work.
		assertFalse(pace.observe("q", Collections.singletonMap(1, 3L), makes, t + 1_000));
	}

	@Test
	public void paceTrustsOnlyEnough()
	{
		Pace pace = new Pace();
		pace.observe("p", Collections.singletonMap(1, 10L), Collections.emptyMap(), 0);
		pace.observe("p", Collections.singletonMap(1, 5L), Collections.emptyMap(), 30_000);
		assertEquals(0, pace.measured(1), 0);
	}

	@Test
	public void estimateFallsBackToTypicalRate()
	{
		Chain c = Chain.build(kit("FOOD", 200), Collections.emptyMap(), 10, Collections.singletonMap("FOOD", ItemID.SHARK),
			new HashMap<>(), Collections.emptyMap(), Collections.emptyMap());
		Step cook = null;
		for (Step s : c.getSteps())
		{
			if (s.getItem() == ItemID.SHARK)
			{
				cook = s;
			}
		}
		// 2,000 hp is 100 sharks; at 1,300 an hour that is about 4.6 minutes.
		assertEquals(100, cook.getNet());
		assertEquals(Math.round(100 * 3_600_000.0 / 1300), new Pace().estimate(cook));
		Chain herbs = Chain.build(kit("PRAYER", 12), Collections.emptyMap(), 10, Collections.emptyMap(),
			new HashMap<>(), Collections.emptyMap(), Collections.emptyMap());
		for (Step s : herbs.getSteps())
		{
			if (s.getItem() == ItemID.UNIDENTIFIED_RANARR)
			{
				assertEquals("farm runs have no rate", -1, new Pace().estimate(s));
			}
		}
	}
}

package com.codex.provisioner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class TreeTest
{
	private static Map<Skill, Integer> levels(int all)
	{
		Map<Skill, Integer> m = new EnumMap<>(Skill.class);
		for (Skill s : Skill.values())
		{
			m.put(s, all);
		}
		return m;
	}

	private static Chain chain(Map<Integer, Long> held, Object... pairs)
	{
		Need[] needs = new Need[pairs.length / 2];
		for (int i = 0; i < needs.length; i++)
		{
			needs[i] = new Need((String) pairs[i * 2], (Integer) pairs[i * 2 + 1]);
		}
		Kit kit = new Kit("test", "Test", Arrays.asList(needs), false);
		Map<String, Integer> choices = new HashMap<>();
		choices.put("PRAYER", ItemID._3DOSEPRAYERRESTORE);
		return Chain.build(kit, Collections.emptyMap(), 1, choices, held, levels(99), Collections.emptyMap());
	}

	private static int index(List<Tree.Node> nodes, int item)
	{
		for (int i = 0; i < nodes.size(); i++)
		{
			if (nodes.get(i).getItem() == item)
			{
				return i;
			}
		}
		return -1;
	}

	@Test
	public void growsFromTheProductDownToWhatIsGathered()
	{
		Chain c = chain(new HashMap<>(), "PRAYER", 12);
		List<Tree.Node> prayer = Tree.of(c).values().iterator().next();
		Tree.Node root = prayer.get(0);
		assertEquals(ItemID._3DOSEPRAYERRESTORE, root.getItem());
		assertEquals(0, root.getDepth());
		int unf = index(prayer, ItemID.RANARRVIAL);
		int grimy = index(prayer, ItemID.UNIDENTIFIED_RANARR);
		int snape = index(prayer, ItemID.SNAPE_GRASS);
		assertEquals(1, prayer.get(unf).getDepth());
		// Grimy ranarr is cleaned into the herb that goes into the unfinished potion: two below it.
		assertEquals(3, prayer.get(grimy).getDepth());
		assertTrue(grimy > unf);
		// Snape grass is the potion's last input, so its branch ends there, and the unfinished
		// potion's branch runs on past everything beneath it until then.
		assertEquals(1, prayer.get(snape).getDepth());
		assertTrue(prayer.get(snape).isLast());
		assertFalse(prayer.get(unf).isLast());
		assertTrue(prayer.get(grimy).rail(0));
		assertFalse(prayer.get(snape).rail(0));
	}

	@Test
	public void aStockedPartIsALeafAndASharedPartOpensOnce()
	{
		// Clean ranarr in hand: nothing beneath it is needed.
		Map<Integer, Long> held = new HashMap<>();
		held.put(ItemID.RANARR_WEED, 50L);
		Chain c = chain(held, "PRAYER", 12, "RANGING", 4);
		Map<Chain.Line, List<Tree.Node>> trees = Tree.of(c);
		List<List<Tree.Node>> all = new java.util.ArrayList<>(trees.values());
		List<Tree.Node> prayer = all.get(0);
		int herb = index(prayer, ItemID.RANARR_WEED);
		assertTrue(prayer.get(herb).isDone());
		assertEquals(-1, index(prayer, ItemID.UNIDENTIFIED_RANARR));

		// Vials of water go into both potions: opened under the first, only named under the second.
		List<Tree.Node> ranging = all.get(1);
		int vialFirst = index(prayer, ItemID.VIAL_WATER);
		int vialAgain = index(ranging, ItemID.VIAL_WATER);
		assertFalse(prayer.get(vialFirst).isRepeat());
		assertTrue(ranging.get(vialAgain).isRepeat());
		assertTrue(vialAgain == ranging.size() - 1 || ranging.get(vialAgain + 1).getDepth() <= ranging.get(vialAgain).getDepth());
	}

	@Test
	public void aSupplyAlreadyStockedIsOneLine()
	{
		Map<Integer, Long> held = new HashMap<>();
		held.put(ItemID._4DOSEPRAYERRESTORE, 10L);
		Chain c = chain(held, "PRAYER", 12);
		List<Tree.Node> prayer = Tree.of(c).values().iterator().next();
		assertEquals(1, prayer.size());
		assertTrue(prayer.get(0).isDone());
		assertNull(prayer.get(0).getStep());
	}
}

package com.codex.provisioner.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.awt.image.BufferedImage;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.client.util.AsyncBufferedImage;
import org.junit.Test;

public class ArrivalsTest
{
	/** A picture still loading; it has no client thread, so a late ask on it would fail the test. */
	private static AsyncBufferedImage loading()
	{
		return new AsyncBufferedImage(null, 1, 1, BufferedImage.TYPE_INT_ARGB);
	}

	@Test
	public void waitsOnAPictureOnlyUntilItArrives()
	{
		Arrivals arrivals = new Arrivals();
		AtomicInteger refreshes = new AtomicInteger();
		AsyncBufferedImage whip = loading();
		arrivals.ask(whip, refreshes::incrementAndGet);
		arrivals.ask(whip, refreshes::incrementAndGet);
		assertFalse(arrivals.arrived(whip));
		whip.loaded();
		// Both asks made while it loaded are answered, and after that nothing more waits on it.
		assertEquals(2, refreshes.get());
		assertTrue(arrivals.arrived(whip));
		arrivals.ask(whip, refreshes::incrementAndGet);
		assertEquals(2, refreshes.get());
	}

	@Test
	public void waitsAgainOnAFreshPictureOfTheSameItem()
	{
		Arrivals arrivals = new Arrivals();
		AtomicInteger refreshes = new AtomicInteger();
		AsyncBufferedImage first = loading();
		arrivals.ask(first, refreshes::incrementAndGet);
		first.loaded();
		// RuneLite dropped the picture from its cache and made a new, blank one for the same item.
		AsyncBufferedImage again = loading();
		arrivals.ask(again, refreshes::incrementAndGet);
		again.loaded();
		assertEquals(2, refreshes.get());
	}

	@Test
	public void toleratesNoCallbackAndNoPicture()
	{
		Arrivals arrivals = new Arrivals();
		AsyncBufferedImage image = loading();
		arrivals.ask(image, null);
		arrivals.ask(null, null);
		image.loaded();
		assertTrue(arrivals.arrived(image));
	}
}

package com.codex.provisioner.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.codex.provisioner.core.Chain;
import com.codex.provisioner.core.Costing;
import com.codex.provisioner.core.HerbRuns;
import com.codex.provisioner.core.Kit;
import com.codex.provisioner.core.Loads;
import com.codex.provisioner.core.Provisions;
import com.codex.provisioner.core.Quarters;
import com.codex.provisioner.core.Restock;
import com.codex.provisioner.core.SharedBank;
import com.codex.provisioner.core.Step;
import com.codex.provisioner.core.Training;
import com.codex.provisioner.core.Verb;
import com.google.gson.Gson;
import java.awt.Component;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Every saved key the Provisioner reads, damaged every way a save can be: its own provisions,
 * Quartermaster's kitsV1 and quarters, and Bank Steward's bankV1. Empty, cut short, the wrong
 * shape, figures below zero or too big, a later version's, or not JSON at all: none may throw,
 * leave the panel unable to draw, or cost the player what still reads.
 */
public class DamagedSavesTest
{
	private static final Gson GSON = new Gson();
	private static final long NOW = 1_800_000_000_000L;

	private static String fixture(String name) throws IOException
	{
		try (InputStream in = Quarters.class.getResourceAsStream(name))
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			byte[] buf = new byte[4096];
			for (int n; (n = in.read(buf)) > 0; )
			{
				out.write(buf, 0, n);
			}
			return new String(out.toByteArray(), StandardCharsets.UTF_8);
		}
	}

	/** A save of the Provisioner's own, as the plugin writes it after some play. */
	private static String ownSave()
	{
		Provisions p = new Provisions();
		Map<Integer, Long> bank = new HashMap<>();
		bank.put(ItemID.RAW_SHARK, 46L);
		bank.put(ItemID.UNIDENTIFIED_RANARR, 18L);
		bank.put(ItemID.VIAL_WATER, 60L);
		bank.put(ItemID.SNAPE_GRASS, 40L);
		p.observeBank(bank, NOW - 60_000);
		Map<Skill, Integer> levels = new HashMap<>();
		Map<Skill, Long> xp = new HashMap<>();
		for (Skill s : Skill.values())
		{
			levels.put(s, 80);
			xp.put(s, 2_000_000L);
		}
		p.observeLevels(levels);
		p.observeXp(xp);
		p.choose("FOOD", ItemID.SHARK);
		p.setTrips(12);
		p.setKit("kit:1");
		p.observeStorage(Collections.singletonMap(ItemID._1DOSEPRAYERRESTORE, 12L));
		p.plan(Quarters.none().allKits().get(0), Collections.emptyMap(), new HashMap<>());
		return GSON.toJson(p);
	}

	/** The same save damaged every way we can think of. */
	static List<String> damaged(String save)
	{
		List<String> out = new ArrayList<>();
		out.add(null);
		out.add("");
		out.add("   ");
		out.add("null");
		out.add("{");
		out.add("}");
		out.add("[]");
		out.add("[1,2,3]");
		out.add("5");
		out.add("-1e400");
		out.add("\"a save\"");
		out.add("true");
		out.add("{\u0000\uFFFF}{][");
		out.add("\uFEFF" + save);
		out.add(save.replaceFirst("^\\{", "{\"version\":99,\"shelf\":{\"a\":[1,{\"b\":2}]},"));
		// Every number in the save in turn too big, below zero, a fraction or a word.
		for (String n : new String[]{"99999999999999999999", "-5", "-9223372036854775808", "2147483648", "1e308", "0.5", "\"many\"", "null", "{}", "[]"})
		{
			out.add(save.replaceAll("(?<=[:\\[,])-?\\d+(\\.\\d+)?(?=[,\\]}])", n));
			out.add(save.replaceFirst("(?<=[:\\[,])-?\\d+(\\.\\d+)?(?=[,\\]}])", n));
		}
		// Every string in the save in turn a number, empty or nonsense.
		out.add(save.replaceAll("(?<=:)\"[^\"]*\"", "7"));
		out.add(save.replaceAll("(?<=:)\"[^\"]*\"", "\"\""));
		out.add(save.replaceAll("(?<=:)\"[^\"]*\"", "\"NOT_A_THING\""));
		// Every list and object the wrong shape.
		out.add(save.replaceAll("\\[", "{").replaceAll("]", "}"));
		out.add(save.replaceAll("(?<=:)\\{", "[").replaceAll("}(?=[,}])", "]"));
		for (int cut = 1; cut < 24; cut++)
		{
			out.add(save.substring(0, save.length() * cut / 24));
		}
		return out;
	}

	@Test
	public void theProvisionersOwnSaveSurvivesAnyDamage() throws IOException
	{
		String own = ownSave();
		for (String bad : damaged(own))
		{
			Provisions p = Provisions.read(GSON, bad, NOW).provisions;
			draw(p, Quarters.read(GSON, fixture("quartermaster-measured-kitsV1.json"), fixture("quartermaster-measured-quarters.json")),
				SharedBank.read(GSON, fixture("bank-steward-bankV1.json")), bad);
			// What was read saves and reads back whole.
			assertFalse(String.valueOf(bad), Provisions.read(GSON, GSON.toJson(p), NOW).damaged);
		}
	}

	@Test
	public void quartermastersKitsSurviveAnyDamage() throws IOException
	{
		String kits = fixture("quartermaster-measured-kitsV1.json");
		String quarters = fixture("quartermaster-measured-quarters.json");
		Provisions p = Provisions.read(GSON, ownSave(), NOW).provisions;
		for (String bad : damaged(kits))
		{
			draw(p, Quarters.read(GSON, bad, quarters), null, bad);
			draw(p, Quarters.read(GSON, bad, null), null, bad);
		}
		for (String bad : damaged(quarters))
		{
			draw(p, Quarters.read(GSON, kits, bad), null, bad);
